    SUBST1_TAC THENL
   [EXPAND_TAC "tB" THEN AP_THM_TAC THEN AP_TERM_TAC THEN CONV_TAC WORD_BLAST;
    ALL_TAC] THEN
  CONV_TAC WORD_BLAST);;

