                `ct1:int128`; `ct2:int128`; `ct3:int128`;
                `q5:int128`; `q6:int128`; `q9_in:int128`;
                `q10_in:int128`; `q11_in:int128`; `q4_in:int128`;
                `q16:int128`]
               KERNEL_4BLOCK_NIST_BRIDGE_LASSOC) THEN
  ASM_REWRITE_TAC[] THEN
