                    (word_zx
                      (word_subword
                        (word_xor (aes_gcm_rev64_int128 q4_pre)
                                  (byteswap128 q11_pre))
                        (64,64) :64 word) :int128))
                  (0,64) :64 word)
                (word_subword
                  (word_zx (word_subword q17 (64,64) :64 word) :int128)
                  (0,64) :64 word) :int128)
              (word_pmul
                (word_subword
                  (word_xor
                    (word_zx (word_subword (aes_gcm_rev64_int128 q5_pre)
                                           (64,64) :64 word) :int128)
                    (aes_gcm_rev64_int128 q5_pre)) (0,64) :64 word)
