                                     :64 word) :64 word) :int128)
                   (64,64)
                   (word_subword
                     (word_subword
                       (word_zx
                         (word_xor
                           (word_subword (aes_gcm_rev64_int128 q6_pre) (0,64)
                                         :64 word)
                           (word_subword (aes_gcm_rev64_int128 q6_pre) (64,64)
                                         :64 word) :64 word) :int128)
                       (0,64) :64 word) (0,64) :64 word) :int128) (64,64)
                 :64 word)
               (word_subword q16 (64,64) :64 word) :int128) /\
          read Q11 s =
