              read Q23 s = rk5 /\
              read Q24 s = rk6 /\
              read Q25 s = rk7 /\
              read Q26 s = rk8 /\
              read Q31 s = rk9 /\
              read X9 s = sx9 /\
              read X10 s = sx10 /\
              read X13 s = sx13 /\
              read X14 s = sx14)
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_enc_kernel_mc /\
