    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_enc_kernel_mc /\
              read PC s = word (pc + 0x308) /\
              read X2 s = cptr /\
              read X0 s = x0_in /\
              read X5 s = x5_in /\
              read Q0 s = b0 /\
              read Q1 s = b1 /\
              read Q2 s = b2 /\
              read Q4 s = q4_pre /\
              read Q5 s = q5_pre /\
              read Q6 s = q6_pre /\
              read Q7 s = q7_pre /\
              read Q11 s = q11_pre /\
              read Q12 s = q12 /\
              read Q13 s = q13 /\
              read Q14 s = q14 /\
              read Q15 s = q15 /\
              read Q16 s = q16 /\
              read Q17 s = q17 /\
              read Q18 s = rk0 /\
              read Q19 s = rk1 /\
              read Q20 s = rk2 /\
              read Q21 s = rk3 /\
              read Q22 s = rk4 /\
              read Q23 s = rk5 /\
              read Q24 s = rk6 /\
              read Q25 s = rk7 /\
              read Q26 s = rk8 /\
              read Q31 s = rk9 /\
              read X9 s = sx9 /\
              read X10 s = sx10 /\
              read X13 s = sx13 /\
              read X14 s = sx14)
         (\s. read Q12 s = q12 /\
              read Q13 s = q13 /\
              read Q14 s = q14 /\
              read Q15 s = q15 /\
              read Q16 s = q16 /\
              read Q17 s = q17 /\
              read Q18 s = rk0 /\
              read Q19 s = rk1 /\
              read Q20 s = rk2 /\
              read Q21 s = rk3 /\
              read Q22 s = rk4 /\
              read Q23 s = rk5 /\
              read Q24 s = rk6 /\
              read Q25 s = rk7 /\
              read Q26 s = rk8 /\
              read Q31 s = rk9 /\
              read X10 s = sx10 /\
              read X13 s = sx13 /\
              read X14 s = sx14 /\
              aligned_bytes_loaded s (word pc) aes_gcm_enc_kernel_mc /\
              read PC s = word (pc + 0x5c4) /\
              read X0 s = word_add x0_in (word 64) /\
              read X2 s = word_add cptr (word 64) /\
              read X5 s = x5_in /\
              (read NF s <=>
               ival (word_sub (word_add x0_in (word 64)) x5_in) < &0) /\
              (read VF s <=>
               ~(ival (word_add x0_in (word 64)) - ival x5_in =
                 ival (word_sub (word_add x0_in (word 64)) x5_in))) /\
              read Q11 s = nist_ghash h prev_tag [ct0; ct1; ct2; ct3] /\
              (?(q1k:int128) (q2k:int128) (q3k:int128)
                (x19k:int64) (x20k:int64) (x21k:int64)
                (x22k:int64) (x23k:int64) (x24k:int64).
                 read Q5 s = (word_xor (aese q1k rk9)
                               (word_insert
                                 (word_zx x19k :int128)
                                 (64,64)
                                 (word_xor x20k sx14)) :int128) /\
                 read Q6 s = (word_xor (aese q2k rk9)
                               (word_insert
                                 (word_zx x21k :int128)
                                 (64,64)
                                 x22k) :int128) /\
                 read Q7 s = (word_xor (aese q3k rk9)
                               (word_insert
                                 (word_zx x23k :int128)
                                 (64,64)
                                 (word_xor x24k sx14)) :int128)) /\
              (?(c4:int128) (c5:int128) (c6:int128) (c7:int128).
                 read (memory :> bytes128 cptr) s = c4 /\
                 read (memory :> bytes128 (word_add cptr (word 16))) s = c5 /\
                 read (memory :> bytes128 (word_add cptr (word 32))) s = c6 /\
                 read (memory :> bytes128 (word_add cptr (word 48))) s = c7))
         (MAYCHANGE [PC] ,,
          MAYCHANGE [Q0; Q1; Q2; Q3; Q4; Q5; Q6; Q7; Q8; Q9; Q10; Q11] ,,
          MAYCHANGE [X0; X2; X6; X7; X9; X12; X19; X20; X21; X22; X23; X24] ,,
          MAYCHANGE SOME_FLAGS ,,
