       [EXISTS_TAC `APPEND (cts:int128 list) [ct0; ct1; ct2; ct3]` THEN
        EXISTS_TAC `read Q4 (s2:armstate)` THEN
        EXISTS_TAC `word_xor (aese (q1k:int128) (rk9:int128))
