  ENSURES_INIT_TAC "s0" THEN
  RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES;
                              fst AES_GCM_ENC_KERNEL_EXEC]) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[condition_semantics; LT_REFL]) THEN
  ARM_STEPS_TAC AES_GCM_ENC_KERNEL_EXEC [1] THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(MP_TAC o check (is_exists o concl)) THEN
  STRIP_TAC THEN
  EXISTS_TAC `cts:int128 list` THEN
  ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* Phase 11b G3 (s250) - debt-2 STEP 2c GT_128 Phase 2 Part B: the          *)
(* concrete-counter main-loop invariant wrapper.  Clone of                  *)
(* AES_GCM_MAIN_LOOP_WRAPPER_FULL_X12_CORRECT whose ENSURES_WHILE_PUP        *)
(* invariant additionally pins Q0/Q1/Q2 (and X11) to the i-indexed native   *)
(* counter blocks for blocks 4i+4/4i+5/4i+6 (cores base32 + (4i+K)), the     *)
(* loop-stable masked-counter sx11 threaded throughout.  PRE links          *)
(* sx12_base = base32 + 7 (X12 leads the block-4 counter field by 7 at the   *)
(* loop top).  The b0/b1/b2 existentials for Q0/Q1/Q2 are removed; the body  *)
(* consumes the s250 Part-A 6th CTR cut FULL_LOADED_X12_CTR.                 *)
(* ========================================================================= *)

let AES_GCM_MAIN_LOOP_WRAPPER_FULL_X12_CTR_CORRECT = prove
 (`!pc (cptr:int64) (x0_init:int64) (x5_init:int64) (N:num)
       (h:int128) (initial_tag:int128)
       (q12:int128) (q13:int128) (q14:int128) (q15:int128)
       (q16:int128) (q17:int128)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128) (rk4:int128)
       (rk5:int128) (rk6:int128) (rk7:int128) (rk8:int128) (rk9:int128)
       (sx10:int64) (sx11:int64) (sx13:int64) (sx14:int64)
