             read X14 s = sx14 /\
             read Q1 s = q1_in /\
             read Q2 s = q2_in /\
             read Q3 s = q3_in /\
             read Q5 s = word_xor q0_in
                          (word_insert
                            (word_zx (word_xor b0_lo sx13):int128)
                            (64,64)
                            (word_xor b0_hi sx14)) /\
             read Q8 s = byteswap128 q11_in /\
             read Q10 s = q10_in /\
             read Q12 s = q12_in /\
             read Q13 s = q13_in /\
             read Q14 s = q14_in /\
             read Q15 s = q15_in /\
             read Q16 s = q16_in /\
             read Q17 s = q17_in)
        (MAYCHANGE [PC; X0; X5; X6; X7] ,,
         MAYCHANGE [Q4; Q5; Q8] ,,
         MAYCHANGE SOME_FLAGS ,,
         MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES;
                              fst AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC]) THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  (* Cut 1: OPENING (slice 129..133, s0 -> s5) *)
  MP_TAC(SPECL[`pc:num`; `q11_in:int128`; `sx0:int64`; `sx4:int64`;
               `sx13:int64`; `sx14:int64`;
               `b0_lo:int64`; `b0_hi:int64`]
              AES_GCM_LENC_TAIL_OPENING_CORRECT) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[NONOVERLAPPING_CLAUSES;
                fst AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC] THEN
    NONOVERLAPPING_TAC;
    ALL_TAC] THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s5" THEN
  (* Cut 2: CMP30_FMOV_Q4Q5 (slice 134..137, s5 -> s9) *)
  MP_TAC(REWRITE_RULE[SOME_FLAGS]
          (SPECL[`pc:num`; `q0_in:int128`;
                 `read Q4 (s5:armstate):int128`;
                 `word_sub (sx4:int64) (sx0:int64) :int64`;
                 `word_xor (b0_lo:int64) (sx13:int64) :int64`;
                 `word_xor (b0_hi:int64) (sx14:int64) :int64`]
                AES_GCM_LENC_TAIL_CMP30_FMOV_Q4Q5_CORRECT)) THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s9" THEN
  (* Cut 3: BGT4_TAKEN (slice 138, s9 -> s10) *)
  MP_TAC(SPECL[`pc:num`; `word_sub (sx4:int64) (sx0:int64) :int64`]
              AES_GCM_LENC_TAIL_BGT_BLOCKS4_CORRECT) THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s10" THENL
   [MATCH_MP_TAC CMP_GT_BRIDGE_48 THEN
    EXISTS_TAC `word_sub (sx4:int64) (sx0:int64) :int64` THEN
    ASM_REWRITE_TAC[] THEN ASM_INT_ARITH_TAC;
    ALL_TAC] THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s071) — Lenc_blocks_3_remaining first 5 instructions cut.        *)
(*                                                                           *)
(* Slice instr indices 169..173, kernel offsets 0x868..0x878 (5 instr).      *)
(* Entry point of `.Lenc_blocks_3_remaining`; reachable from blocks_4's     *)
(* exit OR from the b.gt at slice 146 (when 32 < val sx5 ≤ 48).             *)
(*                                                                           *)
(*   0x868  arm_ST1_VEC      Q5 X2 16          ; store CT block 5            *)
(*   0x86c  arm_LDP          X6 X7 X0 16       ; load PT block 6             *)
(*   0x870  arm_REV64_VEC    Q4 Q5 8           ; GHASH PRE block-3: byterev *)
(*                                              ;   (note: when entered     *)
(*                                              ;    from blocks_4, Q5 is  *)
(*                                              ;    the freshly built CT   *)
(*                                              ;    block 5 = Q4_pre XOR  *)
(*                                              ;    Q1_in)                 *)
(*   0x874  arm_EOR          X6 X6 X13         ; X6 ^= rk10_lo               *)
(*   0x878  arm_EOR_VEC      Q4 Q4 Q8 128      ; v4 ^= partial tag Q8       *)
(*                                                                           *)
(* Structurally identical to BLOCKS4_ST_LD_REV_EOR; just at a different     *)
(* PC entry point (pc + 0x2a0 vs pc + 0x260).  Same proof tactic.           *)
(*                                                                           *)
(* Note: when entered from blocks_4, Q8 = 0 (cleared by blocks_4's `movi   *)
(* v8.8b, #0` at slice 163).  When entered directly from the b.gt blocks_3 *)
(* branch, Q8 = byteswap128 q11_in (the OPENING value) since none of the   *)
(* fall-through path setup touches Q8.  This cut takes Q8 as q8_pre        *)
(* parameter without committing to which case applies.                      *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS3_ST_LD_REV_EOR_CORRECT = prove
 (`!pc (cptr:int64) (sx0:int64) (sx13:int64) (sx14:int64)
       (q5_pre:int128) (q8_pre:int128)
       (b1_lo:int64) (b1_hi:int64).
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (cptr, 16) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (sx0, 16) /\
   nonoverlapping (cptr, 16) (sx0, 16)
   ==> ensures arm
        (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
             read PC s = word (pc + 0x2a0) /\
             read X0 s = sx0 /\
             read X2 s = cptr /\
             read X13 s = sx13 /\
             read X14 s = sx14 /\
             read Q5 s = q5_pre /\
             read Q8 s = q8_pre /\
             read (memory :> bytes64 sx0) s = b1_lo /\
             read (memory :> bytes64 (word_add sx0 (word 8))) s = b1_hi)
        (\s. read PC s = word (pc + 0x2b4) /\
             read X0 s = word_add sx0 (word 16) /\
             read X2 s = word_add cptr (word 16) /\
             read X6 s = word_xor b1_lo sx13 /\
             read X7 s = b1_hi /\
             read X13 s = sx13 /\
             read X14 s = sx14 /\
             read Q4 s = word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre /\
             read Q5 s = q5_pre /\
             read Q8 s = q8_pre /\
             read (memory :> bytes128 cptr) s = q5_pre)
        (MAYCHANGE [PC; X0; X2; X6; X7] ,,
         MAYCHANGE [Q4] ,,
         MAYCHANGE [memory :> bytes128 cptr] ,,
         MAYCHANGE [events])`,
  REWRITE_TAC[fst AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC (169--173) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN
  TRY (REWRITE_TAC[aes_gcm_rev64_int128] THEN
       ASM_REWRITE_TAC[] THEN CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_RULE));;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s071) — Lenc_blocks_3_remaining second batch (rest of arm).      *)
(*                                                                           *)
(* Slice instr indices 174..186, kernel offsets 0x87c..0x8ac (13 instr).     *)
(* Continues from BLOCKS3_ST_LD_REV_EOR's exit (pc + 0x2b4) and exits at    *)
(* pc + 0x2e8 (= kernel 0x8b0 = .Lenc_blocks_2_remaining).                   *)
(*                                                                           *)
(* Structurally analogous to BLOCKS4_PMULL_MIDLOWHIGH but with two key      *)
(* differences:                                                              *)
(*   1. Uses Q14 (= byteswap128 (h_power 2) = H_3) instead of Q15 (H_4)     *)
(*      for the GHASH PMULLs.                                                *)
(*   2. ACCUMULATES into Q9/Q10/Q11 (Q9 += block-3 HIGH, Q11 += block-3 LOW,*)
(*      Q10 += block-3 MID via subsequent EOR_VECs) instead of overwriting. *)
(*   3. The MID PMULL uses Q17.lo (= karatsuba_mid h^2) directly via       *)
(*      `pmull v22, v22, v17` — no intermediate `mov d10, v17.d[1]` setup. *)
(*   4. Block-6 plaintext is XOR'd against Q2 (the AES output for block-6).*)
(*                                                                           *)
(* The cut commits POST values for the GHASH HIGH/LOW accumulators (Q9     *)
(* and Q11) but defers Q10 (the MID accumulator), Q5 (the next-block CT), *)
(* and Q22 to MAYCHANGE — they're staging values consumed by the next arm.*)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS3_PMULL_ACCUM_CORRECT = prove
 (`!pc (sx14:int64) (x6_post:int64) (x7_pre:int64)
       (q2_in:int128) (q4_in:int128) (q5_in:int128)
       (q9_in:int128) (q10_in:int128) (q11_in:int128)
       (q14_in:int128) (q17_in:int128).
   ensures arm
    (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
         read PC s = word (pc + 0x2b4) /\
         read X6 s = x6_post /\
         read X7 s = x7_pre /\
         read X14 s = sx14 /\
         read Q2 s = q2_in /\
         read Q4 s = q4_in /\
         read Q5 s = q5_in /\
         read Q9 s = q9_in /\
         read Q10 s = q10_in /\
         read Q11 s = q11_in /\
         read Q14 s = q14_in /\
         read Q17 s = q17_in)
    (\s. read PC s = word (pc + 0x2e8) /\
         read X6 s = x6_post /\
         read X7 s = word_xor x7_pre sx14 /\
         read X14 s = sx14 /\
         read Q2 s = q2_in /\
         read Q9 s = word_xor q9_in
                       (word_pmul (word_subword q4_in (64,64):int64)
                                  (word_subword q14_in (64,64):int64) :int128) /\
         read Q11 s = word_xor q11_in
                        (word_pmul (word_subword q4_in (0,64):int64)
                                   (word_subword q14_in (0,64):int64) :int128) /\
         read Q14 s = q14_in /\
         read Q17 s = q17_in)
    (MAYCHANGE [PC] ,,
     MAYCHANGE [X7] ,,
     MAYCHANGE [Q5; Q8; Q9; Q10; Q11; Q20; Q21; Q22])`,
  REPEAT GEN_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC (174--186) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN
  TRY (CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_RULE));;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s072) — Lenc_blocks_2_remaining first batch (ST/LD/REV/EOR).     *)
(*                                                                           *)
(* Slice instr indices 187..191, kernel offsets 0x8b0..0x8c0 (5 instr).      *)
(* Mirrors BLOCKS3_ST_LD_REV_EOR but the instruction *order* differs and    *)
(* the `movi v8.8b, #0` (clearing Q8) is part of THIS cut (in blocks_3 the *)
(* movi happens later, in the PMULL_ACCUM cut).                              *)
(*                                                                           *)
(*   0x8b0  st1   {v5.16b}, [x2], #16     ; store CT block, X2 += 16        *)
(*   0x8b4  rev64 v4.16b, v5.16b          ; Q4 := rev64(Q5)                 *)
(*   0x8b8  ldp   x6, x7, [x0], #16       ; load PT block, X0 += 16         *)
(*   0x8bc  eor   v4.16b, v4.16b, v8.16b  ; Q4 := Q4 XOR Q8 (feed prev tag) *)
(*   0x8c0  movi  v8.8b, #0               ; Q8 := 0 (suppress further feed) *)
(*                                                                           *)
(* The cut commits Q8 = (word 0:int128) so downstream cuts (blocks_1's      *)
(* eor v4, v4, v8 at kernel 0x900) can use the constant value.              *)
(* The b1_lo/b1_hi loads are NOT XORed with sx13/sx14 yet (those happen at *)
(* slice 192/195 in the PMULL ACCUM cut).                                   *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS2_ST_LD_REV_EOR_CORRECT = prove
 (`!pc (cptr:int64) (sx0:int64) (sx13:int64) (sx14:int64)
       (q5_pre:int128) (q8_pre:int128)
       (b1_lo:int64) (b1_hi:int64).
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (cptr, 16) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (sx0, 16) /\
   nonoverlapping (cptr, 16) (sx0, 16)
   ==> ensures arm
        (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
             read PC s = word (pc + 0x2e8) /\
             read X0 s = sx0 /\
             read X2 s = cptr /\
             read X13 s = sx13 /\
             read X14 s = sx14 /\
             read Q5 s = q5_pre /\
             read Q8 s = q8_pre /\
             read (memory :> bytes64 sx0) s = b1_lo /\
             read (memory :> bytes64 (word_add sx0 (word 8))) s = b1_hi)
        (\s. read PC s = word (pc + 0x2fc) /\
             read X0 s = word_add sx0 (word 16) /\
             read X2 s = word_add cptr (word 16) /\
             read X6 s = b1_lo /\
             read X7 s = b1_hi /\
             read X13 s = sx13 /\
             read X14 s = sx14 /\
             read Q4 s = word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre /\
             read Q5 s = q5_pre /\
             read Q8 s = (word 0:int128) /\
             read (memory :> bytes128 cptr) s = q5_pre)
        (MAYCHANGE [PC; X0; X2; X6; X7] ,,
         MAYCHANGE [Q4; Q8] ,,
         MAYCHANGE [memory :> bytes128 cptr] ,,
         MAYCHANGE [events])`,
  REWRITE_TAC[fst AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC (187--191) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN
  TRY (REWRITE_TAC[aes_gcm_rev64_int128] THEN
       ASM_REWRITE_TAC[] THEN CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_RULE));;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s072) — Lenc_blocks_2_remaining second batch (PMULL ACCUM).      *)
(*                                                                           *)
(* Slice instr indices 192..205, kernel offsets 0x8c4..0x8f8 (14 instr).     *)
(* Continues from BLOCKS2_ST_LD_REV_EOR's exit (pc + 0x2fc) and exits at    *)
(* pc + 0x334 (= kernel 0x8fc = .Lenc_blocks_1_remaining).                   *)
(*                                                                           *)
(* Three structural differences from BLOCKS3_PMULL_ACCUM:                    *)
(*   1. Uses Q13 (= byteswap128 (h_power 1) = H_2) instead of Q14.          *)
(*   2. The MID PMULL is `pmull2 v22.1q, v22.2d, v16.2d` after an `ins      *)
(*      v22.d[1], v22.d[0]` (lane duplication), so the multiply uses        *)
(*      Q22.hi (= duplicated low) × Q16.hi rather than Q22.lo × Q17.lo.    *)
(*      The semantic value `pmull(Q4.hi XOR Q4.lo, Q16.hi)` matches the    *)
(*      `karatsuba_mid h^1` factor needed for block-position 5 GHASH.       *)
(*   3. Builds Q5 := word_xor (word_join (X7^sx14) (X6^sx13)) Q3 — one     *)
(*      AES output ready for ST1 in the blocks_1 path's tail or the        *)
(*      common finalization's last `st1 {v5.16b}, [x2]` at kernel 0x954.   *)
(*                                                                           *)
(* The cut commits POST values for Q5 (the next CT block staged for the    *)
(* final store), Q9 (HIGH GHASH accumulator) and Q11 (LOW GHASH             *)
(* accumulator).  Q10 (MID accumulator), Q22, Q20, Q21 are deferred to     *)
(* MAYCHANGE — they're staging values either consumed by blocks_1 (Q10    *)
(* via `eor v10, v10, v8` at kernel 0x924) or only matter via the          *)
(* downstream MODULO fold's accumulation that this cut does not touch.    *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS2_PMULL_ACCUM_CORRECT = prove
 (`!pc (sx13:int64) (sx14:int64) (b1_lo:int64) (b1_hi:int64)
       (q3_in:int128) (q4_in:int128) (q5_in:int128)
       (q9_in:int128) (q10_in:int128) (q11_in:int128)
       (q13_in:int128) (q16_in:int128).
   ensures arm
    (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
         read PC s = word (pc + 0x2fc) /\
         read X6 s = b1_lo /\
         read X7 s = b1_hi /\
         read X13 s = sx13 /\
         read X14 s = sx14 /\
         read Q3 s = q3_in /\
         read Q4 s = q4_in /\
         read Q5 s = q5_in /\
         read Q9 s = q9_in /\
         read Q10 s = q10_in /\
         read Q11 s = q11_in /\
         read Q13 s = q13_in /\
         read Q16 s = q16_in)
    (\s. read PC s = word (pc + 0x334) /\
         read X6 s = word_xor b1_lo sx13 /\
         read X7 s = word_xor b1_hi sx14 /\
         read X13 s = sx13 /\
         read X14 s = sx14 /\
         read Q3 s = q3_in /\
         read Q4 s = q4_in /\
         read Q5 s = word_xor (word_join (word_xor b1_hi sx14:int64)
                                         (word_xor b1_lo sx13:int64) :int128)
                              q3_in /\
         read Q9 s = word_xor q9_in
                       (word_pmul (word_subword q4_in (64,64):int64)
                                  (word_subword q13_in (64,64):int64) :int128) /\
         read Q11 s = word_xor q11_in
                        (word_pmul (word_subword q4_in (0,64):int64)
                                   (word_subword q13_in (0,64):int64) :int128) /\
         read Q13 s = q13_in /\
         read Q16 s = q16_in)
    (MAYCHANGE [PC] ,,
     MAYCHANGE [X6; X7] ,,
     MAYCHANGE [Q5; Q9; Q10; Q11; Q20; Q21; Q22])`,
  REPEAT GEN_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC (192--205) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN
  TRY (CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_RULE));;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s072) — Lenc_blocks_1_remaining REV+EOR cut.                     *)
(*                                                                           *)
(* Slice instr indices 206..207, kernel offsets 0x8fc..0x900 (2 instr).     *)
(*                                                                           *)
(*   0x8fc  rev64 v4.16b, v5.16b          ; Q4 := rev64(Q5)                 *)
(*   0x900  eor   v4.16b, v4.16b, v8.16b  ; Q4 := Q4 XOR Q8 (feed prev tag) *)
(*                                                                           *)
(* Mirrors the rev64+eor pair at the start of blocks_2/3/4's first batch    *)
(* but blocks_1 has NO ST1 / LDP — there's no plaintext to load and no     *)
(* ciphertext to store yet (last block's CT is still in Q5; final store    *)
(* happens in the common finalization region at kernel 0x954).              *)
(*                                                                           *)
(* Split out as its own cut so the downstream PMULL absorption cut can      *)
(* take a clean q4_in parameter (rather than threading                       *)
(* `aes_gcm_rev64_int128 q5_pre` through the proof's WORD_BLAST barrier).   *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS1_REV_EOR_CORRECT = prove
 (`!pc (q5_pre:int128) (q8_pre:int128).
   ensures arm
    (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
         read PC s = word (pc + 0x334) /\
         read Q5 s = q5_pre /\
         read Q8 s = q8_pre)
    (\s. read PC s = word (pc + 0x33c) /\
         read Q4 s = word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre /\
         read Q5 s = q5_pre /\
         read Q8 s = q8_pre)
    (MAYCHANGE [PC] ,, MAYCHANGE [Q4])`,
  REPEAT GEN_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC (206--207) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN
  TRY (REWRITE_TAC[aes_gcm_rev64_int128] THEN
       ASM_REWRITE_TAC[] THEN CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_RULE));;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s072) — Lenc_blocks_1_remaining PMULL absorption cut.            *)
(*                                                                           *)
(* Slice instr indices 208..216, kernel offsets 0x904..0x924 (9 instr).      *)
(* Continues from BLOCKS1_REV_EOR's exit (pc + 0x33c) and exits at          *)
(* pc + 0x360 (= kernel 0x928 = `movi v8.8b, #0xc2` — start of MODULO).     *)
(*                                                                           *)
(*   0x904  pmull2 v20, v4.2d, v12.2d     ; Q20 := PMULL2 HIGH               *)
(*   0x908  mov   d8, v4.d[1]             ; Q8 := dup_low(Q4.hi)             *)
(*   0x90c  rev   w9, w12                 ; W9 := bytereverse(W12)           *)
(*   0x910  pmull v21, v4.1d, v12.1d      ; Q21 := PMULL LOW                 *)
(*   0x914  eor   v9, v9, v20             ; Q9 += HIGH                       *)
(*   0x918  eor   v8, v8, v4 (8b)         ; Q8.lo := Q4.hi XOR Q4.lo         *)
(*   0x91c  pmull v8, v8, v16             ; Q8 := PMULL(Q4.hi^Q4.lo, Q16.lo)*)
(*   0x920  eor   v11, v11, v21           ; Q11 += LOW                       *)
(*   0x924  eor   v10, v10, v8            ; Q10 += MID                       *)
(*                                                                           *)
(* Q12 = byteswap128 (h_power 0) = H_1 (block-position 6 H-power for the    *)
(* final residual block).  Q16.lo = karatsuba_mid h^0 (the middle Karatsuba *)
(* factor for the same H-power).                                             *)
(*                                                                           *)
(* The cut commits POST values for X9 (counter-store-ready), Q9 (HIGH       *)
(* accumulator) and Q11 (LOW accumulator).  Q10, Q8, Q20, Q21 are deferred  *)
(* to MAYCHANGE — Q10 (MID accumulator) is consumed by the MODULO fold's    *)
(* `eor v10, v10, v4` and `eor v10, v10, v7` chain, but the value of Q10    *)
(* at this cut's exit is part of the larger MODULO computation captured     *)
(* by the next cut.                                                          *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS1_PMULL_ABSORB_CORRECT = prove
 (`!pc (sx12:int32)
       (q4_in:int128) (q9_in:int128) (q10_in:int128) (q11_in:int128)
       (q12_in:int128) (q16_in:int128).
   ensures arm
    (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
         read PC s = word (pc + 0x33c) /\
         read X12 s = word_zx sx12 /\
         read Q4 s = q4_in /\
         read Q9 s = q9_in /\
         read Q10 s = q10_in /\
         read Q11 s = q11_in /\
         read Q12 s = q12_in /\
         read Q16 s = q16_in)
    (\s. read PC s = word (pc + 0x360) /\
         read X9 s = word_zx (word_bytereverse sx12) /\
         read X12 s = word_zx sx12 /\
         read Q4 s = q4_in /\
         read Q9 s = word_xor q9_in
                       (word_pmul (word_subword q4_in (64,64):int64)
                                  (word_subword q12_in (64,64):int64) :int128) /\
         read Q11 s = word_xor q11_in
                        (word_pmul (word_subword q4_in (0,64):int64)
                                   (word_subword q12_in (0,64):int64) :int128) /\
         read Q12 s = q12_in /\
         read Q16 s = q16_in)
    (MAYCHANGE [PC; X9] ,,
     MAYCHANGE [Q8; Q9; Q10; Q11; Q20; Q21])`,
  REPEAT GEN_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC (208--216) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN
  TRY (CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_RULE));;

(* ------------------------------------------------------------------------- *)
(* Phase 9b (s079) — BLOCKS1_PMULL_ABSORB variant exposing Q10 closed form.  *)
(*                                                                           *)
(* Same instructions as BLOCKS1_PMULL_ABSORB_CORRECT (slice 208..216), but   *)
(* POST adds Q10 closed form:                                                *)
(*   Q10_after_absorb = word_xor q10_in (word_pmul                           *)
(*     (word_subword (word_zx (word_subword                                  *)
(*        (word_xor q4_in (word_zx (word_subword q4_in (64,64) :int64)       *)
(*                                  :int128)) (0,64) :int64) :int128)        *)
(*        (0,64) :int64)                                                     *)
(*     (word_subword q16_in (0,64) :int64) :int128).                         *)
(*                                                                           *)
(* The simulator's emit form for the `mov d8, v4.d[1]; eor v8, v8, v4 (8b);  *)
(* pmull v8, v8, v16` chain is verbose: the intermediate `mov d8, v4.d[1]`   *)
(* zero-extends the high 64 of q4 to 128 bits, then `eor v8, v4 (8b)` XORs   *)
(* with the low 8-byte slice (clearing high 64 bits in the 8b variant), and  *)
(* finally `pmull v8, v8, v16` is a 64×64→128 polynomial multiply.           *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS1_PMULL_ABSORB_Q10_CORRECT = prove
 (`!pc (sx12:int32)
       (q4_in:int128) (q9_in:int128) (q10_in:int128) (q11_in:int128)
       (q12_in:int128) (q16_in:int128).
   ensures arm
    (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
         read PC s = word (pc + 0x33c) /\
         read X12 s = word_zx sx12 /\
         read Q4 s = q4_in /\
         read Q9 s = q9_in /\
         read Q10 s = q10_in /\
         read Q11 s = q11_in /\
         read Q12 s = q12_in /\
         read Q16 s = q16_in)
    (\s. read PC s = word (pc + 0x360) /\
         read X9 s = word_zx (word_bytereverse sx12) /\
         read X12 s = word_zx sx12 /\
         read Q4 s = q4_in /\
         read Q9 s = word_xor q9_in
                       (word_pmul (word_subword q4_in (64,64):int64)
                                  (word_subword q12_in (64,64):int64) :int128) /\
         read Q10 s = word_xor q10_in
                        (word_pmul (word_subword
                                     (word_zx (word_subword
                                                (word_xor q4_in
                                                  (word_zx (word_subword q4_in
                                                              (64,64):int64) :int128))
                                                (0,64):int64) :int128)
                                     (0,64):int64)
                                   (word_subword q16_in (0,64):int64) :int128) /\
         read Q11 s = word_xor q11_in
                        (word_pmul (word_subword q4_in (0,64):int64)
                                   (word_subword q12_in (0,64):int64) :int128) /\
         read Q12 s = q12_in /\
         read Q16 s = q16_in)
    (MAYCHANGE [PC; X9] ,,
     MAYCHANGE [Q8; Q9; Q10; Q11; Q20; Q21])`,
  REPEAT GEN_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC (208--216) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN
  TRY (CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_RULE));;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s072) — Lenc_blocks_1_remaining MODULO fold cut.                 *)
(*                                                                           *)
(* Slice instr indices 217..226, kernel offsets 0x928..0x94c (10 instr).    *)
(* Continues from BLOCKS1_PMULL_ABSORB's exit (pc + 0x360) and exits at    *)
(* pc + 0x388 (= kernel 0x950 = `str w9, [x16, #12]`, common finalization).*)
(*                                                                           *)
(*   0x928  movi  v8.8b, #0xc2            ; Q8.lo := 0xc2 (low byte)        *)
(*   0x92c  eor   v4, v11, v9             ; Q4 := Q11 XOR Q9 (Karatsuba)    *)
(*   0x930  shl   d8, d8, #56             ; Q8.lo := 0xc2 << 56 (mod const) *)
(*   0x934  eor   v10, v10, v4            ; Q10 ^= Q4 (Karatsuba tidy)      *)
(*   0x938  pmull v7, v9.1d, v8.1d        ; Q7 := pmull(Q9.lo, Q8.lo)       *)
(*   0x93c  ext   v9, v9, v9, #8          ; Q9 := swap halves               *)
(*   0x940  eor   v10, v10, v7            ; Q10 ^= Q7 (fold)                *)
(*   0x944  eor   v10, v10, v9            ; Q10 ^= swapped-Q9 (fold)        *)
(*   0x948  pmull v9, v10.1d, v8.1d       ; Q9 := pmull(Q10.lo, Q8.lo)      *)
(*   0x94c  ext   v10, v10, v10, #8       ; Q10 := swap halves              *)
(*                                                                           *)
(* This is the GF(2^128) reduction (POLYVAL/GHASH MODULO step) folding the *)
(* Karatsuba-laid-out high/mid/low (Q9/Q10/Q11) into the form expected by  *)
(* the final st1 v11 tag-store path.  The cut commits Q11 and Q5 are       *)
(* preserved (Q11 is read by `eor v4, v11, v9` but never written here;    *)
(* Q5 is untouched).  Q9, Q10, Q4, Q7, Q8 go in MAYCHANGE — the downstream*)
(* finalization cut reads their post-MODULO values via the chain          *)
(* composition's ARM_BIGSTEP propagation.                                  *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS1_MODULO_CORRECT = prove
 (`!pc (q5_in:int128) (q9_in:int128) (q10_in:int128) (q11_in:int128).
   ensures arm
    (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
         read PC s = word (pc + 0x360) /\
         read Q5 s = q5_in /\
         read Q9 s = q9_in /\
         read Q10 s = q10_in /\
         read Q11 s = q11_in)
    (\s. read PC s = word (pc + 0x388) /\
         read Q5 s = q5_in /\
         read Q11 s = q11_in)
    (MAYCHANGE [PC] ,,
     MAYCHANGE [Q4; Q7; Q8; Q9; Q10])`,
  REPEAT GEN_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC (217--226) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Phase 9b (s079) — BLOCKS1_MODULO variant exposing post-MODULO Q9/Q10.     *)
(*                                                                           *)
(* Same instructions as BLOCKS1_MODULO_CORRECT (slice 217..226, kernel       *)
(* offsets 0x928..0x94c = pc+0x360..pc+0x388) but POST exposes the           *)
(* algebraic forms of Q9 and Q10 at exit.  Eliminates the Hilbert-style      *)
(* `read Q9 s` / `read Q10 s` placeholders that BLOCKS1_FINALIZATION_FULL   *)
(* was forced to use because BLOCKS1_FULL's POST left Q9/Q10 as MAYCHANGE.  *)
(*                                                                           *)
(* Define M = swap_halves(q9_in)                                             *)
(*           XOR pmull(q9_in.lo, 0xc200000000000000)                          *)
(*           XOR q9_in XOR q11_in XOR q10_in.                                *)
(* Then:                                                                     *)
(*   Q9_post  = pmull(M.lo, 0xc200000000000000)                              *)
(*   Q10_post = swap_halves(M)                                               *)
(*                                                                           *)
(* (0xc200000000000000 = word 13979173243358019584 — the GHASH polynomial   *)
(* reduction constant.  swap_halves of an int128 v is                        *)
(* `word_subword (word_join v v :int256) (64,128)`, the simulator's emit     *)
(* form for the `ext v.16b, v.16b, v.16b, #8` instruction.)                  *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS1_MODULO_Q9_Q10_CORRECT = prove
 (`!pc (q5_in:int128) (q9_in:int128) (q10_in:int128) (q11_in:int128).
   ensures arm
    (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
         read PC s = word (pc + 0x360) /\
         read Q5 s = q5_in /\
         read Q9 s = q9_in /\
         read Q10 s = q10_in /\
         read Q11 s = q11_in)
    (\s. read PC s = word (pc + 0x388) /\
         read Q5 s = q5_in /\
         read Q11 s = q11_in /\
         read Q9 s =
           word_pmul (word_subword
             (word_xor (word_subword (word_join (q9_in:int128) q9_in :int256)
                                     (64,128) :int128)
                       (word_xor (word_pmul (word_subword q9_in (0,64):int64)
                                            (word 13979173243358019584:int64)
                                            :int128)
                                 (word_xor (word_xor q9_in q11_in) q10_in)))
             (0,64):int64)
             (word 13979173243358019584:int64) :int128 /\
         read Q10 s =
           (word_subword (word_join
             (word_xor (word_subword (word_join (q9_in:int128) q9_in :int256)
                                     (64,128) :int128)
                       (word_xor (word_pmul (word_subword q9_in (0,64):int64)
                                            (word 13979173243358019584:int64)
                                            :int128)
                                 (word_xor (word_xor q9_in q11_in) q10_in)))
             (word_xor (word_subword (word_join q9_in q9_in :int256)
                                     (64,128) :int128)
                       (word_xor (word_pmul (word_subword q9_in (0,64):int64)
                                            (word 13979173243358019584:int64)
                                            :int128)
                                 (word_xor (word_xor q9_in q11_in) q10_in)))
             :int256) (64,128) :int128))
    (MAYCHANGE [PC] ,,
     MAYCHANGE [Q4; Q7; Q8; Q9; Q10])`,
  REPEAT GEN_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC (217--226) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s072) — Lenc_tail finalization cut.                              *)
(*                                                                           *)
(* Slice instr indices 227..234, kernel offsets 0x950..0x96c (8 instr).      *)
(* The common finalization region — reached from all four blocks_N arms     *)
(* via fallthrough — performs the final stores and Q11 byteswap.             *)
(*                                                                           *)
(*   0x950  str   w9, [x16, #12]          ; store updated counter to ivec  *)
(*   0x954  st1   {v5.16b}, [x2]          ; store last CT block (no #16!)  *)
(*   0x958  eor   v11, v11, v9            ; Q11 ^= Q9                       *)
(*   0x95c  eor   v11, v11, v10           ; Q11 ^= Q10                      *)
(*   0x960  ext   v11, v11, v11, #8       ; Q11 := swap halves              *)
(*   0x964  rev64 v11, v11                ; Q11 := rev64(Q11)               *)
(*   0x968  mov   x0, x15                 ; X0 := X15 (return value)        *)
(*   0x96c  st1   {v11.16b}, [x3]         ; store final tag at Xi pointer  *)
(*                                                                           *)
(* The cut takes the post-MODULO state's Q9, Q10, Q11 as parameters and    *)
(* commits memory writes:                                                    *)
(*   - 4 bytes at x16+12: low 32 bits of W9 (= bytereversed counter).       *)
(*   - 16 bytes at x2  : Q5 (last CT block).                                *)
(*   - 16 bytes at x3  : aes_gcm_rev64_int128 of swap-halves(Q11^Q9^Q10)   *)
(*     (the final NIST GHASH tag in NIST byte order).                       *)
(*                                                                           *)
(* X0 := X15 (the saved input-end pointer is moved into the C-return       *)
(* register as the kernel's return value — number of plaintext bytes        *)
(* processed).                                                              *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_FINALIZATION_CORRECT = prove
 (`!pc (sx9:int64) (sx15:int64) (sx16:int64) (cptr:int64) (xiptr:int64)
       (q5_in:int128) (q9_in:int128) (q10_in:int128) (q11_in:int128).
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (cptr, 16) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (xiptr, 16) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc)
                  (word_add sx16 (word 12), 4) /\
   nonoverlapping (cptr, 16) (xiptr, 16) /\
   nonoverlapping (cptr, 16) (word_add sx16 (word 12), 4) /\
   nonoverlapping (xiptr, 16) (word_add sx16 (word 12), 4)
   ==> ensures arm
        (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
             read PC s = word (pc + 0x388) /\
             read X9 s = sx9 /\
             read X15 s = sx15 /\
             read X16 s = sx16 /\
             read X2 s = cptr /\
             read X3 s = xiptr /\
             read Q5 s = q5_in /\
             read Q9 s = q9_in /\
             read Q10 s = q10_in /\
             read Q11 s = q11_in)
        (\s. read PC s = word (pc + 0x3a8) /\
             read X0 s = sx15 /\
             read X9 s = sx9 /\
             read X15 s = sx15 /\
             read X16 s = sx16 /\
             read X2 s = cptr /\
             read X3 s = xiptr /\
             read Q5 s = q5_in /\
             read (memory :> bytes32 (word_add sx16 (word 12))) s =
                  word_subword sx9 (0,32):int32 /\
             read (memory :> bytes128 cptr) s = q5_in /\
             read (memory :> bytes128 xiptr) s =
                  aes_gcm_rev64_int128
                    (word_join (word_subword
                                 (word_xor (word_xor q11_in q9_in) q10_in)
                                 (0,64):int64)
                               (word_subword
                                 (word_xor (word_xor q11_in q9_in) q10_in)
                                 (64,64):int64) :int128))
        (MAYCHANGE [PC; X0] ,,
         MAYCHANGE [Q11] ,,
         MAYCHANGE [memory :> bytes128 cptr;
                    memory :> bytes128 xiptr] ,,
         MAYCHANGE [memory :> bytes32 (word_add sx16 (word 12))] ,,
         MAYCHANGE [events])`,
  REWRITE_TAC[fst AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC (227--234) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN
  TRY (REWRITE_TAC[aes_gcm_rev64_int128] THEN
       ASM_REWRITE_TAC[] THEN CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_RULE));;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s073) — Lenc_blocks_4_remaining FULL chain composition.          *)
(*                                                                           *)
(* Composes BLOCKS4_ST_LD_REV_EOR (slice 153..157) +                         *)
(* BLOCKS4_PMULL_MIDLOWHIGH (slice 158..168) into a single ensures over the *)
(* full blocks_4 arm body (slice 153..168, kernel offsets 0x828..0x864,     *)
(* 16 instructions).  Entry PC is pc + 0x260, exit PC is pc + 0x2a0         *)
(* (= entry of blocks_3_remaining).  Uses the standard ARM_BIGSTEP chain    *)
(* composition recipe from s061.                                             *)
(*                                                                           *)
(* Postcondition exposes Q9 and Q11 with the full block-4 PMULL HIGH and    *)
(* LOW values (folding the rev64+eor of q5_pre+q8_pre through to the GHASH  *)
(* multiplication directly), matching what subsequent blocks_3 PMULL ACCUM  *)
(* will accumulate against.                                                  *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS4_FULL_CORRECT = prove
 (`!pc (cptr:int64) (sx0:int64) (sx13:int64) (sx14:int64)
       (q1_in:int128) (q5_pre:int128) (q8_pre:int128)
       (q10_in:int128) (q15_in:int128) (q17_in:int128)
       (b1_lo:int64) (b1_hi:int64).
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (cptr, 16) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (sx0, 16) /\
   nonoverlapping (cptr, 16) (sx0, 16)
   ==> ensures arm
        (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
             read PC s = word (pc + 0x260) /\
             read X0 s = sx0 /\
             read X2 s = cptr /\
             read X13 s = sx13 /\
             read X14 s = sx14 /\
             read Q1 s = q1_in /\
             read Q5 s = q5_pre /\
             read Q8 s = q8_pre /\
             read Q10 s = q10_in /\
             read Q15 s = q15_in /\
             read Q17 s = q17_in /\
             read (memory :> bytes64 sx0) s = b1_lo /\
             read (memory :> bytes64 (word_add sx0 (word 8))) s = b1_hi)
        (\s. read PC s = word (pc + 0x2a0) /\
             read X0 s = word_add sx0 (word 16) /\
             read X2 s = word_add cptr (word 16) /\
             read X6 s = word_xor b1_lo sx13 /\
             read X7 s = word_xor b1_hi sx14 /\
             read X13 s = sx13 /\
             read X14 s = sx14 /\
             read Q1 s = q1_in /\
             read Q11 s = (word_pmul
                            (word_subword
                              (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                              (0,64):int64)
                            (word_subword q15_in (0,64):int64) :int128) /\
             read Q9 s = (word_pmul
                           (word_subword
                             (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                             (64,64):int64)
                           (word_subword q15_in (64,64):int64) :int128) /\
             read Q15 s = q15_in /\
             read Q17 s = q17_in /\
             read (memory :> bytes128 cptr) s = q5_pre)
        (MAYCHANGE [PC; X0; X2; X6; X7] ,,
         MAYCHANGE [Q4; Q5; Q8; Q9; Q10; Q11; Q22] ,,
         MAYCHANGE [memory :> bytes128 cptr] ,,
         MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES;
                              fst AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC]) THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  MP_TAC(SPECL[`pc:num`; `cptr:int64`; `sx0:int64`; `sx13:int64`; `sx14:int64`;
               `q5_pre:int128`; `q8_pre:int128`;
               `b1_lo:int64`; `b1_hi:int64`]
              AES_GCM_LENC_TAIL_BLOCKS4_ST_LD_REV_EOR_CORRECT) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[NONOVERLAPPING_CLAUSES;
                fst AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC] THEN
    NONOVERLAPPING_TAC;
    ALL_TAC] THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s5" THEN
  MP_TAC(SPECL[`pc:num`; `sx14:int64`;
               `word_xor (b1_lo:int64) (sx13:int64) :int64`;
               `b1_hi:int64`;
               `q1_in:int128`;
               `word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre :int128`;
               `q5_pre:int128`;
               `q15_in:int128`;
               `q17_in:int128`;
               `q10_in:int128`]
              AES_GCM_LENC_TAIL_BLOCKS4_PMULL_MIDLOWHIGH_CORRECT) THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s16" THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s073) — Lenc_blocks_3_remaining FULL chain composition.          *)
(*                                                                           *)
(* Composes BLOCKS3_ST_LD_REV_EOR (slice 169..173) +                         *)
(* BLOCKS3_PMULL_ACCUM (slice 174..186) into a single ensures over the      *)
(* full blocks_3 arm body (slice 169..186, kernel offsets 0x868..0x8ac,     *)
(* 18 instructions).  Entry PC is pc + 0x2a0, exit PC is pc + 0x2e8         *)
(* (= entry of blocks_2_remaining).                                          *)
(*                                                                           *)
(* Postcondition exposes Q9 and Q11 with the block-3 PMULL HIGH/LOW values *)
(* ACCUMULATED into the input Q9/Q11 (from upstream blocks_4 in the chain   *)
(* or the cleared accumulators in the fall-through path).  Q14 = H_3        *)
(* (h-power 2 byteswapped).                                                  *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS3_FULL_CORRECT = prove
 (`!pc (cptr:int64) (sx0:int64) (sx13:int64) (sx14:int64)
       (q2_in:int128) (q5_pre:int128) (q8_pre:int128)
       (q9_in:int128) (q10_in:int128) (q11_in:int128)
       (q14_in:int128) (q17_in:int128)
       (b1_lo:int64) (b1_hi:int64).
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (cptr, 16) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (sx0, 16) /\
   nonoverlapping (cptr, 16) (sx0, 16)
   ==> ensures arm
        (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
             read PC s = word (pc + 0x2a0) /\
             read X0 s = sx0 /\
             read X2 s = cptr /\
             read X13 s = sx13 /\
             read X14 s = sx14 /\
             read Q2 s = q2_in /\
             read Q5 s = q5_pre /\
             read Q8 s = q8_pre /\
             read Q9 s = q9_in /\
             read Q10 s = q10_in /\
             read Q11 s = q11_in /\
             read Q14 s = q14_in /\
