(* ------------------------------------------------------------------------- *)
(* Phase 9 (s073) — Lenc_blocks_1_remaining FULL chain composition.          *)
(*                                                                           *)
(* Composes BLOCKS1_REV_EOR (slice 206..207) +                               *)
(* BLOCKS1_PMULL_ABSORB (slice 208..216) + BLOCKS1_MODULO (slice 217..226)  *)
(* into a single ensures over the entire blocks_1 arm body                  *)
(* (slice 206..226, kernel offsets 0x8fc..0x94c, 21 instructions).           *)
(* Entry PC is pc + 0x334, exit PC is pc + 0x388 (= entry of                 *)
(* common finalization region).                                              *)
(*                                                                           *)
(* Postcondition exposes Q5 (preserved), Q11 (the post-PMULL-LOW             *)
(* accumulator that survives the MODULO fold), and X9 (the bytereversed     *)
(* counter ready for the [x16+12] store).  Q9/Q10 are post-MODULO            *)
(* register-only updates that MAYCHANGE captures and FINALIZATION reads      *)
(* via state-relative names.                                                 *)
(*                                                                           *)
(* MODULO's MP_TAC requires explicit `:int128` annotation on q12_in's       *)
(* word_subword arg to avoid type-variable confusion in the BIGSTEP         *)
(* residual.                                                                 *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS1_FULL_CORRECT = prove
 (`!pc (sx12:int32)
       (q5_pre:int128) (q8_pre:int128)
       (q9_in:int128) (q10_in:int128) (q11_in:int128)
       (q12_in:int128) (q16_in:int128).
   ensures arm
    (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
         read PC s = word (pc + 0x334) /\
         read X12 s = word_zx sx12 /\
         read Q5 s = q5_pre /\
         read Q8 s = q8_pre /\
         read Q9 s = q9_in /\
         read Q10 s = q10_in /\
         read Q11 s = q11_in /\
         read Q12 s = q12_in /\
         read Q16 s = q16_in)
    (\s. read PC s = word (pc + 0x388) /\
         read X9 s = word_zx (word_bytereverse sx12) /\
         read X12 s = word_zx sx12 /\
         read Q5 s = q5_pre /\
         read Q11 s = word_xor q11_in
                       (word_pmul
                         (word_subword
                           (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                           (0,64):int64)
                         (word_subword q12_in (0,64):int64) :int128))
    (MAYCHANGE [PC; X9] ,,
     MAYCHANGE [Q4; Q7; Q8; Q9; Q10; Q11; Q20; Q21])`,
  REPEAT GEN_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES;
                              fst AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC]) THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  MP_TAC(SPECL[`pc:num`; `q5_pre:int128`; `q8_pre:int128`]
              AES_GCM_LENC_TAIL_BLOCKS1_REV_EOR_CORRECT) THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s2" THEN
  MP_TAC(SPECL[`pc:num`; `sx12:int32`;
               `word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre :int128`;
               `q9_in:int128`;
               `q10_in:int128`;
               `q11_in:int128`;
               `q12_in:int128`;
               `q16_in:int128`]
              AES_GCM_LENC_TAIL_BLOCKS1_PMULL_ABSORB_CORRECT) THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s11" THEN
  MP_TAC(SPECL[`pc:num`;
               `q5_pre:int128`;
               `word_xor (q9_in:int128)
                  (word_pmul
                    (word_subword
                      (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                      (64,64):int64)
                    (word_subword (q12_in:int128) (64,64):int64) :int128)`;
               `read Q10 (s11:armstate):int128`;
               `word_xor (q11_in:int128)
                  (word_pmul
                    (word_subword
                      (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                      (0,64):int64)
                    (word_subword (q12_in:int128) (0,64):int64) :int128)`]
              AES_GCM_LENC_TAIL_BLOCKS1_MODULO_CORRECT) THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s21" THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Phase 9b (s080) — BLOCKS1_FULL variant exposing closed-form Q9/Q10.       *)
(*                                                                           *)
(* Composes BLOCKS1_REV_EOR (slice 206..207) +                               *)
(* BLOCKS1_PMULL_ABSORB_Q10 (slice 208..216, s079 variant exposing Q10) +    *)
(* BLOCKS1_MODULO_Q9_Q10 (slice 217..226, s079 variant exposing Q9/Q10) into *)
(* a single ensures over slice 206..226 with closed-form Q9/Q10/Q11 in POST. *)
(* This eliminates the Hilbert-style `read Q9 s` / `read Q10 s` placeholders *)
(* that the s076 BLOCKS1_FINALIZATION_FULL had to use because its FULL input *)
(* (BLOCKS1_FULL_CORRECT) left Q9/Q10 in MAYCHANGE.                          *)
(*                                                                           *)
(* POST shape (with q4 := word_xor (rev64 q5_pre) q8_pre):                   *)
(*   q9' := word_xor q9_in (pmull(q4.hi, q12_in.hi))                         *)
(*   q10' := word_xor q10_in (pmull((zx (q4 ^ zx q4.hi).lo).lo, q16_in.lo))  *)
(*   q11' := word_xor q11_in (pmull(q4.lo, q12_in.lo))                       *)
(*   m := swap_halves(q9') ^ pmull(q9'.lo, 0xc2<<56) ^ q9' ^ q11' ^ q10'     *)
(*   Q9_post := pmull(m.lo, 0xc2<<56)                                        *)
(*   Q10_post := swap_halves(m)                                              *)
(*   Q11_post := q11'                                                        *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS1_FULL_Q9_Q10_CORRECT = prove
 (`!pc (sx12:int32)
       (q5_pre:int128) (q8_pre:int128)
       (q9_in:int128) (q10_in:int128) (q11_in:int128)
       (q12_in:int128) (q16_in:int128).
   ensures arm
    (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
         read PC s = word (pc + 0x334) /\
         read X12 s = word_zx sx12 /\
         read Q5 s = q5_pre /\
         read Q8 s = q8_pre /\
         read Q9 s = q9_in /\
         read Q10 s = q10_in /\
         read Q11 s = q11_in /\
         read Q12 s = q12_in /\
         read Q16 s = q16_in)
    (\s. read PC s = word (pc + 0x388) /\
         read X9 s = word_zx (word_bytereverse sx12) /\
         read X12 s = word_zx sx12 /\
         read Q5 s = q5_pre /\
         read Q11 s = word_xor q11_in
                       (word_pmul
                         (word_subword
                           (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                           (0,64):int64)
                         (word_subword q12_in (0,64):int64) :int128) /\
         (let q4 = word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre :int128 in
          let q9' = word_xor q9_in
                      (word_pmul (word_subword q4 (64,64):int64)
                                 (word_subword q12_in (64,64):int64) :int128) in
          let q10' = word_xor q10_in
                       (word_pmul (word_subword
                                    (word_zx (word_subword
                                               (word_xor q4
                                                 (word_zx (word_subword q4
                                                             (64,64):int64) :int128))
                                               (0,64):int64) :int128)
                                    (0,64):int64)
                                  (word_subword q16_in (0,64):int64) :int128) in
          let q11' = word_xor q11_in
                       (word_pmul (word_subword q4 (0,64):int64)
                                  (word_subword q12_in (0,64):int64) :int128) in
          let m = word_xor (word_subword (word_join (q9':int128) q9' :int256)
                                         (64,128) :int128)
                           (word_xor
                             (word_pmul (word_subword q9' (0,64):int64)
                                        (word 13979173243358019584:int64) :int128)
                             (word_xor (word_xor q9' q11') q10')) in
          read Q9 s = word_pmul (word_subword m (0,64):int64)
                                (word 13979173243358019584:int64) :int128 /\
          read Q10 s = (word_subword (word_join (m:int128) m :int256)
                                     (64,128) :int128)))
    (MAYCHANGE [PC; X9] ,,
     MAYCHANGE [Q4; Q7; Q8; Q9; Q10; Q11; Q20; Q21])`,
  REPEAT GEN_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES;
                              fst AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC]) THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  CONV_TAC(DEPTH_CONV let_CONV) THEN
  MP_TAC(SPECL[`pc:num`; `q5_pre:int128`; `q8_pre:int128`]
              AES_GCM_LENC_TAIL_BLOCKS1_REV_EOR_CORRECT) THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s2" THEN
  MP_TAC(SPECL[`pc:num`; `sx12:int32`;
               `word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre :int128`;
               `q9_in:int128`;
               `q10_in:int128`;
               `q11_in:int128`;
               `q12_in:int128`;
               `q16_in:int128`]
              AES_GCM_LENC_TAIL_BLOCKS1_PMULL_ABSORB_Q10_CORRECT) THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s11" THEN
  MP_TAC(SPECL[`pc:num`;
               `q5_pre:int128`;
               `word_xor (q9_in:int128)
                  (word_pmul
                    (word_subword
                      (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                      (64,64):int64)
                    (word_subword (q12_in:int128) (64,64):int64) :int128)`;
               `word_xor (q10_in:int128)
                  (word_pmul (word_subword
                               (word_zx (word_subword
                                          (word_xor (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                                            (word_zx (word_subword
                                                       (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                                                          (64,64):int64) :int128))
                                          (0,64):int64) :int128)
                               (0,64):int64)
                             (word_subword (q16_in:int128) (0,64):int64) :int128)`;
               `word_xor (q11_in:int128)
                  (word_pmul
                    (word_subword
                      (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                      (0,64):int64)
                    (word_subword (q12_in:int128) (0,64):int64) :int128)`]
              AES_GCM_LENC_TAIL_BLOCKS1_MODULO_Q9_Q10_CORRECT) THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s21" THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s057) — post-prologue baseline cut.                              *)
(*                                                                           *)
(* The 11 prologue instructions (kernel offsets 0..0x28, slice instr indices *)
(* 1..11) save callee-saved registers and frame pointer to the stack and     *)
(* set up the basic scalar pointers `x16 = x4 = ivec_ptr` and `x8 = x5 =     *)
(* key_ptr` for use by the rest of the prelude:                              *)
(*                                                                           *)
(*   0x00  stp x29, x30, [sp, #-128]!  ; pre-decrement SP, save FP/LR       *)
(*   0x04  mov x29, sp                  ; new frame pointer                  *)
(*   0x08  stp x19, x20, [sp, #16]                                          *)
(*   0x0c  mov x16, x4                  ; ivec_ptr (X16)                     *)
(*   0x10  mov x8, x5                   ; key_ptr  (X8)                      *)
(*   0x14  stp x21, x22, [sp, #32]                                          *)
(*   0x18  stp x23, x24, [sp, #48]                                          *)
(*   0x1c  stp d8, d9,   [sp, #64]                                          *)
(*   0x20  stp d10, d11, [sp, #80]                                          *)
(*   0x24  stp d12, d13, [sp, #96]                                          *)
(*   0x28  stp d14, d15, [sp, #112]                                         *)
(*                                                                           *)
(* The cut establishes the post-prologue baseline state (PC = pc + 0x2c,    *)
(* SP = stackpointer - 128, X16 = a, X8 = b) under a stack-nonoverlapping   *)
(* precondition mirroring the SUBROUTINE wrapper shape.  The MAYCHANGE      *)
(* includes the 128-byte stack frame as `bytes(stackpointer-128, 128)` —    *)
(* the simulator emits 16 individual `bytes64` writes which                  *)
(* `ENSURES_FINAL_STATE_TAC` subsumes into the larger `bytes(...,128)` slot. *)
(*                                                                           *)
(* This is the entry point for all subsequent prelude cuts: scalar setup    *)
(* (ldr w17 / ldp x13,x14 / ldr q31 / add x4 / lsr x5 / mov x15 / and x5),  *)
(* then the H-table + key loads, then the AES rounds, then the first 4-     *)
(* block CTR/store, terminating at the wrapper-PRE shape at pc + 0x308.     *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_PRELUDE_POST_PROLOGUE_CORRECT = prove
 (`!pc (a:int64) (b:int64) (stackpointer:int64).
    aligned 16 stackpointer /\
    nonoverlapping (word pc, LENGTH aes_gcm_main_loop_prelude_slice_mc)
                   (word_sub stackpointer (word 128), 128)
    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_prelude_slice_mc /\
              read PC s = word pc /\
              read SP s = stackpointer /\
              read X4 s = a /\
              read X5 s = b)
         (\s. read PC s = word (pc + 0x2c) /\
              read SP s = word_sub stackpointer (word 128) /\
              read X4 s = a /\
              read X5 s = b /\
              read X16 s = a /\
              read X8 s = b)
         (MAYCHANGE [PC; SP; X16; X8; X29] ,,
          MAYCHANGE [memory :> bytes(word_sub stackpointer (word 128), 128)] ,,
          MAYCHANGE [events])`,
  REWRITE_TAC[fst AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC] THEN
  REPEAT STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC (1--11) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s057) — scalar setup cut.                                        *)
(*                                                                           *)
(* The 6 instructions at kernel offsets 0x2c..0x40 (slice instr indices      *)
(* 12..17) load the AES-128 key-schedule's last-round-key halves and round- *)
(* N-1 key, and compute the input-pointer arithmetic                         *)
(*                                                                           *)
(*   0x2c  ldr w17, [x8, #240]            ; nr (= 10 for AES-128)           *)
(*   0x30  add x19, x8, x17, lsl #4       ; last-key pointer = x8 + 16*nr   *)
(*   0x34  ldp x13, x14, [x19]            ; round-N key halves              *)
(*   0x38  ldur q31, [x19, #-16]          ; round-N-1 key (rk9)             *)
(*   0x3c  add x4, x0, x1, lsr #3         ; end_input_ptr                   *)
(*   0x40  lsr x5, x1, #3                 ; byte_len                        *)
(*                                                                           *)
(* The cut takes a key-schedule-in-memory precondition specifying the bytes *)
(* at offsets 240 (nr), 160/168 (rk10 halves), and 144 (rk9 q-load).        *)
(* For AES-128 the round count is hardcoded to 10, so `nr = 10` is a        *)
(* concrete value in the precondition; the cut commits to this              *)
(* specialization rather than parametrizing over an arbitrary nr (the       *)
(* AES-128 fork removes the AES-192/256 branches, so only nr=10 reaches    *)
(* this prelude — the unverified aws-lc kernel branches on nr at offset    *)
(* 0x7c / 0x84 to dispatch round counts).                                   *)
(*                                                                           *)
(* MAYCHANGE is split across [PC; X4; X5; X13; X14; X17; X19] (int64),     *)
(* [Q31] (int128), and [events] (lists of memory accesses).  Unifying      *)
(* PC/Xn with Q31 in a single [...] would force a typecheck error since    *)
(* PC and Xn are :64 word components while Q31 is :128 word.                *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_PRELUDE_SCALAR_SETUP_CORRECT = prove
 (`!pc (x0_init:int64) (x1_init:int64) (x5_init:int64) (b:int64)
       (lk_lo:int64) (lk_hi:int64) (rk9:int128).
    ensures arm
     (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_prelude_slice_mc /\
          read PC s = word (pc + 0x2c) /\
          read X0 s = x0_init /\
          read X1 s = x1_init /\
          read X8 s = b /\
          read X5 s = x5_init /\
          read (memory :> bytes32 (word_add b (word 240))) s = (word 10:32 word) /\
          read (memory :> bytes64 (word_add b (word 160))) s = lk_lo /\
          read (memory :> bytes64 (word_add b (word 168))) s = lk_hi /\
          read (memory :> bytes128 (word_add b (word 144))) s = rk9)
     (\s. read PC s = word (pc + 0x44) /\
          read X0 s = x0_init /\
          read X1 s = x1_init /\
          read X8 s = b /\
          read X17 s = (word 10:64 word) /\
          read X19 s = word_add b (word 160) /\
          read X13 s = lk_lo /\
          read X14 s = lk_hi /\
          read X4 s = word_add x0_init (word_ushr x1_init 3) /\
          read X5 s = word_ushr x1_init 3 /\
          read Q31 s = rk9)
     (MAYCHANGE [PC; X4; X5; X13; X14; X17; X19] ,,
      MAYCHANGE [Q31] ,,
      MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC (12--17) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s057) — ivec-load + counter setup cut.                           *)
(*                                                                           *)
(* The 4 instructions at kernel offsets 0x44..0x50 (slice instr indices      *)
(* 18..21) load the initial counter from the ivec buffer and pre-decrement  *)
(* the byte count for the round-down-to-64 step that follows:                *)
(*                                                                           *)
(*   0x44  mov x15, x5                ; save byte_len before rounding        *)
(*   0x48  ldp x10, x11, [x16]        ; ctr96_b64, ctr96_t32 (scalar copies)*)
(*   0x4c  ld1 {v0.16b}, [x16]        ; ctr0 (whole 128-bit counter)        *)
(*   0x50  sub x5, x5, #1             ; byte_len - 1                        *)
(*                                                                           *)
(* The cut takes ivec memory preconditions for the two 64-bit halves and    *)
(* the 128-bit whole — both shapes are needed because the kernel uses both *)
(* the scalar (X10/X11) and vector (Q0) views of the same counter bytes.    *)
(* The stepper handles the redundancy via component aliasing; the           *)
(* precondition explicitly lists both shapes since the spec doesn't reduce  *)
(* one to the other automatically.                                          *)
(*                                                                           *)
(* MAYCHANGE again split by component type per s057's pattern:              *)
(* [PC; X5; X10; X11; X15] (int64), [Q0] (int128), [events].                *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_PRELUDE_IVEC_CTR_CORRECT = prove
 (`!pc (a:int64) (sx5_pre:int64) (ctr_lo:int64) (ctr_hi:int64) (ctr0:int128).
    ensures arm
     (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_prelude_slice_mc /\
          read PC s = word (pc + 0x44) /\
          read X16 s = a /\
          read X5 s = sx5_pre /\
          read (memory :> bytes64 a) s = ctr_lo /\
          read (memory :> bytes64 (word_add a (word 8))) s = ctr_hi /\
          read (memory :> bytes128 a) s = ctr0)
     (\s. read PC s = word (pc + 0x54) /\
          read X16 s = a /\
          read X10 s = ctr_lo /\
          read X11 s = ctr_hi /\
          read X15 s = sx5_pre /\
          read X5 s = word_sub sx5_pre (word 1) /\
          read Q0 s = ctr0)
     (MAYCHANGE [PC; X5; X10; X11; X15] ,,
      MAYCHANGE [Q0] ,,
      MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC (18--21) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s059) — round-keys preload cut.                                  *)
(*                                                                           *)
(* The 39-instruction range at kernel byte offsets 0x54..0xf0 (slice instr  *)
(* indices 22..60) loads round keys rk0..rk7 (excluding rk4 = Q22 which is  *)
(* loaded later in the H-table range), interleaved with the start of the    *)
(* counter setup (Q1/Q2/Q3 from Q0 via fmov + counter increments) and the   *)
(* first four AES rounds on Q0..Q3:                                         *)
(*                                                                           *)
(*   0x54  ldr  q18, [x8]                       ; rk0  -> Q18                *)
(*   0x5c  ldr  q25, [x8, #112]                 ; rk7  -> Q25                *)
(*   0x94  ldr  q19, [x8, #16]                  ; rk1  -> Q19                *)
(*   0xa8  ldr  q20, [x8, #32]                  ; rk2  -> Q20                *)
(*   0xcc  ldr  q21, [x8, #48]                  ; rk3  -> Q21                *)
(*   0xd8  ldr  q24, [x8, #96]                  ; rk6  -> Q24                *)
(*   0xe4  ldr  q23, [x8, #80]                  ; rk5  -> Q23                *)
(*                                                                           *)
(* The post asserts the seven round-key loads.  Q22 (rk4 from [x8,#64]) is  *)
(* loaded inside the H-table range (0xf0..0x244) and is NOT covered by      *)
(* this cut.  Q0..Q3, X5/X9/X11/X12, and round-key Qs go in MAYCHANGE.      *)
(* SOME_FLAGS is NOT in MAYCHANGE: this range has no flag-setting           *)
(* instructions (no cmp / adds variant).                                    *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_PRELUDE_ROUND_KEYS_CORRECT = prove
 (`!pc (b:int64)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128)
       (rk5:int128) (rk6:int128) (rk7:int128).
    ensures arm
     (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_prelude_slice_mc /\
          read PC s = word (pc + 0x54) /\
          read X8 s = b /\
          read (memory :> bytes128 b) s = rk0 /\
          read (memory :> bytes128 (word_add b (word 16))) s = rk1 /\
          read (memory :> bytes128 (word_add b (word 32))) s = rk2 /\
          read (memory :> bytes128 (word_add b (word 48))) s = rk3 /\
          read (memory :> bytes128 (word_add b (word 80))) s = rk5 /\
          read (memory :> bytes128 (word_add b (word 96))) s = rk6 /\
          read (memory :> bytes128 (word_add b (word 112))) s = rk7)
     (\s. read PC s = word (pc + 0xf0) /\
          read X8 s = b /\
          read Q18 s = rk0 /\
          read Q19 s = rk1 /\
          read Q20 s = rk2 /\
          read Q21 s = rk3 /\
          read Q23 s = rk5 /\
          read Q24 s = rk6 /\
          read Q25 s = rk7)
     (MAYCHANGE [PC; X5; X9; X11; X12] ,,
      MAYCHANGE [Q0; Q1; Q2; Q3;
                 Q18; Q19; Q20; Q21; Q23; Q24; Q25] ,,
      MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC (22--60) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Phase 9 (s058) — H-table load + karatsuba_mid construction cut.           *)
(*                                                                           *)
(* The 85-instruction range at kernel byte offsets 0xf0..0x244 contains the  *)
(* four `ldr q12/q13/q14/q15, [x6, ...]` H-power table loads interleaved    *)
(* with AES rounds and round-key loads, plus the six `trn1`/`trn2`/`eor`    *)
(* instructions that build Q16/Q17 = packed `karatsuba_mid` pairs.          *)
(*                                                                           *)
(* Spec mapping (using `byteswap128 x = word_join x_lo x_hi`):                *)
(*                                                                           *)
(*   ldr q14, [x6, #48] ; v14 = byteswap128(h_power(ghash_twist h) 2)       *)
(*   ldr q13, [x6, #32] ; v13 = byteswap128(h_power(ghash_twist h) 1)       *)
(*   ldr q15, [x6, #80] ; v15 = byteswap128(h_power(ghash_twist h) 3)       *)
(*   ldr q12, [x6]      ; v12 = byteswap128(h_power(ghash_twist h) 0)       *)
(*                                                                           *)
(*   trn2  v17.2d,  v14.2d, v15.2d                                          *)
(*     ; v17 = word_interleave_hi v14 v15                                   *)
(*     ;     = word_join (h_power 3)_LO (h_power 2)_LO                      *)
(*   trn1  v9.2d,   v14.2d, v15.2d                                          *)
(*     ; v9  = word_join (h_power 3)_HI (h_power 2)_HI                      *)
(*   trn2  v16.2d,  v12.2d, v13.2d                                          *)
(*     ; v16 = word_join (h_power 1)_LO (h_power 0)_LO                      *)
(*   eor   v17.16b, v17.16b, v9.16b                                         *)
(*     ; v17 = word_join (km(h_power 3)) (km(h_power 2))                    *)
(*   trn1  v8.2d,   v12.2d, v13.2d                                          *)
(*     ; v8  = word_join (h_power 1)_HI (h_power 0)_HI                      *)
(*   eor   v16.16b, v16.16b, v8.16b                                         *)
(*     ; v16 = word_join (km(h_power 1)) (km(h_power 0))                    *)
(*                                                                           *)
(* The post Q12..Q17 layout exactly matches the Phase 8 wrapper PRE          *)
(* (`AES_GCM_MAIN_LOOP_WRAPPER_FULL_CORRECT` parameters q12..q17), so this   *)
(* cut bridges the prelude's H-table load to the wrapper-pre's H-table       *)
(* state.  The Q16/Q17 raw post produced by the simulator after `eor` is    *)
(*                                                                           *)
(*   word_xor (word_join (bs.lo,bs.lo)) (word_join (bs.hi,bs.hi))           *)
(*                                                                           *)
(* (where bs = byteswap128 of the relevant h_power); after unfolding         *)
(* `byteswap128` and `karatsuba_mid`, `WORD_BLAST` discharges the equality   *)
(* in <1s.                                                                   *)
(*                                                                           *)
(* MAYCHANGE captures everything clobbered in this 85-instr range:           *)
(*   - Q0..Q3 (AES rounds 1..8 on counters)                                  *)
(*   - Q8, Q9 (intermediate trn1 results)                                    *)
(*   - Q11 (loaded from [x3] at offset 0x160 + ext + rev64)                  *)
(*   - Q12..Q17 (H-table state — the post specifies these)                   *)
(*   - Q22 (rk4 from [x8,#64]); Q26 (rk8 from [x8,#128])                     *)
(*   - Q27..Q30 (round keys rk9..rk12; rk10..rk12 unused for AES-128)        *)
(*   - X9, X12 (counter scratch via add/orr/rev)                             *)
(*   - SOME_FLAGS (cmp at 0x224 sets NF/ZF/CF/VF)                            *)
(*   - events (memory loads)                                                  *)
(* Note Q18..Q21, Q23..Q25 are NOT written in 0xf0..0x244 — those round-     *)
(* keys are loaded earlier in the prelude (0x54..0xf0) and pass through      *)
(* this slice unchanged.  Tightening MAYCHANGE to exclude them keeps         *)
(* downstream cuts via ARM_BIGSTEP_TAC composition able to thread their      *)
(* values from before this range to after.                                    *)
(*                                                                           *)
(* The slice instr indices for offsets 0xf0..0x240 (last instruction before  *)
(* b.ge at 0x244) are 61..145 (1-based, since 0xf0/4+1 = 61, 0x240/4+1 =     *)
(* 145).                                                                     *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_PRELUDE_HTABLE_KMID_CORRECT = prove
 (`!pc (htable_ptr:int64) (h:int128).
    nonoverlapping (word pc, LENGTH aes_gcm_main_loop_prelude_slice_mc)
                   (htable_ptr, 96)
    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_prelude_slice_mc /\
              read PC s = word (pc + 0xf0) /\
              read X6 s = htable_ptr /\
              read (memory :> bytes128 htable_ptr) s =
                byteswap128 (h_power (ghash_twist h) 0) /\
              read (memory :> bytes128 (word_add htable_ptr (word 32))) s =
                byteswap128 (h_power (ghash_twist h) 1) /\
              read (memory :> bytes128 (word_add htable_ptr (word 48))) s =
                byteswap128 (h_power (ghash_twist h) 2) /\
              read (memory :> bytes128 (word_add htable_ptr (word 80))) s =
                byteswap128 (h_power (ghash_twist h) 3))
         (\s. read PC s = word (pc + 0x244) /\
              read X6 s = htable_ptr /\
              read Q12 s = byteswap128 (h_power (ghash_twist h) 0) /\
              read Q13 s = byteswap128 (h_power (ghash_twist h) 1) /\
              read Q14 s = byteswap128 (h_power (ghash_twist h) 2) /\
              read Q15 s = byteswap128 (h_power (ghash_twist h) 3) /\
              read Q16 s =
                (word_join (karatsuba_mid (h_power (ghash_twist h) 1):64 word)
                           (karatsuba_mid (h_power (ghash_twist h) 0):64 word)
                 :int128) /\
              read Q17 s =
                (word_join (karatsuba_mid (h_power (ghash_twist h) 3):64 word)
                           (karatsuba_mid (h_power (ghash_twist h) 2):64 word)
                 :int128))
         (MAYCHANGE [PC; X9; X12] ,,
          MAYCHANGE [Q0; Q1; Q2; Q3; Q8; Q9; Q11;
                     Q12; Q13; Q14; Q15; Q16; Q17;
                     Q22; Q26; Q27; Q28; Q29; Q30] ,,
          MAYCHANGE SOME_FLAGS ,,
          MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES;
                              fst AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC]) THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC (61--145) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[byteswap128; karatsuba_mid] THEN CONV_TAC WORD_BLAST;
    REWRITE_TAC[SOME_FLAGS] THEN MONOTONE_MAYCHANGE_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Phase 11b G1 (s180) — prelude-slice block-0 AES-form cut.                 *)
(*                                                                           *)
(* G1 (the ciphertext spec bridge) requires the composed full-kernel chain   *)
(* to assert that the firstblocks ciphertext factor `q0_pre` (a free param   *)
(* in AES_GCM_PRELUDE_FIRSTBLOCKS_FULL_CORRECT @17065) is actually the       *)
(* AES-NI emit form `aese (aes_arm_round^9 ctr0 [rk0..rk8]) rk9`, which the   *)
(* emit-form bridge AES_GCM_EMIT_FORM_AS_PT_XOR_CIPHER (aes_gcm_bridge.ml)    *)
(* consumes to produce the spec ciphertext `pt XOR aes128_cipher_arm ctr0 ks`.*)
(* Per [[g1_ciphertext_q0_free_param]], the existing prelude cuts (ROUND_KEYS,*)
(* HTABLE_KMID) simulate the 0x78..0x238 AES rounds on Q0..Q3 but discard the *)
(* result into MAYCHANGE; their POSTs are silent on Q0..Q3.                   *)
(*                                                                           *)
(* This cut covers the prelude AES region (kernel offsets 0x54..0x244, slice *)
(* instr indices 22..145 — the SAME range as ROUND_KEYS ∘ HTABLE_KMID) and   *)
(* exposes the block-0 AES form in its POST.  Block 0 (V0) is the natural     *)
(* first building block: its AES INPUT is the loaded initial counter `ctr0`  *)
(* (`ld1 {v0.16b},[x16]` at 0x4c, established as `read Q0 = ctr0` here),      *)
(* so it needs NO counter-construction bridge.  Blocks 1..3 (V1..V3) build    *)
(* their AES inputs from the scalar counter registers X9/X10/X11 via          *)
(* `fmov d_i,x10; fmov v_i.d[1],x9` interleaved with the `add w12,#1; rev w9; *)
(* orr x9,x11,x9,lsl#32` BE-counter-increment chain — those require a         *)
(* separate counter-construction bridge (aes_gcm_ctr_at) deferred to a        *)
(* follow-on step.                                                            *)
(*                                                                           *)
(* Round-key inputs are the AES-128 schedule words at `[x8,#16*i]`:          *)
(* rk0..rk8 from offsets 0..128, rk9 pre-loaded into Q31 by the prologue      *)
(* (`ldur q31,[x19,#-16]` at 0x38).  The raw simulator emit form             *)
(* `aese(aesmc(aese ... ctr0 rk0))...)` refolds to the spec                  *)
(* `aese (aes_arm_round^9 ctr0 [rk0..rk8]) rk9` via AESMC_AESE_AS_ARM_ROUND.  *)
(* The trailing `aese ... rk9` (round 9, no aesmc) stays as `aese`, matching  *)
(* the emit bridge's `aese s9 rk9` factor exactly.                            *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_PRELUDE_BLOCK0_AES_FORM_CORRECT = prove
 (`!pc (b:int64) (ctr0:int128) (rk9:int128)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128) (rk4:int128)
       (rk5:int128) (rk6:int128) (rk7:int128) (rk8:int128).
    nonoverlapping (word pc, LENGTH aes_gcm_main_loop_prelude_slice_mc)
                   (b, 256)
    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_prelude_slice_mc /\
              read PC s = word (pc + 0x54) /\
              read X8 s = b /\
              read Q0 s = ctr0 /\
              read Q31 s = rk9 /\
              read (memory :> bytes128 b) s = rk0 /\
              read (memory :> bytes128 (word_add b (word 16))) s = rk1 /\
              read (memory :> bytes128 (word_add b (word 32))) s = rk2 /\
              read (memory :> bytes128 (word_add b (word 48))) s = rk3 /\
              read (memory :> bytes128 (word_add b (word 64))) s = rk4 /\
              read (memory :> bytes128 (word_add b (word 80))) s = rk5 /\
              read (memory :> bytes128 (word_add b (word 96))) s = rk6 /\
              read (memory :> bytes128 (word_add b (word 112))) s = rk7 /\
              read (memory :> bytes128 (word_add b (word 128))) s = rk8)
         (\s. read PC s = word (pc + 0x244) /\
              read Q0 s = aese (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round ctr0
                           rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9)
         (MAYCHANGE [PC; X5; X9; X11; X12] ,,
          MAYCHANGE [Q0; Q1; Q2; Q3; Q8; Q9; Q11;
                     Q12; Q13; Q14; Q15; Q16; Q17;
                     Q18; Q19; Q20; Q21; Q22; Q23; Q24; Q25; Q26;
                     Q27; Q28; Q29; Q30] ,,
          MAYCHANGE SOME_FLAGS ,,
          MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES;
                              fst AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC]) THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC (22--145) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[AESMC_AESE_AS_ARM_ROUND] THEN
  REWRITE_TAC[SOME_FLAGS] THEN MONOTONE_MAYCHANGE_TAC);;

(* ------------------------------------------------------------------------- *)
(* Phase 11b G1 (s181) — prelude-slice block-0..3 AES-form cut.              *)
(*                                                                           *)
(* Extends AES_GCM_PRELUDE_BLOCK0_AES_FORM_CORRECT (above) from block 0 to   *)
(* all four firstblocks counters V0..V3.  Blocks 1..3 build their AES inputs *)
(* from the scalar counter registers X10 (`ctr_lo`) / X11 (`ctr_hi`) via the *)
(* `fmov d_i,x10; fmov v_i.d[1],x9` moves interleaved with the BE-counter     *)
(* increment chain `lsr x12,x11,#32; rev w12; add w12,#1; rev w9; orr        *)
(* x9,x11,x9,lsl#32`.  X10/X11 MUST appear in the PRE — without their value   *)
(* hypotheses the simulator drops Q1/Q2/Q3 to MAYCHANGE with no value, so the *)
(* block-0-only cut cannot expose them.                                       *)
(*                                                                           *)
(* The counter-construction bridge (the heart of this cut): the kernel's      *)
(* block-i AES INPUT equals                                                   *)
(*                                                                           *)
(*    word_bytereverse (aes_gcm_ctr_at (word_bytereverse ctr0) i)            *)
(*                                                                           *)
(* (`aes_gcm_ctr_at` from arm/proofs/utils/aes_gcm_spec.ml = i BE-32          *)
(* increments).  Byte-order reconciliation: the kernel loads the counter via  *)
(* `ld1 {v0.16b},[x16]` (NIST byte k -> int128 bit 8k) whereas the spec       *)
(* `nist_bytes_to_int128` puts NIST byte k at bit 8(15-k); the two int128     *)
(* views are byte-reverses of each other.  Both increment the SAME big-endian *)
(* 32-bit counter field (the kernel works on `ctr_hi >> 32`, the spec on      *)
(* `word_subword c (0,32)`).  Hence spec_ctr0 = word_bytereverse ctr0 and the *)
(* per-block input is the byte-reverse of the spec's i-th counter.  The PRE   *)
(* hypothesis `ctr0 = word_join ctr_hi ctr_lo` ties the vector view (Q0) to   *)
(* the scalar halves (consistent with AES_GCM_PRELUDE_IVEC_CTR_CORRECT, which *)
(* loads ctr0/ctr_lo/ctr_hi from the same 16 ivec bytes); at block 0 it makes *)
(* `word_bytereverse (word_bytereverse ctr0) = ctr0` so V0's input collapses  *)
(* to the bare `ctr0`, matching the block-0-only cut.                         *)
(*                                                                           *)
(* Close: refold the AES rounds (AESMC_AESE_AS_ARM_ROUND), expand             *)
(* `aes_gcm_ctr_at c {0,1,2,3}` to nested `aes_gcm_ctr_increment` via a       *)
(* SUBGOAL_THEN side-lemma (keeps the numeral->SUC reduction local so it      *)
(* doesn't bloat the main goal's word-arithmetic numerals), then per AES      *)
(* conjunct peel `aese`+9x`aes_arm_round` (AP_THM/AP_TERM) down to the bare   *)
(* counter-input equation, drop the ENSURES hypotheses, and discharge with    *)
(* BITBLAST_TAC.  (BITBLAST_TAC closes the byte-order identity in ~1s;         *)
(* CONV_TAC WORD_BLAST hangs on the `word_bytereverse(word_or(word_and        *)
(* (word_bytereverse ..) ..) ..)` form.  Clearing the assumptions first is    *)
(* required — with the ENSURES hyps in scope BITBLAST_TAC fails EQT_ELIM.)    *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_PRELUDE_BLOCK0123_AES_FORM_CORRECT = prove
 (`!pc (b:int64) (ctr0:int128) (rk9:int128) (ctr_lo:int64) (ctr_hi:int64)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128) (rk4:int128)
       (rk5:int128) (rk6:int128) (rk7:int128) (rk8:int128).
    nonoverlapping (word pc, LENGTH aes_gcm_main_loop_prelude_slice_mc)
                   (b, 256)
    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_prelude_slice_mc /\
              read PC s = word (pc + 0x54) /\
              read X8 s = b /\
              read X10 s = ctr_lo /\
              read X11 s = ctr_hi /\
              read Q0 s = ctr0 /\
              ctr0 = word_join ctr_hi ctr_lo /\
              read Q31 s = rk9 /\
              read (memory :> bytes128 b) s = rk0 /\
              read (memory :> bytes128 (word_add b (word 16))) s = rk1 /\
              read (memory :> bytes128 (word_add b (word 32))) s = rk2 /\
              read (memory :> bytes128 (word_add b (word 48))) s = rk3 /\
              read (memory :> bytes128 (word_add b (word 64))) s = rk4 /\
              read (memory :> bytes128 (word_add b (word 80))) s = rk5 /\
              read (memory :> bytes128 (word_add b (word 96))) s = rk6 /\
              read (memory :> bytes128 (word_add b (word 112))) s = rk7 /\
              read (memory :> bytes128 (word_add b (word 128))) s = rk8)
         (\s. read PC s = word (pc + 0x244) /\
              read Q0 s = aese (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (word_bytereverse
                              (aes_gcm_ctr_at (word_bytereverse ctr0) 0))
                           rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9 /\
              read Q1 s = aese (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (word_bytereverse
                              (aes_gcm_ctr_at (word_bytereverse ctr0) 1))
                           rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9 /\
              read Q2 s = aese (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (word_bytereverse
                              (aes_gcm_ctr_at (word_bytereverse ctr0) 2))
                           rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9 /\
              read Q3 s = aese (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (word_bytereverse
                              (aes_gcm_ctr_at (word_bytereverse ctr0) 3))
                           rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9)
         (MAYCHANGE [PC; X5; X9; X11; X12] ,,
          MAYCHANGE [Q0; Q1; Q2; Q3; Q8; Q9; Q11;
                     Q12; Q13; Q14; Q15; Q16; Q17;
                     Q18; Q19; Q20; Q21; Q22; Q23; Q24; Q25; Q26;
                     Q27; Q28; Q29; Q30] ,,
          MAYCHANGE SOME_FLAGS ,,
          MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES;
                              fst AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC]) THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC (22--145) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[AESMC_AESE_AS_ARM_ROUND] THEN
  SUBGOAL_THEN
   `aes_gcm_ctr_at (word_bytereverse (word_join (ctr_hi:int64) (ctr_lo:int64)))
      0 = word_bytereverse (word_join ctr_hi ctr_lo) /\
    aes_gcm_ctr_at (word_bytereverse (word_join (ctr_hi:int64) (ctr_lo:int64)))
      1 = aes_gcm_ctr_increment (word_bytereverse (word_join ctr_hi ctr_lo)) /\
    aes_gcm_ctr_at (word_bytereverse (word_join (ctr_hi:int64) (ctr_lo:int64)))
      2 = aes_gcm_ctr_increment
            (aes_gcm_ctr_increment (word_bytereverse (word_join ctr_hi ctr_lo))) /\
    aes_gcm_ctr_at (word_bytereverse (word_join (ctr_hi:int64) (ctr_lo:int64)))
      3 = aes_gcm_ctr_increment (aes_gcm_ctr_increment
            (aes_gcm_ctr_increment (word_bytereverse (word_join ctr_hi ctr_lo))))`
   (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[aes_gcm_ctr_at] THEN
    CONV_TAC(TOP_DEPTH_CONV num_CONV) THEN REWRITE_TAC[ITER];
    ALL_TAC] THEN
  (* REPEAT CONJ_TAC splits into the four Q0..Q3 AES equalities plus the      *)
  (* trailing MAYCHANGE frame; the FIRST chain dispatches each goal to the    *)
  (* right closer order-independently (the MAYCHANGE closer fails fast on the *)
  (* AES goals, so BITBLAST never sees the MAYCHANGE relation).  Clearing the *)
  (* assumptions before BITBLAST_TAC is required (EQT_ELIM otherwise); the    *)
  (* AES rounds are peeled opaque via AP_THM/AP_TERM down to the bare         *)
  (* counter-input byte-order identity.                                       *)
  REPEAT CONJ_TAC THEN
  FIRST
   [REWRITE_TAC[SOME_FLAGS] THEN MONOTONE_MAYCHANGE_TAC;
    REWRITE_TAC[aes_gcm_ctr_increment] THEN
    REPEAT(AP_THM_TAC THEN AP_TERM_TAC) THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN BITBLAST_TAC]);;

(* ========================================================================= *)
(* Phase 11b G1 (s183) — combined cut over slice instr 22..145 (0x54..0x244) *)
(* asserting the UNION of the three same-range cuts:                          *)
(*   - BLOCK0123 (Q0..Q3 = the AES cipher of the BE-incremented counters),    *)
(*   - ROUND_KEYS (Q18..Q25 = rk0..rk3, rk5..rk7),                            *)
(*   - HTABLE_KMID_FLAG_X12_INV (Q12..Q17 H-table/karatsuba_mid, NF/VF flags  *)
(*     from the cmp at 0x224, X5 = ((sx5 AND ~63) + sx0), and the X12 self-   *)
(*     reference invariant).                                                  *)
(*                                                                            *)
(* WHY a single combined cut (not composition of the three): the four AES    *)
(* rounds on Q0..Q3 run at kernel offsets 0x78..0x238, straddling the 0xf0    *)
(* ROUND_KEYS/HTABLE boundary, so Q0..Q3 can only be tracked from the clean   *)
(* counter state at 0x54.  The three cuts cover the IDENTICAL symbolic        *)
(* execution but each asserts a DISJOINT subset of the output state; they     *)
(* therefore cannot be sequentially composed (same range) nor conjoined       *)
(* (arm is not provably deterministic — the `events` component), and          *)
(* ENSURES_ADD_FACT_TO_POST cannot lift Q0..Q3 (they are in the MAYCHANGE     *)
(* frame, see [[ensures_add_fact_x_in_maychange]]).  The single               *)
(* ARM_STEPS (22--145) proves all of it at once (it is literally the union    *)
(* of BLOCK0123's and HTABLE_KMID_FLAG_X12_INV's own proofs over the same     *)
(* step range), so the combined POST closes with the union of the two close   *)
(* tactics dispatched order-independently by a FIRST chain.                   *)
(*                                                                            *)
(* This is the foundational G1 building block: it is a drop-in replacement    *)
(* for the inline ARM_STEPS(22--60) + HTABLE_KMID_FLAG_X12_INV cut inside     *)
(* AES_GCM_MAIN_LOOP_PRELUDE_PRE_FIRSTBLOCKS_FLAG_X5_X12_PT_CORRECT, adding   *)
(* the Q0..Q3 AES-form conjuncts that the existing prelude chain DROPS.       *)
(* ========================================================================= *)

let AES_GCM_PRELUDE_HTABLE_KMID_FLAG_X12_BLOCK0123_CORRECT = prove
 (`!pc (b:int64) (ctr0:int128) (rk9:int128) (ctr_lo:int64) (ctr_hi:int64)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128) (rk4:int128)
       (rk5:int128) (rk6:int128) (rk7:int128) (rk8:int128)
       (sx0:int64) (sx5:int64) (sx12:int32)
       (htable_ptr:int64) (h:int128).
    nonoverlapping (word pc, LENGTH aes_gcm_main_loop_prelude_slice_mc)
                   (b, 256) /\
    nonoverlapping (word pc, LENGTH aes_gcm_main_loop_prelude_slice_mc)
                   (htable_ptr, 96)
    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_prelude_slice_mc /\
              read PC s = word (pc + 0x54) /\
              read X0 s = sx0 /\
              read X5 s = sx5 /\
              read X6 s = htable_ptr /\
              read X8 s = b /\
              read X10 s = ctr_lo /\
              read X11 s = ctr_hi /\
              read X12 s = word_zx sx12 /\
              read Q0 s = ctr0 /\
              ctr0 = word_join ctr_hi ctr_lo /\
              read Q31 s = rk9 /\
