              read X13 s = lk_lo /\
              read X14 s = lk_hi /\
              read X4 s = word_add ptr0 (word_ushr bit_len 3) /\
              read Q31 s = rk9 /\
              read Q18 s = rk0 /\
              read Q19 s = rk1 /\
              read Q20 s = rk2 /\
              read Q21 s = rk3 /\
              read Q23 s = rk5 /\
              read Q24 s = rk6 /\
              read Q25 s = rk7 /\
              read Q12 s = byteswap128 (h_power (ghash_twist h) 0) /\
