    aligned 16 stackpointer /\
    nonoverlapping (word pc, LENGTH aes_gcm_main_loop_prelude_slice_mc)
                   (word_sub stackpointer (word 128), 128) /\
    nonoverlapping (word pc, LENGTH aes_gcm_main_loop_prelude_slice_mc)
