    nonoverlapping (key_ptr, 256) (word_sub stackpointer (word 128), 128) /\
    nonoverlapping (ivec_ptr, 16) (word_sub stackpointer (word 128), 128) /\
    nonoverlapping (htable_ptr, 96) (word_sub stackpointer (word 128), 128)
