              read Q20 s = rk2 /\
              read Q21 s = rk3 /\
              read Q23 s = rk5 /\
              read Q24 s = rk6 /\
              read Q25 s = rk7 /\
              read Q12 s = byteswap128 (h_power (ghash_twist h) 0) /\
              read Q13 s = byteswap128 (h_power (ghash_twist h) 1) /\
              read Q14 s = byteswap128 (h_power (ghash_twist h) 2) /\
              read Q15 s = byteswap128 (h_power (ghash_twist h) 3) /\
              read Q16 s =
