  REWRITE_TAC[SOME_FLAGS] THEN
  (* Cut 1: POST_PROLOGUE *)
  MP_TAC(SPECL[`pc:num`; `ivec_ptr:int64`; `key_ptr:int64`; `stackpointer:int64`]
