  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC "s21" THEN
  (* Inline ARM_STEPS (22--60): exposes X5 algebraic form and X12 in word_zx
     form (so HTABLE_KMID_FLAG_X12_INV's PRE `read X12 s = word_zx sx12`
     can bind sx12 = word_subword (read X12 s60) (0,32):int32). *)
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC (22--60) THEN
  (* Cut 5: HTABLE_KMID_FLAG_X12_INV.  ANTS produces an X12 PRE-residual
     `read X12 s60 = word_zx (word_subword (read X12 s60) (0,32):int32)`
     which is provable via IMP_REWRITE collapse + helper lemma. *)
  MP_TAC(REWRITE_RULE[SOME_FLAGS]
          (SPECL[`pc:num`; `ptr0:int64`; `read X5 (s60:armstate):int64`;
                 `word_subword (read X12 (s60:armstate):int64) (0,32):int32`;
                 `htable_ptr:int64`; `h:int128`]
                AES_GCM_PRELUDE_HTABLE_KMID_FLAG_X12_INV_CORRECT)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[NONOVERLAPPING_CLAUSES;
                    fst AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC];
    ALL_TAC] THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC "s145" THENL
   [IMP_REWRITE_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH] THEN
    CONV_TAC SYM_CONV THEN
    MATCH_ACCEPT_TAC
     (WORD_BLAST `!x:int32. word_zx (word_subword (word_zx x:int64) (0,32):int32) = (word_zx x:int64)`);
    ALL_TAC] THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN
     `word_add (word_and (word_sub (word_ushr bit_len 3) (word 1))
                         (word 18446744073709551552:int64))
               ptr0 =
      word_add ptr0
               (word_and (word_sub (word_ushr bit_len 3) (word 1))
                         (word 18446744073709551552:int64))`
     (fun th -> REWRITE_TAC[th]) THEN
    CONV_TAC WORD_RULE;
    FIRST_X_ASSUM ACCEPT_TAC;
    SUBGOAL_THEN
     `word_add (word_and (word_sub (word_ushr bit_len 3) (word 1))
                         (word 18446744073709551552:int64))
               ptr0 =
      word_add ptr0
               (word_and (word_sub (word_ushr bit_len 3) (word 1))
                         (word 18446744073709551552:int64))`
     (fun th -> REWRITE_TAC[th]) THEN
    CONV_TAC WORD_RULE;
    SUBGOAL_THEN
     `word_add (word_and (word_sub (word_ushr bit_len 3) (word 1))
                         (word 18446744073709551552:int64))
               ptr0 =
      word_add ptr0
               (word_and (word_sub (word_ushr bit_len 3) (word 1))
                         (word 18446744073709551552:int64))`
     (fun th -> REWRITE_TAC[th]) THEN
    CONV_TAC WORD_RULE]);;

(* ------------------------------------------------------------------------- *)
(* Phase 11b G3 (s221) — concrete-X12 prelude-prefix sibling of              *)
(* AES_GCM_MAIN_LOOP_PRELUDE_PRE_FIRSTBLOCKS_FLAG_X5_X12_PT_CORRECT.          *)
(*                                                                           *)
(* Debt 5 (G3 counter pinning), second structural step (after s220's         *)
(* X12_INV_CTR cut).  The base PT cut carries X12 in OPAQUE self-ref form     *)
(* `read X12 s = word_zx (word_subword (read X12 s) (0,32))`.  This sibling   *)
(* threads the CONCRETE counter: under the new PRE conjunct                   *)
(* `ctr0 = word_join ctr_hi ctr_lo`, it exposes                              *)
(*   read X12 s = word_zx (word_add                                          *)
(*       (word_bytereverse (word_subword ctr0 (96,32):int32)) (word 4))      *)
(* i.e. the block-4 native BE counter (base = word_bytereverse(word_subword  *)
(* ctr0 (96,32)), the value just after `rev w12,w12`@0x70; then +4 from the   *)
(* four `add w12,#1` in 0x54..0x244: three in the ROUND_KEYS range 22..60     *)
(* and one in the HTABLE_KMID range at 0x14c).                               *)
(*                                                                           *)
(* The cut-5 instantiation binds sx12 = word_add (word_bytereverse           *)
(* (word_subword ctr0 (96,32))) (word 3) (the block-3 counter at the cut's   *)
(* PRE @0xf0); X12_INV_CTR's POST then adds the final +1.  The ARM_BIGSTEP    *)
(* leaves an X12-match residual equating the simulator's nested              *)
(* word_zx/word_add base+3 form to that anchored sx12; we discharge it with   *)
(* the two helper lemmas below (a 32-bit subword endianness pivot + a         *)
(* nested-word_zx round-trip collapse).  Stays additive — clones, does not   *)
(* mutate, the self-ref base cut (4+ control-flow consumers depend on it).    *)
(* ------------------------------------------------------------------------- *)

(* Endianness pivot: the kernel's native BE-counter base `word_zx(word_ushr  *)
(* ctr_hi 32)` (the value `rev w12,w12` byte-reverses) equals the int128      *)
(* counter field `word_subword ctr0 (96,32)` once ctr0 = word_join ctr_hi    *)
(* ctr_lo.  Used GSYM to rewrite the anchored RHS back to the ctr_hi form     *)
(* the simulator produced, so the collapse lemma can fire.                   *)
let PRELUDE_X12_CTR_SUBWORD = WORD_BLAST
  `word_zx (word_ushr (ctr_hi:int64) 32) :int32 =
   word_subword (word_join (ctr_hi:int64) (ctr_lo:int64) :int128) (96,32) :int32`;;

(* Nested-word_zx round-trip collapse: the simulator wraps each `add w12,#1` *)
(* in `word_zx(word_zx(... :int64) :int32)` int32<->int64 round-trips.  Three *)
(* increments collapse to `word_zx(word_add w (word 3))`.  WORD_BLAST on the  *)
(* full nested form against the ctr_hi base is intractable                    *)
(* ([[word_blast_state_size_barrier]]); the round-trips peel cleanly with    *)
(* WORD_ZX_ZX, leaving a small word-arith goal WORD_RULE finishes.           *)
let PRELUDE_X12_CTR_COLLAPSE3 = prove
 (`!w:int32.
     (word_zx
       (word_add
        (word_zx
        (word_zx
        (word_add
         (word_zx
         (word_zx
         (word_add
          (word_zx (word_zx w :int64) :int32)
         (word 1)) :int64) :int32)
        (word 1)) :int64) :int32)
       (word 1)) :int64) =
     (word_zx (word_add w (word 3)) :int64)`,
  GEN_TAC THEN
  IMP_REWRITE_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH] THEN
  AP_TERM_TAC THEN CONV_TAC WORD_RULE);;

(* 4-increment analog of PRELUDE_X12_CTR_COLLAPSE3 (s224 author / s225 cold-fix).*)
(* The cut-5 merge's concrete-X12 POST sums the s60 simulator nested form       *)
(* (3 `add w12,#1` increments = base+3) PLUS one more +1 contributed by the     *)
(* X12_INV_CTR cut, giving base+4.  Same closer as COLLAPSE3: peel the nested    *)
(* int32<->int64 word_zx round-trips with WORD_ZX_ZX, finish the small word-arith*)
(* goal with WORD_RULE.                                                          *)
let PRELUDE_X12_CTR_COLLAPSE4 = prove
 (`!w:int32.
     (word_zx
       (word_add
        (word_zx
        (word_zx
        (word_add
         (word_zx
         (word_zx
         (word_add
          (word_zx
          (word_zx
          (word_add
           (word_zx (word_zx w :int64) :int32)
          (word 1)) :int64) :int32)
         (word 1)) :int64) :int32)
        (word 1)) :int64) :int32)
       (word 1)) :int64) =
     (word_zx (word_add w (word 4)) :int64)`,
  GEN_TAC THEN
  IMP_REWRITE_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH] THEN
  AP_TERM_TAC THEN CONV_TAC WORD_RULE);;

(* ------------------------------------------------------------------------- *)
(* C6b debt-5 step 4 (s223 proof / s224 commit / s225 cold-load fix) —        *)
(* concrete-X12 sibling of the HTABLE_KMID_FLAG_BLOCK0123_WITH_Q11_NOX12 cut  *)
(* (@15835).  Byte-identical to the baseline except: name +_CTR; X12 POST     *)
(* opaque self-ref `word_zx(word_subword (read X12 s)(0,32))` replaced by the  *)
(* concrete block-4 counter                                                    *)
(* `word_zx(word_add(word_bytereverse(word_subword ctr0 (96,32)))(word 4))`;   *)
(* and the X12-arm closer rewrites GSYM PRELUDE_X12_CTR_SUBWORD then collapses  *)
(* the nested word_zx round-trips via PRELUDE_X12_CTR_COLLAPSE4.               *)
(*                                                                             *)
(* COLD-LOAD FIX (s225): the original close `REPEAT CONJ_TAC THEN FIRST[...]`  *)
(* failed on a cold load — the X12 arm's bare REWRITE_TACs succeed-without-    *)
(* closing on the non-`aese` Q11/Q16/Q17 GHASH conjuncts (GSYM SUBWORD matches *)
(* a buried `word_subword (word_join ..) (96,32)`), so FIRST committed and left *)
(* them open.  The `THEN NO_TAC` on the X12 arm makes it close-or-fail.  Proved *)
(* MERGE_HYPS=0 cold in a faithful subset scope (s225).                        *)
(*                                                                             *)
(* Placed here (not next to the @15835 baseline) because it forward-references *)
(* the two PRELUDE_X12_CTR_* helpers above.  This is the merge point for the    *)
(* per-band tail re-threading (concrete X12 + AES Q0..Q3 + Q11 together).       *)
let AES_GCM_PRELUDE_HTABLE_KMID_FLAG_BLOCK0123_WITH_Q11_CTR_NOX12_CORRECT = prove
 (`!pc (b:int64) (ctr0:int128) (rk9:int128) (ctr_lo:int64) (ctr_hi:int64)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128) (rk4:int128)
       (rk5:int128) (rk6:int128) (rk7:int128) (rk8:int128)
       (sx0:int64) (sx5:int64)
       (htable_ptr:int64) (h:int128)
       (tag_ptr:int64) (initial_tag:int128).
    nonoverlapping (word pc, LENGTH aes_gcm_main_loop_prelude_slice_mc)
                   (b, 256) /\
    nonoverlapping (word pc, LENGTH aes_gcm_main_loop_prelude_slice_mc)
                   (htable_ptr, 96) /\
    nonoverlapping (word pc, LENGTH aes_gcm_main_loop_prelude_slice_mc)
                   (tag_ptr, 16)
    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_prelude_slice_mc /\
              read PC s = word (pc + 0x54) /\
              read X0 s = sx0 /\
              read X3 s = tag_ptr /\
              read X5 s = sx5 /\
              read X6 s = htable_ptr /\
              read X8 s = b /\
              read X10 s = ctr_lo /\
              read X11 s = ctr_hi /\
              read Q0 s = ctr0 /\
              ctr0 = word_join ctr_hi ctr_lo /\
              read Q31 s = rk9 /\
              read (memory :> bytes128 b) s = rk0 /\
              read (memory :> bytes128 (word_add b (word 16))) s = rk1 /\
              read (memory :> bytes128 (word_add b (word 32))) s = rk2 /\
              read (memory :> bytes128 (word_add b (word 48))) s = rk3 /\
              read (memory :> bytes128 (word_add b (word 64))) s = rk4 /\
              read (memory :> bytes128 (word_add b (word 80))) s = rk5 /\
              read (memory :> bytes128 (word_add b (word 96))) s = rk6 /\
              read (memory :> bytes128 (word_add b (word 112))) s = rk7 /\
              read (memory :> bytes128 (word_add b (word 128))) s = rk8 /\
              read (memory :> bytes128 tag_ptr) s = initial_tag /\
              read (memory :> bytes128 htable_ptr) s =
                byteswap128 (h_power (ghash_twist h) 0) /\
              read (memory :> bytes128 (word_add htable_ptr (word 32))) s =
                byteswap128 (h_power (ghash_twist h) 1) /\
              read (memory :> bytes128 (word_add htable_ptr (word 48))) s =
                byteswap128 (h_power (ghash_twist h) 2) /\
              read (memory :> bytes128 (word_add htable_ptr (word 80))) s =
                byteswap128 (h_power (ghash_twist h) 3))
         (\s. read PC s = word (pc + 0x244) /\
              read X0 s = sx0 /\
              read X5 s = word_add (word_and sx5 (word 18446744073709551552:int64))
                                   sx0 /\
              read X6 s = htable_ptr /\
              read X12 s = word_zx (word_add
                (word_bytereverse (word_subword ctr0 (96,32):int32))
                (word 4):int32) /\
              (read NF s <=>
               ival (word_sub sx0
                      (word_add (word_and sx5 (word 18446744073709551552:int64))
                                sx0)) < &0) /\
              (read VF s <=>
               ~(ival sx0 -
                 ival (word_add (word_and sx5 (word 18446744073709551552:int64))
                                sx0) =
                 ival (word_sub sx0
                        (word_add (word_and sx5
                                    (word 18446744073709551552:int64)) sx0)))) /\
              read Q0 s = aese (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (word_bytereverse
                              (aes_gcm_ctr_at (word_bytereverse ctr0) 0))
                           rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9 /\
              read Q1 s = aese (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (word_bytereverse
                              (aes_gcm_ctr_at (word_bytereverse ctr0) 1))
                           rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9 /\
              read Q2 s = aese (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (word_bytereverse
                              (aes_gcm_ctr_at (word_bytereverse ctr0) 2))
                           rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9 /\
              read Q3 s = aese (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (aes_arm_round (aes_arm_round (aes_arm_round
                           (word_bytereverse
                              (aes_gcm_ctr_at (word_bytereverse ctr0) 3))
                           rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9 /\
              read Q11 s = word_bytereverse initial_tag /\
              read Q18 s = rk0 /\
              read Q19 s = rk1 /\
              read Q20 s = rk2 /\
              read Q21 s = rk3 /\
              read Q22 s = rk4 /\
              read Q23 s = rk5 /\
              read Q24 s = rk6 /\
              read Q25 s = rk7 /\
              read Q26 s = rk8 /\
              read Q12 s = byteswap128 (h_power (ghash_twist h) 0) /\
              read Q13 s = byteswap128 (h_power (ghash_twist h) 1) /\
              read Q14 s = byteswap128 (h_power (ghash_twist h) 2) /\
              read Q15 s = byteswap128 (h_power (ghash_twist h) 3) /\
              read Q16 s =
                (word_join (karatsuba_mid (h_power (ghash_twist h) 1):64 word)
                           (karatsuba_mid (h_power (ghash_twist h) 0):64 word)
                 :int128) /\
              read Q17 s =
                (word_join (karatsuba_mid (h_power (ghash_twist h) 3):64 word)
                           (karatsuba_mid (h_power (ghash_twist h) 2):64 word)
                 :int128))
         (MAYCHANGE [PC; X5; X9; X11; X12] ,,
          MAYCHANGE [Q0; Q1; Q2; Q3; Q8; Q9; Q11;
                     Q12; Q13; Q14; Q15; Q16; Q17;
                     Q18; Q19; Q20; Q21; Q22; Q23; Q24; Q25; Q26;
                     Q27; Q28; Q29; Q30] ,,
          MAYCHANGE SOME_FLAGS ,,
          MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES;
                              fst AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC]) THEN
  ARM_STEPS_TAC AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC (22--145) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[AESMC_AESE_AS_ARM_ROUND] THEN
  SUBGOAL_THEN
   `aes_gcm_ctr_at (word_bytereverse (word_join (ctr_hi:int64) (ctr_lo:int64)))
      0 = word_bytereverse (word_join ctr_hi ctr_lo) /\
    aes_gcm_ctr_at (word_bytereverse (word_join (ctr_hi:int64) (ctr_lo:int64)))
      1 = aes_gcm_ctr_increment (word_bytereverse (word_join ctr_hi ctr_lo)) /\
    aes_gcm_ctr_at (word_bytereverse (word_join (ctr_hi:int64) (ctr_lo:int64)))
      2 = aes_gcm_ctr_increment
            (aes_gcm_ctr_increment (word_bytereverse (word_join ctr_hi ctr_lo))) /\
    aes_gcm_ctr_at (word_bytereverse (word_join (ctr_hi:int64) (ctr_lo:int64)))
      3 = aes_gcm_ctr_increment (aes_gcm_ctr_increment
            (aes_gcm_ctr_increment (word_bytereverse (word_join ctr_hi ctr_lo))))`
   (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[aes_gcm_ctr_at] THEN
    CONV_TAC(TOP_DEPTH_CONV num_CONV) THEN REWRITE_TAC[ITER];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THEN
  FIRST
   [REWRITE_TAC[SOME_FLAGS] THEN MONOTONE_MAYCHANGE_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    (* Concrete-X12 arm.  The `aese`-guard skips this arm on the Q0..Q3 AES
       conjuncts (handled by the ctr_increment arm below).  But the guard is
       NOT sufficient on its own: the Q11/Q16/Q17 GHASH conjuncts carry no
       `aese`, and `GSYM PRELUDE_X12_CTR_SUBWORD` spuriously matches a
       `word_subword (word_join ..) (96,32)` subterm buried in their
       byteswapped forms.  A bare `REWRITE_TAC[..] THEN REWRITE_TAC[..]` would
       then SUCCEED-WITHOUT-CLOSING on those conjuncts, and `FIRST` would commit
       to this arm, leaving Q11/Q16/Q17 open on a COLD load (the warm-session
       scope masked this — see [[asm_rewrite_in_orelse_chain]] /
       [[file_load_smoke_test_required]]).  The trailing `THEN NO_TAC` makes the
       arm close-or-fail: it succeeds only when the X12 collapse actually closes
       the goal, so `FIRST` falls through to the correct Q11/karatsuba arms on
       the GHASH conjuncts. *)
    ((fun (asl,w) ->
        if can (find_term (fun t -> t = `aese`)) w
        then failwith "X12 arm: aese present"
        else (REWRITE_TAC[GSYM PRELUDE_X12_CTR_SUBWORD] THEN
              REWRITE_TAC[PRELUDE_X12_CTR_COLLAPSE4] THEN
              NO_TAC) (asl,w)));
    (CONV_TAC SYM_CONV THEN
     REWRITE_TAC[GSYM EXT_REV64_IS_BYTEREVERSE;
                 aes_gcm_rev64_int128; byteswap128] THEN
     CONV_TAC WORD_BLAST);
    REWRITE_TAC[byteswap128; karatsuba_mid] THEN CONV_TAC WORD_BLAST;
    REWRITE_TAC[aes_gcm_ctr_increment] THEN
    REPEAT(AP_THM_TAC THEN AP_TERM_TAC) THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN BITBLAST_TAC]);;

(* ========================================================================= *)
(* s247 C6b debt-2 STEP 2b — masked-X11 sibling of the BLOCK0123 prelude.     *)
(* Additive clone of ..._WITH_Q11_CTR_NOX12_CORRECT (@above) with ONE extra   *)
(* POST conjunct: X11 = word_and (word_subword ctr0 (64,64)) 0xffffffff, the  *)
(* masked counter-high (orr w11,w11,w11 @.S:71 is a 32-bit zero-extending     *)
