     `word_add (word_and (word_sub (word_ushr bit_len 3) (word 1))
                         (word 18446744073709551552:int64))
               ptr0 =
      word_add ptr0
               (word_and (word_sub (word_ushr bit_len 3) (word 1))
                         (word 18446744073709551552:int64))`
     (fun th -> REWRITE_TAC[th]) THEN
    CONV_TAC WORD_RULE;
    FIRST_X_ASSUM ACCEPT_TAC;
    SUBGOAL_THEN
     `word_add (word_and (word_sub (word_ushr bit_len 3) (word 1))
                         (word 18446744073709551552:int64))
               ptr0 =
      word_add ptr0
               (word_and (word_sub (word_ushr bit_len 3) (word 1))
                         (word 18446744073709551552:int64))`
     (fun th -> REWRITE_TAC[th]) THEN
    CONV_TAC WORD_RULE;
    SUBGOAL_THEN
     `word_add (word_and (word_sub (word_ushr bit_len 3) (word 1))
                         (word 18446744073709551552:int64))
               ptr0 =
      word_add ptr0
               (word_and (word_sub (word_ushr bit_len 3) (word 1))
                         (word 18446744073709551552:int64))`
     (fun th -> REWRITE_TAC[th]) THEN
    CONV_TAC WORD_RULE]);;
