(* ==========================================================================
 * Phase 9b/10 (s099) — X0 strengthening chain for byte_len > 128 wrapper.
 *
 * The PRELUDE_FULL_KERNEL_CORRECT (line ~16193) does NOT assert
 * `read X0 s = word_add ptr0 (word 64)` in its POST (X0 is in MAYCHANGE
 * only).  The byte_len > 128 wrapper's downstream MAIN_LOOP_WRAPPER PRE
 * needs `read X0 s = x0_init` such that
 * `word_add x0_init (word(64*N)) = x5_init`, where `x5_init = ptr0 +
 * (byte_len_w - 1) AND ~63`.  Threading this requires X0 in the prelude
 * POST (witnessing `x0_init := ptr0+64`).
 *
 * Five parallel `_X0_LIFT` variants threading X0 = ptr0+64 through:
 *
 *   1. RK10_THROUGH_BGE_X0_LIFT — adds `read X0 s = word_add a (word 64)`
 *      to POST.  X0 is NOT in this theorem's MAYCHANGE (preserved
 *      across 0x260..0x308); use ENSURES_ADD_FACT_TO_POST via LIFT_FACT_TAC.
 *   2. PT23_THROUGH_BGE_X0_LIFT — composes PT23_LOAD (which advances X0
 *      to a+64) + RK10_THROUGH_BGE_X0_LIFT.
 *   3. FIRSTBLOCKS_FULL_X0_LIFT — composes PT01_LOAD (X0 unchanged) +
 *      PT23_THROUGH_BGE_X0_LIFT.
 *   4. SLICE_FULL_X0_LIFT — composes chain1 (X0 = ptr0 unchanged) +
 *      FIRSTBLOCKS_FULL_X0_LIFT.
 *   5. KERNEL_PRELUDE_X0_LIFT — promotes SLICE_FULL_X0_LIFT to the
 *      kernel mc context via SLICE_TO_KERNEL_PRELUDE_LOAD.
 *
 * Each step is a small variant on its non-X0 counterpart.  No additional
 * antecedents or MAYCHANGE atoms — the theorem statements differ only in
 * adding `read X0 s = word_add ptr0 (word 64)` (or `... (word 64)` for
 * inner cuts) to the POST conjunction.
 * ========================================================================= *)

let RK10_THROUGH_BGE_X0_LIFT = prove
 (`!pc (a:int64) (sx5:int64) (cptr:int64)
       (q0_pre:int128) (q1_pre:int128)
       (sx10:int64) (sx9:int64) (sx11:int64) (sx12:int32)
       (q2_pre:int128) (q3_pre:int128) (q6_pre:int128) (q7_pre:int128)
       (rk10_lo:int64) (rk10_hi:int64)
       (b0_lo:int64) (b0_hi:int64) (b1_lo:int64) (b1_hi:int64)
       (b2_lo:int64) (b2_hi:int64) (b3_lo:int64) (b3_hi:int64).
    val a + 64 < 2 EXP 63 /\
    ival (word_add a (word 64)) < ival sx5 /\
    nonoverlapping (word pc, LENGTH aes_gcm_main_loop_prelude_slice_mc)
                   (cptr, 64)
    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_prelude_slice_mc /\
              read PC s = word (pc + 0x260) /\
              read X0 s = word_add a (word 64) /\
              read X5 s = sx5 /\
              read X2 s = cptr /\
              read X9 s = sx9 /\
              read X10 s = sx10 /\
              read X11 s = sx11 /\
              read X12 s = word_zx sx12 /\
              read X13 s = rk10_lo /\
              read X14 s = rk10_hi /\
              read X6 s = b0_lo /\
              read X7 s = b0_hi /\
              read X19 s = b1_lo /\
              read X20 s = b1_hi /\
              read X21 s = b2_lo /\
              read X22 s = b2_hi /\
              read X23 s = b3_lo /\
              read X24 s = b3_hi /\
              read Q0 s = q0_pre /\
              read Q1 s = q1_pre /\
              read Q2 s = q2_pre /\
              read Q3 s = q3_pre /\
              read Q6 s = q6_pre /\
              read Q7 s = q7_pre)
         (\s. read X0 s = word_add a (word 64) /\
              read PC s = word (pc + 0x308) /\
              read X2 s = word_add cptr (word 64) /\
              read (memory :> bytes128 cptr) s = word_xor q0_pre
                   (word_insert (word_zx (word_xor b0_lo rk10_lo) :int128)
                                (64,64) (word_xor b0_hi rk10_hi)) /\
              read (memory :> bytes128 (word_add cptr (word 16))) s =
                   word_xor q1_pre
                            (word_insert
                              (word_zx (word_xor b1_lo rk10_lo) :int128)
                              (64,64) (word_xor b1_hi rk10_hi)) /\
              read (memory :> bytes128 (word_add cptr (word 32))) s =
                   word_xor q2_pre
                            (word_insert
                              (word_zx (word_xor b2_lo rk10_lo) :int128)
                              (64,64) (word_xor b2_hi rk10_hi)) /\
              read (memory :> bytes128 (word_add cptr (word 48))) s =
                   word_xor q3_pre (word_insert
                                     (word_zx (word_xor b3_lo rk10_lo) :int128)
                                     (64,64) (word_xor b3_hi rk10_hi)))
         (MAYCHANGE [PC; X2; X6; X7; X9; X12; X19; X20; X21; X22; X23; X24] ,,
          MAYCHANGE [Q0; Q1; Q2; Q4; Q5; Q6; Q7] ,,
          MAYCHANGE [memory :> bytes128 cptr;
                     memory :> bytes128 (word_add cptr (word 16));
                     memory :> bytes128 (word_add cptr (word 32));
                     memory :> bytes128 (word_add cptr (word 48))] ,,
          MAYCHANGE SOME_FLAGS ,,
          MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  LIFT_FACT_TAC THEN
  MP_TAC(SPECL[`pc:num`; `a:int64`; `sx5:int64`; `cptr:int64`;
               `q0_pre:int128`; `q1_pre:int128`;
               `sx10:int64`; `sx9:int64`; `sx11:int64`; `sx12:int32`;
               `q2_pre:int128`; `q3_pre:int128`; `q6_pre:int128`; `q7_pre:int128`;
               `rk10_lo:int64`; `rk10_hi:int64`;
               `b0_lo:int64`; `b0_hi:int64`; `b1_lo:int64`; `b1_hi:int64`;
               `b2_lo:int64`; `b2_hi:int64`; `b3_lo:int64`; `b3_hi:int64`]
              AES_GCM_PRELUDE_FIRSTBLOCKS_RK10_THROUGH_BGE_CORRECT) THEN
  ASM_REWRITE_TAC[SOME_FLAGS]);;

