          read Q13 s = q13 /\
          read Q14 s = q14 /\
          read Q15 s = q15 /\
          read Q16 s = q16 /\
          read Q17 s = q17 /\
          read Q18 s = rk0 /\
          read Q19 s = rk1 /\
          read Q20 s = rk2 /\
          read Q21 s = rk3 /\
          read Q22 s = rk4 /\
          read Q23 s = rk5 /\
          read X9 s = sx9 /\
          read X10 s = sx10)
     (\s. read PC s = word (pc + 0x144) /\
          read Q0 s = aes_arm_round
                       (aes_arm_round
