  REPEAT CONJ_TAC THEN
  TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  TRY (ASM_REWRITE_TAC[]) THEN
  TRY (REWRITE_TAC[aes_gcm_rev64_int128] THEN
       ASM_REWRITE_TAC[] THEN CONV_TAC WORD_BLAST) THEN
  TRY (CONV_TAC WORD_BLAST));;

