    ABBREV_TAC `H1_HI:64 word = word_subword (h_power (ghash_twist h) 1) (64,64)` THEN
    ABBREV_TAC `H2_LO:64 word = word_subword (h_power (ghash_twist h) 2) (0,64)` THEN
    ABBREV_TAC `H2_HI:64 word = word_subword (h_power (ghash_twist h) 2) (64,64)` THEN
    ABBREV_TAC `H3_LO:64 word = word_subword (h_power (ghash_twist h) 3) (0,64)` THEN
    ABBREV_TAC `H3_HI:64 word = word_subword (h_power (ghash_twist h) 3) (64,64)` THEN
    (* FIX 1: the leading reassociation conjunct (h-eq) closes via WORD_RULE. *)
    CONJ_TAC THENL [CONV_TAC WORD_RULE; ALL_TAC] THEN
    (* c0 helper: word_join-first. *)
    SUBGOAL_THEN
     `(word_subword (word_zx (word_subword (word_xor (word_join (c0_lo:64 word) (c0_hi:64 word):int128)
                                                     (word_zx (c0_lo:64 word):int128))
                                           (0,64) :64 word):int128) (0,64) :64 word) =
      word_xor c0_hi c0_lo` ASSUME_TAC THENL
     [CONV_TAC WORD_BLAST; ALL_TAC] THEN
    (* FIX 2a: c1 helper restated in GOAL operand order (word_join-first). *)
    SUBGOAL_THEN
     `(word_subword (word_zx (word_subword
         (word_xor (word_join (c1_lo:64 word) (c1_hi:64 word):int128)
                   (word_zx (c1_lo:64 word):int128)) (0,64) :64 word):int128)
         (0,64) :64 word) = word_xor c1_hi c1_lo` ASSUME_TAC THENL
     [CONV_TAC WORD_BLAST; ALL_TAC] THEN
    (* c3 helper: word_join-first. *)
    SUBGOAL_THEN
     `(word_subword (word_zx (word_subword (word_xor (word_join (c3_lo:64 word) (c3_hi:64 word):int128)
                                                     (word_zx (c3_lo:64 word):int128))
                                           (0,64) :64 word):int128) (0,64) :64 word) =
      word_xor c3_hi c3_lo` ASSUME_TAC THENL
     [CONV_TAC WORD_BLAST; ALL_TAC] THEN
    (* FIX 2b: c2 helper — word_insert of word_subword, word_zx-c2_lo first. *)
    SUBGOAL_THEN
     `(word_subword (word_insert
         (word_zx (word_subword (word_xor (word_zx (c2_lo:64 word):int128)
                    (word_join (c2_lo:64 word) (c2_hi:64 word):int128)) (0,64) :64 word):int128)
         (64,64)
         (word_subword (word_zx (word_subword (word_xor (word_zx (c2_lo:64 word):int128)
                    (word_join (c2_lo:64 word) (c2_hi:64 word):int128)) (0,64) :64 word):int128)
                       (0,64) :64 word):int128) (64,64) :64 word) =
      word_xor c2_hi c2_lo` ASSUME_TAC THENL
     [CONV_TAC WORD_BLAST; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `(word_subword (word_zx (word_xor (H3_LO:64 word) (H3_HI:64 word):64 word)
                    :int128) (0,64) :64 word) = word_xor H3_LO H3_HI` ASSUME_TAC THENL
     [CONV_TAC WORD_BLAST; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `word_xor (c0_hi:64 word) c0_lo = word_xor c0_lo c0_hi /\
      word_xor (c1_hi:64 word) c1_lo = word_xor c1_lo c1_hi /\
      word_xor (c2_hi:64 word) c2_lo = word_xor c2_lo c2_hi /\
      word_xor (c3_hi:64 word) c3_lo = word_xor c3_lo c3_hi` STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN CONV_TAC WORD_RULE; ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]));;


let AES_GCM_PREPRETAIL_FULL_X12_NIST_GHASH_AES_CONCRETE_KERNEL_CORRECT = prove
 (`!pc (q0_pre:int128) (q1_pre:int128) (q2_pre:int128)
       (q4_pre:int128) (q5_pre:int128) (q6_pre:int128) (q7_pre:int128)
       (q11_pre:int128)
       (q12:int128) (q13:int128) (q14:int128) (q15:int128) (q16:int128) (q17:int128)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128)
       (rk4:int128) (rk5:int128) (rk6:int128) (rk7:int128) (rk8:int128) (rk9:int128)
       (sx9:int64) (sx10:int64)
       (h:int128) (prev_tag:int128) (ct0:int128) (ct1:int128) (ct2:int128) (ct3:int128) (sx12:int32).
    word_xor (aes_gcm_rev64_int128 q4_pre) (byteswap128 q11_pre) =
      byteswap128 (word_xor prev_tag ct0) /\
    aes_gcm_rev64_int128 q5_pre = byteswap128 ct1 /\
    aes_gcm_rev64_int128 q6_pre = byteswap128 ct2 /\
    aes_gcm_rev64_int128 q7_pre = byteswap128 ct3 /\
    q15 = byteswap128 (h_power (ghash_twist h) 3) /\
    q14 = byteswap128 (h_power (ghash_twist h) 2) /\
    q13 = byteswap128 (h_power (ghash_twist h) 1) /\
    q12 = byteswap128 (h_power (ghash_twist h) 0) /\
    q17 = (word_join (karatsuba_mid (h_power (ghash_twist h) 3) :64 word)
                     (karatsuba_mid (h_power (ghash_twist h) 2) :64 word)
           :int128) /\
    q16 = (word_join (karatsuba_mid (h_power (ghash_twist h) 1) :64 word)
                     (karatsuba_mid (h_power (ghash_twist h) 0) :64 word)
           :int128)
    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_enc_kernel_mc /\
              read PC s = word (pc + 0x5c8) /\
              read Q0 s = q0_pre /\
              read Q1 s = q1_pre /\
              read Q2 s = q2_pre /\
              read Q4 s = q4_pre /\
              read Q5 s = q5_pre /\
              read Q6 s = q6_pre /\
              read Q7 s = q7_pre /\
              read Q11 s = q11_pre /\
              read Q12 s = q12 /\
              read Q13 s = q13 /\
              read Q14 s = q14 /\
              read Q15 s = q15 /\
              read Q16 s = q16 /\
              read Q17 s = q17 /\
              read Q18 s = rk0 /\
              read Q19 s = rk1 /\
              read Q20 s = rk2 /\
              read Q21 s = rk3 /\
              read Q22 s = rk4 /\
              read Q23 s = rk5 /\
              read Q24 s = rk6 /\
              read Q25 s = rk7 /\
              read Q26 s = rk8 /\
              read Q31 s = rk9 /\
              read X9 s = sx9 /\
              read X10 s = sx10 /\
              read X12 s = word_zx sx12)
         (\s. read PC s = word (pc + 0x7c8) /\
              read Q0 s = aes_arm_final_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round q0_pre rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9 /\
              read Q1 s = aes_arm_final_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round q1_pre rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9 /\
              read Q2 s = aes_arm_final_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round q2_pre rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9 /\
              read Q3 s = aes_arm_final_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (aes_arm_round (word_insert (word_zx (sx10:int64):int128) (64,64) sx9 :int128) rk0) rk1) rk2) rk3) rk4) rk5) rk6) rk7) rk8) rk9 /\
              read Q11 s = nist_ghash h prev_tag [ct0; ct1; ct2; ct3] /\
              read X12 s = word_zx (word_add sx12 (word 1):int32))
         (MAYCHANGE [PC; X12] ,,
          MAYCHANGE [Q0; Q1; Q2; Q3; Q4; Q5; Q6; Q7; Q8; Q9; Q10; Q11] ,,
          MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC (SPECL [`pc + 0x5c8:num`;
                 `q0_pre:int128`; `q1_pre:int128`; `q2_pre:int128`;
                 `q4_pre:int128`; `q5_pre:int128`; `q6_pre:int128`;
                 `q7_pre:int128`;
                 `q11_pre:int128`;
                 `q12:int128`; `q13:int128`; `q14:int128`; `q15:int128`;
                 `q16:int128`; `q17:int128`;
                 `rk0:int128`; `rk1:int128`; `rk2:int128`; `rk3:int128`;
                 `rk4:int128`; `rk5:int128`; `rk6:int128`; `rk7:int128`;
                 `rk8:int128`; `rk9:int128`;
                 `sx9:int64`; `sx10:int64`;
                 `h:int128`; `prev_tag:int128`;
                 `ct0:int128`; `ct1:int128`; `ct2:int128`; `ct3:int128`;
                 `sx12:int32`]
                AES_GCM_PREPRETAIL_FULL_X12_NIST_GHASH_AES_CONCRETE_CORRECT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ARITH_RULE `(pc + 0x5c8) + 0x200 = pc + 0x7c8`] THEN
  MATCH_MP_TAC (REWRITE_RULE[IMP_CONJ] ENSURES_PRECONDITION_THM) THEN
  GEN_TAC THEN STRIP_TAC THEN
  POP_ASSUM(STRIP_ASSUME_TAC o BETA_RULE) THEN
  ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[SLICE_TO_KERNEL_PREPRETAIL_LOAD]);;


(* ------------------------------------------------------------------------- *)
(* Phase 9b (s076) — BLOCKS1_FULL + FINALIZATION composition.                *)
(*                                                                           *)
(* Composes AES_GCM_LENC_TAIL_BLOCKS1_FULL_CORRECT (s072, slice 206..226;    *)
(* kernel offsets 0x334..0x388) + AES_GCM_LENC_TAIL_FINALIZATION_CORRECT     *)
(* (s072, slice 227..234; kernel offsets 0x388..0x3a8) into a single ensures *)
(* over the full BLOCKS1 + FINALIZATION region (slice 206..234, kernel       *)
(* offsets 0x334..0x3a8, 29 instructions).                                   *)
(*                                                                           *)
(* The xiptr-write post-conjunct uses `read Q9 s` and `read Q10 s` as        *)
(* Hilbert-style state witnesses for the post-MODULO Q9, Q10 values.         *)
(* Justified: BLOCKS1_FULL's MAYCHANGE includes Q9, Q10 (its proof drops    *)
(* them to MAYCHANGE rather than asserting closed-form post values), and    *)
(* FINALIZATION's MAYCHANGE is [PC; X0; Q11; bytes128 cptr; bytes128 xiptr; *)
(* bytes32(...sx16+12...); events] — Q9, Q10 are NOT in FINALIZATION's      *)
(* MAYCHANGE, so they are preserved across FINALIZATION; therefore           *)
(* `read Q9 s` (final state) = `read Q9 s_after_BLOCKS1`, which is the      *)
(* unique value the simulator produces.                                      *)
(*                                                                           *)
(* The Q11 exit value asserted by BLOCKS1_FULL is dropped from this         *)
(* composed POST because FINALIZATION's MAYCHANGE includes Q11 (the         *)
(* `eor v11, v11, v9` chain clobbers it).  This is fine: the xiptr memory  *)
(* write is the externally visible result and captures all algebraic        *)
(* content the spec needs.                                                   *)
(*                                                                           *)
(* This is the first "branch-arm body + FINALIZATION" composition cut for   *)
(* the Lenc_tail wrapper.  Analogous compositions for BLOCKS2/3/4 will      *)
(* follow, plus the BGT_BLOCKS{2,3,4} branch-arm fall-through pieces.        *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS1_FINALIZATION_FULL_CORRECT = prove
 (`!pc (sx12:int32) (sx15:int64) (sx16:int64) (cptr:int64) (xiptr:int64)
       (q5_pre:int128) (q8_pre:int128)
       (q9_in:int128) (q10_in:int128) (q11_in:int128)
       (q12_in:int128) (q16_in:int128).
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (cptr, 16) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (xiptr, 16) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc)
                  (word_add sx16 (word 12), 4) /\
   nonoverlapping (cptr, 16) (xiptr, 16) /\
   nonoverlapping (cptr, 16) (word_add sx16 (word 12), 4) /\
   nonoverlapping (xiptr, 16) (word_add sx16 (word 12), 4)
   ==> ensures arm
        (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
             read PC s = word (pc + 0x334) /\
             read X12 s = word_zx sx12 /\
             read X15 s = sx15 /\
             read X16 s = sx16 /\
             read X2 s = cptr /\
             read X3 s = xiptr /\
             read Q5 s = q5_pre /\
             read Q8 s = q8_pre /\
             read Q9 s = q9_in /\
             read Q10 s = q10_in /\
             read Q11 s = q11_in /\
             read Q12 s = q12_in /\
             read Q16 s = q16_in)
        (\s. read PC s = word (pc + 0x3a8) /\
             read X0 s = sx15 /\
             read X9 s = word_zx (word_bytereverse sx12) /\
             read X12 s = word_zx sx12 /\
             read X15 s = sx15 /\
             read X16 s = sx16 /\
             read X2 s = cptr /\
             read X3 s = xiptr /\
             read Q5 s = q5_pre /\
             read (memory :> bytes32 (word_add sx16 (word 12))) s =
                  word_subword (word_zx (word_bytereverse (sx12:int32)):int64) (0,32):int32 /\
             read (memory :> bytes128 cptr) s = q5_pre /\
             read (memory :> bytes128 xiptr) s =
                  aes_gcm_rev64_int128
                    (word_join (word_subword
                                 (word_xor
                                   (word_xor
                                     (word_xor q11_in
                                       (word_pmul
                                         (word_subword
                                           (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                                           (0,64):int64)
                                         (word_subword q12_in (0,64):int64) :int128))
                                     (read Q9 s))
                                   (read Q10 s))
                                 (0,64):int64)
                               (word_subword
                                 (word_xor
                                   (word_xor
                                     (word_xor q11_in
                                       (word_pmul
                                         (word_subword
                                           (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                                           (0,64):int64)
                                         (word_subword q12_in (0,64):int64) :int128))
                                     (read Q9 s))
                                   (read Q10 s))
                                 (64,64):int64) :int128))
        (MAYCHANGE [PC; X0; X9] ,,
         MAYCHANGE [Q4; Q7; Q8; Q9; Q10; Q11; Q20; Q21] ,,
         MAYCHANGE [memory :> bytes128 cptr;
                    memory :> bytes128 xiptr] ,,
         MAYCHANGE [memory :> bytes32 (word_add sx16 (word 12))] ,,
         MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES;
                              fst AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC]) THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  MP_TAC(SPECL[`pc:num`; `sx12:int32`;
               `q5_pre:int128`; `q8_pre:int128`;
               `q9_in:int128`; `q10_in:int128`; `q11_in:int128`;
               `q12_in:int128`; `q16_in:int128`]
              AES_GCM_LENC_TAIL_BLOCKS1_FULL_CORRECT) THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s21" THEN
  MP_TAC(SPECL[`pc:num`;
               `word_zx (word_bytereverse (sx12:int32)):int64`;
               `sx15:int64`; `sx16:int64`; `cptr:int64`; `xiptr:int64`;
               `q5_pre:int128`;
               `read Q9 (s21:armstate):int128`;
               `read Q10 (s21:armstate):int128`;
               `word_xor (q11_in:int128)
                  (word_pmul
                    (word_subword
                      (word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre)
                      (0,64):int64)
                    (word_subword (q12_in:int128) (0,64):int64) :int128)`]
              AES_GCM_LENC_TAIL_FINALIZATION_CORRECT) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[NONOVERLAPPING_CLAUSES;
                fst AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC] THEN
    NONOVERLAPPING_TAC;
    ALL_TAC] THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s29" THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Phase 9b (s080) — BLOCKS1+FINALIZATION variant with closed-form Q9/Q10.   *)
(*                                                                           *)
(* Composes AES_GCM_LENC_TAIL_BLOCKS1_FULL_Q9_Q10_CORRECT (s080, slice       *)
(* 206..226 with closed-form Q9/Q10 in POST) + AES_GCM_LENC_TAIL_            *)
(* FINALIZATION_CORRECT (s072, slice 227..234) into a single ensures over    *)
(* slice 206..234.  The xiptr-write conjunct in POST uses the closed-form    *)
(* Q9_post / Q10_post (no `read Q9 s` / `read Q10 s` Hilbert leak).          *)
(*                                                                           *)
(* The proof binds the closed-form Q9_post / Q10_post via the BLOCKS1_FULL_  *)
(* Q9_Q10 cut's let-bound POST hypothesis.  After ARM_BIGSTEP through        *)
(* FINALIZATION (which preserves Q9, Q10 — they're not in FINALIZATION's     *)
(* MAYCHANGE), we expand all `let` bindings in the assumption AND the goal  *)
(* with `RULE_ASSUM_TAC(CONV_RULE(DEPTH_CONV let_CONV)) THEN                 *)
(* CONV_TAC(DEPTH_CONV let_CONV)`, then ASM_REWRITE_TAC closes via direct    *)
(* hypothesis-conjunct matching of `read Q9 s29 = pmull(M.lo, ...)` /        *)
(* `read Q10 s29 = swap_halves(M)`.                                          *)
(*                                                                           *)
(* This variant supersedes AES_GCM_LENC_TAIL_BLOCKS1_FINALIZATION_FULL_      *)
(* CORRECT (s076) for downstream consumers that need a closed-form xiptr     *)
(* write (i.e. for connecting to the AES-GCM-spec's `nist_ghash` output).    *)
(* The s076 variant is preserved in tree as a dependency of                  *)
(* AES_GCM_LENC_TAIL_BLOCKS{2,3,4}_FINALIZATION_FULL_CORRECT cascades.       *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS1_FINALIZATION_FULL_CLOSED_CORRECT = prove
 (`!pc (sx12:int32) (sx15:int64) (sx16:int64) (cptr:int64) (xiptr:int64)
       (q5_pre:int128) (q8_pre:int128)
       (q9_in:int128) (q10_in:int128) (q11_in:int128)
       (q12_in:int128) (q16_in:int128).
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (cptr, 16) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (xiptr, 16) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc)
                  (word_add sx16 (word 12), 4) /\
   nonoverlapping (cptr, 16) (xiptr, 16) /\
   nonoverlapping (cptr, 16) (word_add sx16 (word 12), 4) /\
   nonoverlapping (xiptr, 16) (word_add sx16 (word 12), 4)
   ==> ensures arm
        (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
             read PC s = word (pc + 0x334) /\
             read X12 s = word_zx sx12 /\
             read X15 s = sx15 /\
             read X16 s = sx16 /\
             read X2 s = cptr /\
             read X3 s = xiptr /\
             read Q5 s = q5_pre /\
             read Q8 s = q8_pre /\
             read Q9 s = q9_in /\
             read Q10 s = q10_in /\
             read Q11 s = q11_in /\
             read Q12 s = q12_in /\
             read Q16 s = q16_in)
        (\s. read PC s = word (pc + 0x3a8) /\
             read X0 s = sx15 /\
             read X9 s = word_zx (word_bytereverse sx12) /\
             read X12 s = word_zx sx12 /\
             read X15 s = sx15 /\
             read X16 s = sx16 /\
             read X2 s = cptr /\
             read X3 s = xiptr /\
             read Q5 s = q5_pre /\
             read (memory :> bytes32 (word_add sx16 (word 12))) s =
                  word_subword (word_zx (word_bytereverse (sx12:int32)):int64) (0,32):int32 /\
             read (memory :> bytes128 cptr) s = q5_pre /\
             (let q4 = word_xor (aes_gcm_rev64_int128 q5_pre) q8_pre :int128 in
              let q9' = word_xor q9_in
                          (word_pmul (word_subword q4 (64,64):int64)
                                     (word_subword q12_in (64,64):int64) :int128) in
              let q10' = word_xor q10_in
                           (word_pmul (word_subword
                                        (word_zx (word_subword
                                                   (word_xor q4
                                                     (word_zx (word_subword q4
                                                                 (64,64):int64) :int128))
                                                   (0,64):int64) :int128)
                                        (0,64):int64)
                                      (word_subword q16_in (0,64):int64) :int128) in
              let q11' = word_xor q11_in
                           (word_pmul (word_subword q4 (0,64):int64)
                                      (word_subword q12_in (0,64):int64) :int128) in
              let m = word_xor (word_subword (word_join (q9':int128) q9' :int256)
                                             (64,128) :int128)
                               (word_xor
                                 (word_pmul (word_subword q9' (0,64):int64)
                                            (word 13979173243358019584:int64) :int128)
                                 (word_xor (word_xor q9' q11') q10')) in
              let q9_post = word_pmul (word_subword m (0,64):int64)
                                      (word 13979173243358019584:int64) :int128 in
              let q10_post = word_subword (word_join (m:int128) m :int256)
                                          (64,128) :int128 in
              read (memory :> bytes128 xiptr) s =
                   aes_gcm_rev64_int128
                     (word_join (word_subword
                                  (word_xor (word_xor q11' q9_post) q10_post)
                                  (0,64):int64)
                                (word_subword
                                  (word_xor (word_xor q11' q9_post) q10_post)
