(* ------------------------------------------------------------------------- *)
(* Phase 9b (s077) — BLOCKS2 + (BLOCKS1 + FINALIZATION) cascade.             *)
(*                                                                           *)
(* Composes AES_GCM_LENC_TAIL_BLOCKS2_FULL_CORRECT (s073, slice 187..205;    *)
(* kernel offsets 0x2e8..0x334) + AES_GCM_LENC_TAIL_BLOCKS1_FINALIZATION_   *)
(* FULL_CORRECT (s076, slice 206..234; kernel offsets 0x334..0x3a8) into a   *)
(* single ensures over the entire blocks_2 + blocks_1 + finalization arm    *)
(* (slice 187..234, kernel offsets 0x2e8..0x3a8, 48 instructions).           *)
(*                                                                           *)
(* Inner BLOCKS1+FINAL is SPECL'd with state-relative `read Q8 (s19:        *)
(* armstate):int128` (Hilbert) for q8_pre; q9_in/q11_in are the BLOCKS2-    *)
(* exit algebraic forms; q12_in/q16_in/q5_pre/q5_in pass through.            *)
(* The post-cascade Q8 value (`read Q8 s` at s48) is NOT the same as the    *)
(* BLOCKS1+FINAL-input Q8 (BLOCKS2 sets Q8 to `word 0`; BLOCKS1+FINAL's    *)
(* MAYCHANGE includes Q8).                                                   *)
(*                                                                           *)
(* This V1 cascade exposes:                                                  *)
(*   - PC at exit (pc + 0x3a8)                                              *)
(*   - X regs (X0, X9, X12..X16) preserved/set                              *)
(*   - Q3 preserved (BLOCKS2 doesn't touch; BLOCKS1+FINAL doesn't touch)    *)
(*   - bytes32 (sx16 + 12) write (counter store)                            *)
(*   - bytes128 cptr write (BLOCKS2's plaintext store at outer cptr)        *)
(*   - bytes128 (cptr + 16) write (BLOCKS1+FINAL's final store at cptr+16)  *)
(*                                                                           *)
(* The xiptr-write algebraic conjunct (the GHASH output) is NOT included    *)
(* in this POST — it depends on the internal Q8 value (word 0) which        *)
(* BLOCKS2_FULL_CORRECT's POST doesn't expose.  A future variant of         *)
(* BLOCKS2_FULL exposing Q8 = word 0 + a re-derived cascade with the        *)
(* full xiptr-write conjunct will close this gap.                            *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_BLOCKS2_FINALIZATION_FULL_CORRECT = prove
 (`!pc (sx12:int32) (sx15:int64) (sx16:int64)
       (cptr:int64) (sx0:int64) (xiptr:int64)
       (sx13:int64) (sx14:int64)
       (q3_in:int128) (q5_pre:int128) (q8_pre:int128)
       (q9_in:int128) (q10_in:int128) (q11_in:int128)
       (q12_in:int128) (q13_in:int128) (q16_in:int128)
       (b1_lo:int64) (b1_hi:int64).
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (cptr, 32) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (sx0, 16) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc) (xiptr, 16) /\
   nonoverlapping (word pc, LENGTH aes_gcm_main_loop_tail_slice_mc)
                  (word_add sx16 (word 12), 4) /\
   nonoverlapping (cptr, 32) (sx0, 16) /\
   nonoverlapping (cptr, 32) (xiptr, 16) /\
   nonoverlapping (cptr, 32) (word_add sx16 (word 12), 4) /\
   nonoverlapping (sx0, 16) (xiptr, 16) /\
   nonoverlapping (sx0, 16) (word_add sx16 (word 12), 4) /\
   nonoverlapping (xiptr, 16) (word_add sx16 (word 12), 4)
   ==> ensures arm
        (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_tail_slice_mc /\
             read PC s = word (pc + 0x2e8) /\
             read X0 s = sx0 /\
             read X2 s = cptr /\
             read X3 s = xiptr /\
             read X12 s = word_zx sx12 /\
             read X13 s = sx13 /\
             read X14 s = sx14 /\
             read X15 s = sx15 /\
             read X16 s = sx16 /\
             read Q3 s = q3_in /\
             read Q5 s = q5_pre /\
             read Q8 s = q8_pre /\
             read Q9 s = q9_in /\
             read Q10 s = q10_in /\
             read Q11 s = q11_in /\
             read Q12 s = q12_in /\
             read Q13 s = q13_in /\
             read Q16 s = q16_in /\
             read (memory :> bytes64 sx0) s = b1_lo /\
             read (memory :> bytes64 (word_add sx0 (word 8))) s = b1_hi)
        (\s. read PC s = word (pc + 0x3a8) /\
             read X0 s = sx15 /\
             read X9 s = word_zx (word_bytereverse sx12) /\
             read X12 s = word_zx sx12 /\
             read X13 s = sx13 /\
             read X14 s = sx14 /\
             read X15 s = sx15 /\
             read X16 s = sx16 /\
             read Q3 s = q3_in /\
