              AES_GCM_LENC_TAIL_BLOCKS4_ST_LD_REV_EOR_CORRECT) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[NONOVERLAPPING_CLAUSES;
                fst AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC] THEN
    NONOVERLAPPING_TAC;
    ALL_TAC] THEN
  ARM_BIGSTEP_TAC AES_GCM_MAIN_LOOP_TAIL_SLICE_EXEC "s5" THEN
