(* Phase 9b (s084) — slice-to-kernel promotion of DISPATCH_N4_CORRECT.        *)
(*                                                                           *)
(* Promotes the slice-level DISPATCH_N4 (slice 129..138, slice offsets       *)
(* 0x200..0x260) to the full kernel mc context (kernel offsets 0x7c8..0x828).*)
(* ------------------------------------------------------------------------- *)

let AES_GCM_LENC_TAIL_DISPATCH_N4_KERNEL_CORRECT = prove
 (`!pc (sx0:int64) (sx4:int64) (sx12:int32) (sx13:int64) (sx14:int64)
       (q0_in:int128) (q1_in:int128) (q2_in:int128) (q3_in:int128)
       (q10_in:int128) (q11_in:int128)
