       (q11_in:int128)
       (q12_in:int128) (q13_in:int128) (q14_in:int128)
       (q16_in:int128) (q17_in:int128)
       (b0_lo:int64) (b0_hi:int64) (b1_lo:int64) (b1_hi:int64)
       (b2_lo:int64) (b2_hi:int64).
   nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (sx0, 48) /\
