             read X13 s = sx13 /\
             read X14 s = sx14 /\
             read X15 s = sx15 /\
             read X16 s = sx16 /\
             read (memory :> bytes32 (word_add sx16 (word 12))) s =
                  word_subword (word_zx (word_bytereverse (sx12:int32)):int64) (0,32):int32 /\
             read (memory :> bytes128 cptr) s =
                  word_xor q0_in
                          (word_insert
