                                            (word_xor b2_lo sx13:int64) :int128)
                                 (q2_in:int128) :int128 in
              let ct3 = word_xor (word_join (word_xor b3_hi sx14:int64)
                                            (word_xor b3_lo sx13:int64) :int128)
                                 (q3_in:int128) :int128 in
              read (memory :> bytes128 xiptr) s =
                   word_bytereverse
                     (nist_ghash h q11_in
                        [word_bytereverse ct0; word_bytereverse ct1;
                         word_bytereverse ct2; word_bytereverse ct3])))
        (MAYCHANGE [PC; X0; X2; X5; X6; X7; X9] ,,
         MAYCHANGE [Q4; Q5; Q7; Q8; Q9; Q10; Q11; Q20; Q21; Q22] ,,
         MAYCHANGE [memory :> bytes128 cptr;
                    memory :> bytes128 (word_add cptr (word 16));
                    memory :> bytes128 (word_add cptr (word 32));
                    memory :> bytes128 (word_add cptr (word 48));
                    memory :> bytes128 xiptr] ,,
         MAYCHANGE [memory :> bytes32 (word_add sx16 (word 12))] ,,
         MAYCHANGE SOME_FLAGS ,,
         MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL[`pc:num`; `sx0:int64`; `sx4:int64`; `sx12:int32`;
               `sx13:int64`; `sx14:int64`; `sx15:int64`; `sx16:int64`;
               `cptr:int64`; `xiptr:int64`;
               `q0_in:int128`; `q1_in:int128`; `q2_in:int128`; `q3_in:int128`;
               `q10_in:int128`; `q11_in:int128`;
               `q12_in:int128`; `q13_in:int128`; `q14_in:int128`;
               `q15_in:int128`; `q16_in:int128`; `q17_in:int128`;
               `b0_lo:int64`; `b0_hi:int64`; `b1_lo:int64`; `b1_hi:int64`;
               `b2_lo:int64`; `b2_hi:int64`; `b3_lo:int64`; `b3_hi:int64`]
              AES_GCM_LENC_TAIL_N4_FULL_Q9_Q10_CLOSED_KERNEL_CORRECT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(REWRITE_RULE[IMP_CONJ] ENSURES_POSTCONDITION_THM) THEN
  GEN_TAC THEN
  REWRITE_TAC[LET_DEF; LET_END_DEF] THEN
  CONV_TAC(DEPTH_CONV let_CONV) THEN
  STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL[`h:int128`; `q11_in:int128`;
               `word_xor (q0_in:int128)
                  (word_insert
                    (word_zx (word_xor (b0_lo:int64) (sx13:int64)) :int128)
                    (64,64)
                    (word_xor (b0_hi:int64) (sx14:int64))) :int128`;
               `word_xor (word_join (word_xor (b1_hi:int64) (sx14:int64) :int64)
                                    (word_xor (b1_lo:int64) (sx13:int64) :int64) :int128)
                         (q1_in:int128) :int128`;
               `word_xor (word_join (word_xor (b2_hi:int64) (sx14:int64) :int64)
                                    (word_xor (b2_lo:int64) (sx13:int64) :int64) :int128)
                         (q2_in:int128) :int128`;
               `word_xor (word_join (word_xor (b3_hi:int64) (sx14:int64) :int64)
                                    (word_xor (b3_lo:int64) (sx13:int64) :int64) :int128)
                         (q3_in:int128) :int128`]
              XIPTR_4BLOCK_AS_NIST_GHASH) THEN
  REWRITE_TAC[LET_DEF; LET_END_DEF] THEN
  CONV_TAC(DEPTH_CONV let_CONV) THEN
  DISCH_THEN ACCEPT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Phase 9b (s089) — bridge lemmas for the N=0 case of the kernel wrapper.   *)
(*                                                                           *)
(* When `byte_len <= 64` (i.e. zero full 4-block iterations), the prelude's  *)
(* `cmp x0, x5; b.ge .Lenc_tail` at offsets 0x224..0x244 takes the branch    *)
(* and jumps to PC = pc + 0x7c8 (`Lenc_tail`).                                *)
(*                                                                           *)
(* The flag derivation needed: at PC=0x244 the simulator emits NF = ival     *)
(* (word_sub ptr0 x5_init) < &0 and VF/NF logic where x5_init = ptr0 +       *)
(* ((byte_len-1) AND ~63).  For byte_len in [1,64], (byte_len-1) AND ~63 = 0,*)
(* so x5_init = ptr0, hence NF=FALSE and VF=FALSE, hence Condition_GE.      *)
(*                                                                           *)
(* Two atomic algebraic lemmas:                                              *)
(*  - AES_GCM_BYTE_LEN_LE_64_AND_MASK: the and-mask itself is word 0.        *)
(*  - AES_GCM_BYTE_LEN_LE_64_X5_EQ_PTR0: x5_init = ptr0 directly.            *)
(*                                                                           *)
(* These are independent of any kernel/slice mc context and reusable in any  *)
(* downstream Phase 9b N=0 prelude wrapper proof (and in the public byte-    *)
(* level theorem for handling the byte_len ≤ 64 input case).                 *)
(* ------------------------------------------------------------------------- *)

let AES_GCM_BYTE_LEN_LE_64_AND_MASK = prove
 (`!byte_len:int64.
     1 <= val byte_len /\ val byte_len <= 64
     ==> word_and (word_sub byte_len (word 1))
                  (word 18446744073709551552:int64) = (word 0:int64)`,
  GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[GSYM VAL_EQ_0; VAL_WORD_AND_MASK_WORD] THEN
  SUBGOAL_THEN
   `(word 18446744073709551552:int64) = word_not (word (2 EXP 6 - 1))`
   SUBST1_TAC THENL
   [CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC WORD_REDUCE_CONV;
    ALL_TAC] THEN
  REWRITE_TAC[VAL_WORD_AND_NOT_MASK_WORD] THEN
  SUBGOAL_THEN `val (word_sub (byte_len:int64) (word 1)) = val byte_len - 1`
    SUBST1_TAC THENL
   [REWRITE_TAC[VAL_WORD_SUB_CASES; VAL_WORD_1] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  SUBGOAL_THEN `(val (byte_len:int64) - 1) DIV 64 = 0`
    (fun th -> REWRITE_TAC[th]) THENL
   [MATCH_MP_TAC DIV_LT THEN ASM_ARITH_TAC;
    ARITH_TAC]);;

let AES_GCM_BYTE_LEN_LE_64_X5_EQ_PTR0 = prove
 (`!ptr0 byte_len:int64.
     1 <= val byte_len /\ val byte_len <= 64
     ==> word_add ptr0
                  (word_and (word_sub byte_len (word 1))
                            (word 18446744073709551552:int64)) = ptr0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPEC `byte_len:int64` AES_GCM_BYTE_LEN_LE_64_AND_MASK) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONV_TAC WORD_RULE);;

(* Flag bridge: under byte_len ≤ 64, the prelude's `cmp x0,x5`-emitted        *)
(* simulator NF/VF facts both collapse to FALSE, hence Condition_GE holds.    *)
(* Stated in the exact shape the prelude POST exposes (so it can be applied  *)
(* via direct substitution into the wrapper's flag conjunct).                 *)

let AES_GCM_BYTE_LEN_LE_64_NF_VF_FACTS = prove
 (`!ptr0 byte_len:int64.
     1 <= val byte_len /\ val byte_len <= 64
     ==> ~(ival (word_sub ptr0
                  (word_add ptr0
                    (word_and (word_sub byte_len (word 1))
                              (word 18446744073709551552:int64)))) < &0) /\
         (ival ptr0 -
          ival (word_add ptr0
                  (word_and (word_sub byte_len (word 1))
                            (word 18446744073709551552:int64))) =
          ival (word_sub ptr0
                  (word_add ptr0
                    (word_and (word_sub byte_len (word 1))
                              (word 18446744073709551552:int64)))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL[`ptr0:int64`; `byte_len:int64`]
              AES_GCM_BYTE_LEN_LE_64_X5_EQ_PTR0) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[WORD_SUB_REFL; IVAL_WORD_0; INT_LT_REFL] THEN
  INT_ARITH_TAC);;
(* ==========================================================================
 * Phase 9b (s090) — N=0 prelude wrapper.
 *
 * When `byte_len ∈ [1, 64]` (`len_full_blocks DIV 0x40 = 0`, no full
 * 4-block iterations), the prelude's `cmp x0,x5; b.ge .Lenc_tail` at
 * offsets 0x224..0x244 takes the b.ge branch and jumps straight to
 * PC=pc+0x7c8 (Lenc_tail entry).
 *
 * Theorem 1 (FLAG_X5_X12_PT_KERNEL) promotes the slice-level
 *   AES_GCM_MAIN_LOOP_PRELUDE_PRE_FIRSTBLOCKS_FLAG_X5_X12_PT_CORRECT
 * (slice mc, pc → pc+0x244) to the full kernel mc context.  Mirrors
 * the s068 PRELUDE_FULL_KERNEL promotion pattern verbatim.
 *
 * Theorem 2 (N0_KERNEL) is the actual N=0 wrapper.  Composes Theorem 1
 * with one ARM_BIGSTEP_TAC for the b.ge step at 0x244, discharging
 * the Condition_GE flag fact via the s089 NF/VF bridge lemma.
 * ========================================================================= *)

let AES_GCM_MAIN_LOOP_PRELUDE_FLAG_X5_X12_PT_KERNEL_CORRECT = prove
 (`!pc (ptr0:int64) (bit_len:int64) (cptr:int64) (tag_ptr:int64)
       (ivec_ptr:int64) (key_ptr:int64) (htable_ptr:int64)
       (stackpointer:int64)
       (lk_lo:int64) (lk_hi:int64) (rk9:int128)
       (ctr_lo:int64) (ctr_hi:int64) (ctr0:int128)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128)
       (rk5:int128) (rk6:int128) (rk7:int128)
       (h:int128) (q6_pre:int128) (q7_pre:int128)
       (b0_lo:int64) (b0_hi:int64) (b1_lo:int64) (b1_hi:int64)
       (b2_lo:int64) (b2_hi:int64) (b3_lo:int64) (b3_hi:int64).
    aligned 16 stackpointer /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc)
                   (word_sub stackpointer (word 128), 128) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc)
                   (htable_ptr, 96) /\
    nonoverlapping (key_ptr, 256) (word_sub stackpointer (word 128), 128) /\
    nonoverlapping (ivec_ptr, 16) (word_sub stackpointer (word 128), 128) /\
    nonoverlapping (htable_ptr, 96) (word_sub stackpointer (word 128), 128) /\
    nonoverlapping (ptr0, 64) (word_sub stackpointer (word 128), 128)
    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_enc_kernel_mc /\
              read PC s = word pc /\
              read SP s = stackpointer /\
              read X0 s = ptr0 /\
              read X1 s = bit_len /\
              read X2 s = cptr /\
              read X3 s = tag_ptr /\
              read X4 s = ivec_ptr /\
              read X5 s = key_ptr /\
              read X6 s = htable_ptr /\
              read Q6 s = q6_pre /\
              read Q7 s = q7_pre /\
              read (memory :> bytes32 (word_add key_ptr (word 240))) s = (word 10:32 word) /\
              read (memory :> bytes64 (word_add key_ptr (word 160))) s = lk_lo /\
              read (memory :> bytes64 (word_add key_ptr (word 168))) s = lk_hi /\
              read (memory :> bytes128 (word_add key_ptr (word 144))) s = rk9 /\
              read (memory :> bytes64 ivec_ptr) s = ctr_lo /\
              read (memory :> bytes64 (word_add ivec_ptr (word 8))) s = ctr_hi /\
              read (memory :> bytes128 ivec_ptr) s = ctr0 /\
              read (memory :> bytes128 key_ptr) s = rk0 /\
              read (memory :> bytes128 (word_add key_ptr (word 16))) s = rk1 /\
              read (memory :> bytes128 (word_add key_ptr (word 32))) s = rk2 /\
              read (memory :> bytes128 (word_add key_ptr (word 48))) s = rk3 /\
              read (memory :> bytes128 (word_add key_ptr (word 80))) s = rk5 /\
              read (memory :> bytes128 (word_add key_ptr (word 96))) s = rk6 /\
              read (memory :> bytes128 (word_add key_ptr (word 112))) s = rk7 /\
              read (memory :> bytes128 htable_ptr) s =
                byteswap128 (h_power (ghash_twist h) 0) /\
              read (memory :> bytes128 (word_add htable_ptr (word 32))) s =
                byteswap128 (h_power (ghash_twist h) 1) /\
              read (memory :> bytes128 (word_add htable_ptr (word 48))) s =
                byteswap128 (h_power (ghash_twist h) 2) /\
              read (memory :> bytes128 (word_add htable_ptr (word 80))) s =
                byteswap128 (h_power (ghash_twist h) 3) /\
              read (memory :> bytes64 ptr0) s = b0_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 8))) s = b0_hi /\
              read (memory :> bytes64 (word_add ptr0 (word 16))) s = b1_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 24))) s = b1_hi /\
              read (memory :> bytes64 (word_add ptr0 (word 32))) s = b2_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 40))) s = b2_hi /\
              read (memory :> bytes64 (word_add ptr0 (word 48))) s = b3_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 56))) s = b3_hi)
         (\s. read PC s = word (pc + 0x244) /\
              read SP s = word_sub stackpointer (word 128) /\
              read X0 s = ptr0 /\
              read X2 s = cptr /\
              read X3 s = tag_ptr /\
              read X6 s = htable_ptr /\
              read X8 s = key_ptr /\
              read X16 s = ivec_ptr /\
              read X10 s = ctr_lo /\
              read X15 s = word_ushr bit_len 3 /\
              read X17 s = (word 10:64 word) /\
              read X19 s = word_add key_ptr (word 160) /\
              read X13 s = lk_lo /\
              read X14 s = lk_hi /\
              read X4 s = word_add ptr0 (word_ushr bit_len 3) /\
              read X5 s = word_add ptr0
                (word_and (word_sub (word_ushr bit_len 3) (word 1))
                          (word 18446744073709551552:int64)) /\
              read X12 s = word_zx (word_subword (read X12 s) (0,32):int32) /\
              read Q6 s = q6_pre /\
              read Q7 s = q7_pre /\
              read Q31 s = rk9 /\
              read Q18 s = rk0 /\
              read Q19 s = rk1 /\
              read Q20 s = rk2 /\
              read Q21 s = rk3 /\
              read Q23 s = rk5 /\
              read Q24 s = rk6 /\
              read Q25 s = rk7 /\
              read Q12 s = byteswap128 (h_power (ghash_twist h) 0) /\
              read Q13 s = byteswap128 (h_power (ghash_twist h) 1) /\
              read Q14 s = byteswap128 (h_power (ghash_twist h) 2) /\
              read Q15 s = byteswap128 (h_power (ghash_twist h) 3) /\
              read Q16 s =
                (word_join (karatsuba_mid (h_power (ghash_twist h) 1):64 word)
                           (karatsuba_mid (h_power (ghash_twist h) 0):64 word)
                 :int128) /\
              read Q17 s =
                (word_join (karatsuba_mid (h_power (ghash_twist h) 3):64 word)
                           (karatsuba_mid (h_power (ghash_twist h) 2):64 word)
                 :int128) /\
              (read NF s <=>
               ival (word_sub ptr0
                              (word_add ptr0
                                 (word_and (word_sub (word_ushr bit_len 3) (word 1))
                                           (word 18446744073709551552:int64)))) < &0) /\
              (read VF s <=>
               ~(ival ptr0 - ival (word_add ptr0
                                     (word_and (word_sub (word_ushr bit_len 3) (word 1))
                                               (word 18446744073709551552:int64))) =
                 ival (word_sub ptr0
                                (word_add ptr0
                                   (word_and (word_sub (word_ushr bit_len 3) (word 1))
                                             (word 18446744073709551552:int64)))))) /\
              read (memory :> bytes64 ptr0) s = b0_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 8))) s = b0_hi /\
              read (memory :> bytes64 (word_add ptr0 (word 16))) s = b1_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 24))) s = b1_hi /\
              read (memory :> bytes64 (word_add ptr0 (word 32))) s = b2_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 40))) s = b2_hi /\
              read (memory :> bytes64 (word_add ptr0 (word 48))) s = b3_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 56))) s = b3_hi)
         (MAYCHANGE [PC; SP; X4; X5; X8; X9; X10; X11; X12; X13; X14; X15;
                     X16; X17; X19; X29] ,,
          MAYCHANGE [Q0; Q1; Q2; Q3; Q8; Q9; Q11;
                     Q12; Q13; Q14; Q15; Q16; Q17;
                     Q18; Q19; Q20; Q21; Q22; Q23; Q24; Q25;
                     Q26; Q27; Q28; Q29; Q30; Q31] ,,
          MAYCHANGE SOME_FLAGS ,,
          MAYCHANGE [memory :> bytes(word_sub stackpointer (word 128), 128)] ,,
          MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC (SPECL[`pc + 0x0:num`; `ptr0:int64`; `bit_len:int64`; `cptr:int64`;
                `tag_ptr:int64`; `ivec_ptr:int64`; `key_ptr:int64`;
                `htable_ptr:int64`; `stackpointer:int64`;
                `lk_lo:int64`; `lk_hi:int64`; `rk9:int128`;
                `ctr_lo:int64`; `ctr_hi:int64`; `ctr0:int128`;
                `rk0:int128`; `rk1:int128`; `rk2:int128`; `rk3:int128`;
                `rk5:int128`; `rk6:int128`; `rk7:int128`;
                `h:int128`; `q6_pre:int128`; `q7_pre:int128`;
                `b0_lo:int64`; `b0_hi:int64`; `b1_lo:int64`; `b1_hi:int64`;
                `b2_lo:int64`; `b2_hi:int64`; `b3_lo:int64`; `b3_hi:int64`]
               AES_GCM_MAIN_LOOP_PRELUDE_PRE_FIRSTBLOCKS_FLAG_X5_X12_PT_CORRECT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[NONOVERLAPPING_CLAUSES; ARITH_RULE `pc + 0 = pc`] THEN
    REWRITE_TAC[fst AES_GCM_MAIN_LOOP_PRELUDE_SLICE_EXEC;
                fst AES_GCM_ENC_KERNEL_EXEC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[fst AES_GCM_ENC_KERNEL_EXEC;
                                NONOVERLAPPING_CLAUSES]) THEN
    NONOVERLAPPING_TAC;
    REWRITE_TAC[ARITH_RULE `(pc + 0x0) + 0x244 = pc + 0x244`;
                ARITH_RULE `pc + 0x0 = pc`] THEN
    MATCH_MP_TAC (REWRITE_RULE[IMP_CONJ] ENSURES_PRECONDITION_THM) THEN
    GEN_TAC THEN STRIP_TAC THEN
    POP_ASSUM(STRIP_ASSUME_TAC o BETA_RULE) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL[`x:armstate`; `pc:num`] SLICE_TO_KERNEL_PRELUDE_LOAD) THEN
    ASM_REWRITE_TAC[ARITH_RULE `pc + 0 = pc`]]);;

