(* tail.  Adds PRE conjunct `read (memory :> bytes128 xiptr) s = initial_tag`.*)
(* ========================================================================= *)

let AES_GCM_ENC_KERNEL_BYTE_LEN_LE_32_BODY_FUNCTIONAL_CLOSED_CORRECT = prove
 (`!pc (ptr0:int64) (bit_len:int64) (cptr:int64) (xiptr:int64)
