              read X5 s = key_ptr /\
              read X6 s = htable_ptr /\
              read X16 s = ivec_ptr /\
              read X8 s = key_ptr /\
              read Q6 s = q6_pre /\
              read Q7 s = q7_pre /\
              read (memory :> bytes32 (word_add key_ptr (word 240))) s = (word 10:32 word) /\
