          MAYCHANGE [Q0; Q1; Q2; Q3; Q4; Q5; Q7; Q8; Q9; Q10; Q11;
                     Q12; Q13; Q14; Q15; Q16; Q17;
                     Q18; Q19; Q20; Q21; Q22; Q23; Q24; Q25;
                     Q26; Q27; Q28; Q29; Q30; Q31] ,,
          MAYCHANGE SOME_FLAGS ,,
          MAYCHANGE [memory :> bytes(word_sub stackpointer (word 128), 128)] ,,
          MAYCHANGE [memory :> bytes128 cptr;
                     memory :> bytes128 (word_add cptr (word 16));
                     memory :> bytes128 (word_add cptr (word 32));
                     memory :> bytes128 (word_add cptr (word 48));
                     memory :> bytes128 xiptr] ,,
          MAYCHANGE [memory :> bytes32 (word_add ivec_ptr (word 12))] ,,
          MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES;
                              fst AES_GCM_ENC_KERNEL_EXEC]) THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS]
    (SPECL[`pc:num`; `ptr0:int64`; `bit_len:int64`; `cptr:int64`;
           `xiptr:int64`; `ivec_ptr:int64`; `key_ptr:int64`;
           `htable_ptr:int64`; `stackpointer:int64`;
           `lk_lo:int64`; `lk_hi:int64`; `rk9:int128`;
           `ctr_lo:int64`; `ctr_hi:int64`; `ctr0:int128`;
           `rk0:int128`; `rk1:int128`; `rk2:int128`; `rk3:int128`;
           `rk5:int128`; `rk6:int128`; `rk7:int128`;
           `h:int128`; `q6_pre:int128`; `q7_pre:int128`;
           `b0_lo:int64`; `b0_hi:int64`; `b1_lo:int64`; `b1_hi:int64`;
           `b2_lo:int64`; `b2_hi:int64`; `b3_lo:int64`; `b3_hi:int64`]
          AES_GCM_MAIN_LOOP_PRELUDE_N0_KERNEL_CORRECT)) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[NONOVERLAPPING_CLAUSES; fst AES_GCM_ENC_KERNEL_EXEC] THEN
    ASM_REWRITE_TAC[] THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  ARM_BIGSTEP_TAC AES_GCM_ENC_KERNEL_EXEC "s_mid" THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS]
    (SPECL[`pc:num`;
           `ptr0:int64`;
           `word_add ptr0 (word_ushr bit_len 3):int64`;
           `word_subword (read X12 s_mid) (0,32):int32`;
           `lk_lo:int64`; `lk_hi:int64`;
           `word_ushr bit_len 3:int64`;
           `ivec_ptr:int64`;
           `cptr:int64`;
           `xiptr:int64`;
           `read Q0 s_mid:int128`;
           `read Q1 s_mid:int128`;
           `read Q2 s_mid:int128`;
           `read Q3 s_mid:int128`;
           `read Q10 s_mid:int128`;
           `read Q11 s_mid:int128`;
           `byteswap128 (h_power (ghash_twist h) 0):int128`;
           `byteswap128 (h_power (ghash_twist h) 1):int128`;
           `byteswap128 (h_power (ghash_twist h) 2):int128`;
           `byteswap128 (h_power (ghash_twist h) 3):int128`;
           `(word_join (karatsuba_mid (h_power (ghash_twist h) 1):64 word)
                       (karatsuba_mid (h_power (ghash_twist h) 0):64 word)
             :int128)`;
           `(word_join (karatsuba_mid (h_power (ghash_twist h) 3):64 word)
                       (karatsuba_mid (h_power (ghash_twist h) 2):64 word)
             :int128)`;
           `b0_lo:int64`; `b0_hi:int64`;
           `b1_lo:int64`; `b1_hi:int64`;
           `b2_lo:int64`; `b2_hi:int64`;
           `b3_lo:int64`; `b3_hi:int64`]
          AES_GCM_LENC_TAIL_N4_FULL_CLOSED_KERNEL_CORRECT)) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[NONOVERLAPPING_CLAUSES; fst AES_GCM_ENC_KERNEL_EXEC] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THEN
    NONOVERLAPPING_TAC;
    ALL_TAC] THEN
  ARM_BIGSTEP_TAC AES_GCM_ENC_KERNEL_EXEC "s_end" THENL
   [(* BIGSTEP residuals: X12 self-ref hyp + &48 < ival lower-bound bridge.
       N=4's tail PRE has only the lower bound; <=64 is wrapper-level only. *)
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
      `word_sub (word_add (ptr0:int64) (word_ushr bit_len 3)) ptr0 =
       word_ushr bit_len 3`
      SUBST1_TAC THENL
     [CONV_TAC WORD_RULE; ALL_TAC] THEN
    SUBGOAL_THEN
      `ival (word_ushr (bit_len:int64) 3) = &(val (word_ushr bit_len 3))`
      SUBST1_TAC THENL
     [MATCH_MP_TAC IVAL_EQ_VAL THEN
      REWRITE_TAC[DIMINDEX_64] THEN
      SIMP_TAC[ARITH_RULE `64 - 1 = 63`] THEN
      MATCH_MP_TAC LET_TRANS THEN EXISTS_TAC `64` THEN
      ASM_REWRITE_TAC[] THEN ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[INT_OF_NUM_LT] THEN ASM_REWRITE_TAC[];
    ENSURES_FINAL_STATE_TAC THEN
    ASM_REWRITE_TAC[] THEN
    MONOTONE_MAYCHANGE_TAC]);;

(* ==========================================================================
 * Phase 9b/10 (s097) — combined byte_len ≤ 64 whole-kernel control-flow
 *                       wrapper.
 *
 * Unifies the four per-N (N=1..4) byte_len-range wrappers
 * (BYTE_LEN_LE_{16,32,48,64_4}_CORRECT) into a single ensures over the
 * full byte_len range `1 ≤ val (word_ushr bit_len 3) ≤ 64`.  Each branch
 * dispatches to its sub-wrapper via `MATCH_MP_TAC` after widening the
 * MAYCHANGE frame with `ENSURES_FRAME_SUBSUMED` (sub-wrappers' MAYCHANGE
 * are tighter than the combined wrapper's MAYCHANGE in their per-N
 * ciphertext-store memory atoms; the combined wrapper unifies on N=4's
 * largest atom set and sub-cases widen via SUBSUMED_MAYCHANGE_TAC).
 *
 * The PRE shape uses `(ptr0, 64)` and `(cptr, 64)` (the N=4 superset);
 * sub-wrappers' tighter `(cptr, 16/32/48)` PREs are derived inside each
 * branch via `NONOVERLAPPING_TAC`.
 *
 * Case-split: ASM_CASES_TAC on `val (word_ushr bit_len 3) <= 16`,
 * `<= 32`, `<= 48`; the residual is N=4 (val > 48 ∧ val <= 64).
 *
 * N=1's MAYCHANGE has no `X2` and only `[bytes128 cptr; bytes128 xiptr]`
 * for ciphertext stores (1 block); N=2/3 add 1/2 more `bytes128`
 * atoms; N=4 has all four.  SUBSUMED_MAYCHANGE_TAC handles each
 * widening uniformly.
 * ========================================================================= *)

let AES_GCM_ENC_KERNEL_BYTE_LEN_LE_64_CORRECT = prove
 (`!pc (ptr0:int64) (bit_len:int64) (cptr:int64) (xiptr:int64)
       (ivec_ptr:int64) (key_ptr:int64) (htable_ptr:int64)
       (stackpointer:int64)
       (lk_lo:int64) (lk_hi:int64) (rk9:int128)
       (ctr_lo:int64) (ctr_hi:int64) (ctr0:int128)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128)
       (rk5:int128) (rk6:int128) (rk7:int128)
       (h:int128) (q6_pre:int128) (q7_pre:int128)
       (b0_lo:int64) (b0_hi:int64) (b1_lo:int64) (b1_hi:int64)
       (b2_lo:int64) (b2_hi:int64) (b3_lo:int64) (b3_hi:int64).
    aligned 16 stackpointer /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc)
                   (word_sub stackpointer (word 128), 128) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (htable_ptr, 96) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (ptr0, 64) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (cptr, 64) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (xiptr, 16) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc)
                   (word_add ivec_ptr (word 12), 4) /\
    nonoverlapping (key_ptr, 256) (word_sub stackpointer (word 128), 128) /\
    nonoverlapping (ivec_ptr, 16) (word_sub stackpointer (word 128), 128) /\
    nonoverlapping (htable_ptr, 96) (word_sub stackpointer (word 128), 128) /\
    nonoverlapping (ptr0, 64) (word_sub stackpointer (word 128), 128) /\
    nonoverlapping (cptr, 64) (xiptr, 16) /\
    nonoverlapping (cptr, 64) (word_add ivec_ptr (word 12), 4) /\
    nonoverlapping (xiptr, 16) (word_add ivec_ptr (word 12), 4) /\
    nonoverlapping (ptr0, 64) (cptr, 64) /\
    nonoverlapping (ptr0, 64) (xiptr, 16) /\
    nonoverlapping (ptr0, 64) (word_add ivec_ptr (word 12), 4) /\
    1 <= val (word_ushr bit_len 3) /\ val (word_ushr bit_len 3) <= 64
    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_enc_kernel_mc /\
              read PC s = word pc /\
              read SP s = stackpointer /\
              read X0 s = ptr0 /\
              read X1 s = bit_len /\
              read X2 s = cptr /\
              read X3 s = xiptr /\
              read X4 s = ivec_ptr /\
              read X5 s = key_ptr /\
              read X6 s = htable_ptr /\
              read Q6 s = q6_pre /\
              read Q7 s = q7_pre /\
              read (memory :> bytes32 (word_add key_ptr (word 240))) s = (word 10:32 word) /\
              read (memory :> bytes64 (word_add key_ptr (word 160))) s = lk_lo /\
              read (memory :> bytes64 (word_add key_ptr (word 168))) s = lk_hi /\
              read (memory :> bytes128 (word_add key_ptr (word 144))) s = rk9 /\
              read (memory :> bytes64 ivec_ptr) s = ctr_lo /\
              read (memory :> bytes64 (word_add ivec_ptr (word 8))) s = ctr_hi /\
              read (memory :> bytes128 ivec_ptr) s = ctr0 /\
              read (memory :> bytes128 key_ptr) s = rk0 /\
              read (memory :> bytes128 (word_add key_ptr (word 16))) s = rk1 /\
              read (memory :> bytes128 (word_add key_ptr (word 32))) s = rk2 /\
              read (memory :> bytes128 (word_add key_ptr (word 48))) s = rk3 /\
              read (memory :> bytes128 (word_add key_ptr (word 80))) s = rk5 /\
              read (memory :> bytes128 (word_add key_ptr (word 96))) s = rk6 /\
              read (memory :> bytes128 (word_add key_ptr (word 112))) s = rk7 /\
              read (memory :> bytes128 htable_ptr) s =
                byteswap128 (h_power (ghash_twist h) 0) /\
              read (memory :> bytes128 (word_add htable_ptr (word 32))) s =
                byteswap128 (h_power (ghash_twist h) 1) /\
              read (memory :> bytes128 (word_add htable_ptr (word 48))) s =
                byteswap128 (h_power (ghash_twist h) 2) /\
              read (memory :> bytes128 (word_add htable_ptr (word 80))) s =
                byteswap128 (h_power (ghash_twist h) 3) /\
              read (memory :> bytes64 ptr0) s = b0_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 8))) s = b0_hi /\
              read (memory :> bytes64 (word_add ptr0 (word 16))) s = b1_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 24))) s = b1_hi /\
              read (memory :> bytes64 (word_add ptr0 (word 32))) s = b2_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 40))) s = b2_hi /\
              read (memory :> bytes64 (word_add ptr0 (word 48))) s = b3_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 56))) s = b3_hi)
         (\s. read PC s = word (pc + 0x970))
         (MAYCHANGE [PC; SP; X0; X2; X4; X5; X6; X7; X8; X9; X10; X11; X12; X13;
                     X14; X15; X16; X17; X19; X29] ,,
          MAYCHANGE [Q0; Q1; Q2; Q3; Q4; Q5; Q7; Q8; Q9; Q10; Q11;
                     Q12; Q13; Q14; Q15; Q16; Q17;
                     Q18; Q19; Q20; Q21; Q22; Q23; Q24; Q25;
                     Q26; Q27; Q28; Q29; Q30; Q31] ,,
          MAYCHANGE SOME_FLAGS ,,
          MAYCHANGE [memory :> bytes(word_sub stackpointer (word 128), 128)] ,,
          MAYCHANGE [memory :> bytes128 cptr;
                     memory :> bytes128 (word_add cptr (word 16));
                     memory :> bytes128 (word_add cptr (word 32));
                     memory :> bytes128 (word_add cptr (word 48));
                     memory :> bytes128 xiptr] ,,
          MAYCHANGE [memory :> bytes32 (word_add ivec_ptr (word 12))] ,,
          MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_CASES_TAC `val (word_ushr (bit_len:int64) 3) <= 16` THENL
   [(* N=1: 1 ≤ val ≤ 16 *)
    MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
    EXISTS_TAC
     `MAYCHANGE [PC; SP; X0; X4; X5; X6; X7; X8; X9; X10; X11; X12; X13;
                 X14; X15; X16; X17; X19; X29] ,,
      MAYCHANGE [Q0; Q1; Q2; Q3; Q4; Q5; Q7; Q8; Q9; Q10; Q11;
                 Q12; Q13; Q14; Q15; Q16; Q17;
                 Q18; Q19; Q20; Q21; Q22; Q23; Q24; Q25;
                 Q26; Q27; Q28; Q29; Q30; Q31] ,,
      MAYCHANGE SOME_FLAGS ,,
      MAYCHANGE [memory :> bytes(word_sub stackpointer (word 128), 128)] ,,
      MAYCHANGE [memory :> bytes128 cptr;
                 memory :> bytes128 xiptr] ,,
      MAYCHANGE [memory :> bytes32 (word_add ivec_ptr (word 12))] ,,
      MAYCHANGE [events]:armstate->armstate->bool` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[SOME_FLAGS] THEN SUBSUMED_MAYCHANGE_TAC;
      MATCH_MP_TAC AES_GCM_ENC_KERNEL_BYTE_LEN_LE_16_CORRECT THEN
      ASM_REWRITE_TAC[] THEN
      REPEAT CONJ_TAC THEN
      TRY NONOVERLAPPING_TAC];
    POP_ASSUM(ASSUME_TAC o REWRITE_RULE[NOT_LE]) THEN
    ASM_CASES_TAC `val (word_ushr (bit_len:int64) 3) <= 32` THENL
     [(* N=2: 16 < val ≤ 32 *)
      MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
      EXISTS_TAC
       `MAYCHANGE [PC; SP; X0; X2; X4; X5; X6; X7; X8; X9; X10; X11; X12; X13;
                   X14; X15; X16; X17; X19; X29] ,,
        MAYCHANGE [Q0; Q1; Q2; Q3; Q4; Q5; Q7; Q8; Q9; Q10; Q11;
                   Q12; Q13; Q14; Q15; Q16; Q17;
                   Q18; Q19; Q20; Q21; Q22; Q23; Q24; Q25;
                   Q26; Q27; Q28; Q29; Q30; Q31] ,,
        MAYCHANGE SOME_FLAGS ,,
        MAYCHANGE [memory :> bytes(word_sub stackpointer (word 128), 128)] ,,
        MAYCHANGE [memory :> bytes128 cptr;
                   memory :> bytes128 (word_add cptr (word 16));
                   memory :> bytes128 xiptr] ,,
        MAYCHANGE [memory :> bytes32 (word_add ivec_ptr (word 12))] ,,
        MAYCHANGE [events]:armstate->armstate->bool` THEN
      CONJ_TAC THENL
       [REWRITE_TAC[SOME_FLAGS] THEN SUBSUMED_MAYCHANGE_TAC;
        MATCH_MP_TAC AES_GCM_ENC_KERNEL_BYTE_LEN_LE_32_CORRECT THEN
        ASM_REWRITE_TAC[] THEN
        REPEAT CONJ_TAC THEN
        TRY NONOVERLAPPING_TAC];
      POP_ASSUM(ASSUME_TAC o REWRITE_RULE[NOT_LE]) THEN
      ASM_CASES_TAC `val (word_ushr (bit_len:int64) 3) <= 48` THENL
       [(* N=3: 32 < val ≤ 48 *)
        MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
        EXISTS_TAC
         `MAYCHANGE [PC; SP; X0; X2; X4; X5; X6; X7; X8; X9; X10; X11; X12; X13;
                     X14; X15; X16; X17; X19; X29] ,,
          MAYCHANGE [Q0; Q1; Q2; Q3; Q4; Q5; Q7; Q8; Q9; Q10; Q11;
                     Q12; Q13; Q14; Q15; Q16; Q17;
                     Q18; Q19; Q20; Q21; Q22; Q23; Q24; Q25;
                     Q26; Q27; Q28; Q29; Q30; Q31] ,,
          MAYCHANGE SOME_FLAGS ,,
          MAYCHANGE [memory :> bytes(word_sub stackpointer (word 128), 128)] ,,
          MAYCHANGE [memory :> bytes128 cptr;
                     memory :> bytes128 (word_add cptr (word 16));
                     memory :> bytes128 (word_add cptr (word 32));
                     memory :> bytes128 xiptr] ,,
          MAYCHANGE [memory :> bytes32 (word_add ivec_ptr (word 12))] ,,
          MAYCHANGE [events]:armstate->armstate->bool` THEN
        CONJ_TAC THENL
         [REWRITE_TAC[SOME_FLAGS] THEN SUBSUMED_MAYCHANGE_TAC;
          MATCH_MP_TAC AES_GCM_ENC_KERNEL_BYTE_LEN_LE_48_CORRECT THEN
          ASM_REWRITE_TAC[] THEN
          REPEAT CONJ_TAC THEN
          TRY NONOVERLAPPING_TAC];
        (* N=4: 48 < val ≤ 64 *)
        POP_ASSUM(ASSUME_TAC o REWRITE_RULE[NOT_LE]) THEN
        MATCH_MP_TAC AES_GCM_ENC_KERNEL_BYTE_LEN_LE_64_4_CORRECT THEN
        ASM_REWRITE_TAC[] THEN
        REPEAT CONJ_TAC THEN
        TRY NONOVERLAPPING_TAC]]]);;

(* ==========================================================================
 * Phase 9b/10 (s097) — helper lemmas for byte_len > 64 wrapper antecedents.
 *
 * The PRELUDE_FULL_KERNEL_CORRECT theorem (used by the byte_len > 64 case
 * wrapper) requires three antecedents on byte_len:
 *
 *   (a) val ptr0 + 64 < 2 EXP 63
 *   (b) val ptr0 + 16 < val (ptr0 + ((byte_len_w - 1) AND ~63))
 *   (c) ival (ptr0 + 64) < ival (ptr0 + ((byte_len_w - 1) AND ~63))
 *
 * The expression `(byte_len_w - 1) AND ~63 = (byte_len_w - 1) DIV 64 * 64`
 * captures the start of the trailing residual region — equivalently, the
 * total bytes processed by FIRSTBLOCKS + main loop + prepretail.  These
 * helper lemmas reduce the cluttered antecedent shapes to algebraic
 * conditions on `val byte_len_w`.
 *
 * Note (s174: now handled — see the branch-TAKEN firstblocks chain above):
 * the `ival(ptr0+64) < ival(ptr0+M)` antecedent on PRELUDE_FULL_KERNEL is
 * strictly stronger than `val byte_len_w > 64`.  It actually requires
 * `M > 64`, equivalently `val byte_len_w > 128` (i.e. ≥ 129 bytes — at
 * least 2 main-loop iterations after the FIRSTBLOCKS region).  The
 * byte_len = 65..128 case (M = 64, so x5 = ptr0+64; FIRSTBLOCKS alone
 * fills the gap, NO main_loop iterations) takes a different control-flow
 * path through the prelude: the branch at offset 0x304 is
 * `b.ge .Lenc_prepretail` (target 0x5c8), and for (64,128] it IS TAKEN
 * (x0 = ptr0+64 = x5 after firstblocks, so the GE condition holds),
 * jumping directly to prepretail at 0x5c8 with K=0 main-loop iters.
 * (A not-taken `b.ge` would fall through to the main loop at 0x308, which
 * is the byte_len > 128 path.)  The branch-TAKEN firstblocks chain above
 * (..._TAKEN_CORRECT, landing PC = pc+0x5c8) is the (64,128] spine's
 * Stage A; cts = the 4 firstblocks, initial_tag = word_bytereverse(Xi_in).
 * ========================================================================= *)

let WORD_AND_NOT_63_LB = prove
 (`!byte_len_w:int64.
     64 < val byte_len_w /\ val byte_len_w < 2 EXP 63
     ==> 64 <=
         val (word_and (word_sub byte_len_w (word 1):int64)
                       (word 18446744073709551552:int64))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `(word 18446744073709551552:int64) = word_not (word 63:int64)`
    SUBST1_TAC THENL [CONV_TAC WORD_BLAST; ALL_TAC] THEN
  SUBGOAL_THEN `word 63:int64 = word (2 EXP 6 - 1):int64` SUBST1_TAC THENL
   [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
  REWRITE_TAC[VAL_WORD_AND_NOT_MASK_WORD] THEN
  SUBGOAL_THEN `val (word_sub byte_len_w (word 1):int64) = val byte_len_w - 1`
    SUBST1_TAC THENL
   [REWRITE_TAC[VAL_WORD_SUB_CASES; VAL_WORD_1] THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  SUBGOAL_THEN `1 <= (val (byte_len_w:int64) - 1) DIV 64` MP_TAC THENL
   [REWRITE_TAC[ARITH_RULE `1 <= n <=> ~(n = 0)`] THEN
    REWRITE_TAC[DIV_EQ_0; ARITH_EQ] THEN ASM_ARITH_TAC;
    ARITH_TAC]);;

let WORD_AND_NOT_63_UB = prove
 (`!byte_len_w:int64.
     1 <= val byte_len_w /\ val byte_len_w < 2 EXP 63
     ==> val (word_and (word_sub byte_len_w (word 1):int64)
                       (word 18446744073709551552:int64))
         <= val byte_len_w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `(word 18446744073709551552:int64) = word_not (word 63:int64)`
    SUBST1_TAC THENL [CONV_TAC WORD_BLAST; ALL_TAC] THEN
  SUBGOAL_THEN `word 63:int64 = word (2 EXP 6 - 1):int64` SUBST1_TAC THENL
   [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
  REWRITE_TAC[VAL_WORD_AND_NOT_MASK_WORD] THEN
  SUBGOAL_THEN `val (word_sub byte_len_w (word 1):int64) = val byte_len_w - 1`
    SUBST1_TAC THENL
   [REWRITE_TAC[VAL_WORD_SUB_CASES; VAL_WORD_1] THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  MATCH_MP_TAC LE_TRANS THEN EXISTS_TAC `val (byte_len_w:int64) - 1` THEN
  CONJ_TAC THENL [MESON_TAC[DIV_MUL_LE]; ARITH_TAC]);;

(* For the (64,128] band, M := (byte_len-1)&~63 = 64 exactly: byte_len-1 in    *)
(* [64,127], and masking off the low 6 bits leaves 64.  This pins M=64 so the  *)
(* (64,128] firstblocks-TAKEN spine's symbolic-M antecedents collapse to the   *)
(* concrete ptr0+64 form (used by SLICE_FULL_X0_LIFT_BODY_TAKEN's flag arm).   *)
let WORD_AND_NOT_63_EQ_64 = prove
 (`!byte_len_w:int64.
     64 < val byte_len_w /\ val byte_len_w <= 128
     ==> word_and (word_sub byte_len_w (word 1):int64)
                  (word 18446744073709551552:int64) = word 64`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC (MESON[VAL_EQ] `val (a:int64) = val (b:int64) ==> a = b`) THEN
  SUBGOAL_THEN
    `(word 18446744073709551552:int64) = word_not (word 63:int64)`
    SUBST1_TAC THENL [CONV_TAC WORD_BLAST; ALL_TAC] THEN
  SUBGOAL_THEN `word 63:int64 = word (2 EXP 6 - 1):int64` SUBST1_TAC THENL
   [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
  REWRITE_TAC[VAL_WORD_AND_NOT_MASK_WORD] THEN
  SUBGOAL_THEN `val (word_sub byte_len_w (word 1):int64) = val byte_len_w - 1`
    SUBST1_TAC THENL
   [REWRITE_TAC[VAL_WORD_SUB_CASES; VAL_WORD_1] THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[VAL_WORD; DIMINDEX_64] THEN CONV_TAC NUM_REDUCE_CONV THEN
  ABBREV_TAC `n = val (byte_len_w:int64)` THEN
  SUBGOAL_THEN `(n - 1) DIV 64 = 1` SUBST1_TAC THENL
   [MATCH_MP_TAC DIV_UNIQ THEN EXISTS_TAC `n - 65` THEN ASM_ARITH_TAC;
    ARITH_TAC]);;

(* ==========================================================================
 * Phase 9b/10 (s098) — existential PRE bridge helper for byte_len > 128.
 *
 * The MAIN_LOOP_WRAPPER_FULL_CORRECT (line ~8106) PRE quantifies
 *   ?(q4:int128) (q5:int128) (q6:int128) (q7:int128)
 *    (b0:int128) (b1:int128) (b2:int128)
 *    (ct0:int128) (ct1:int128) (ct2:int128) (ct3:int128).
 *      <byteswap identifications relating q4..q7 to ct0..ct3>
 * over the Q-state at PC=pc+0x308 entering the main loop.  After
 * PRELUDE_FULL_KERNEL_CORRECT (which puts Q4..Q7 in MAYCHANGE), the
 * concrete q4..q7 values at pc+0x308 are Hilbert-style witnesses
 * `read Q4 s_after_prelude`, etc.  The b0..b2 existentials similarly
 * bind to `read Q0/Q1/Q2 s_after_prelude`.
 *
 * The byteswap-identification conjuncts are *trivially satisfiable*:
 * - For q5/q6/q7 conjuncts, pick `cti := byteswap128 (rev64 qi)`; then
 *   `byteswap128 cti = byteswap128 (byteswap128 (rev64 qi)) = rev64 qi`
 *   by BYTESWAP128_INVOLUTION_LOCAL.
 * - For the q4 conjunct, pick
 *   `ct0 := word_xor T (byteswap128 (word_xor (rev64 q4) (byteswap128 T)))`
 *   where `T = initial_tag`; XOR self-cancellation + involution then
 *   discharge the equation.
 *
 * This helper isolates that algebraic content as a forall-exists statement
 * over q4..q7, initial_tag.  The wrapper proof can discharge the
 * existential PRE by:
 *   1. After PRELUDE BIGSTEP, instantiate `initial_tag :=
 *      read Q11 s_after_prelude`.
 *   2. MP_TAC this helper specialized to `read Q4..Q7 s_after_prelude`.
 *   3. STRIP off the existential via REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC.
 *   4. Use the witnessed ct0..ct3 + Hilbert q4..q7 + read Q0..Q2 b0..b2 as
 *      MAIN_LOOP_WRAPPER PRE existentials.
 *
 * Proof: 4 EXISTS_TAC instantiating the witnesses; REWRITE with INVOLUTION
 * collapses 3 of 4 conjuncts; ABBREV the q4-side byteswap intermediate;
 * WORD_BLAST handles XOR cancellation; final REWRITE with INVOLUTION closes.
 * ========================================================================= *)

let MAIN_LOOP_WRAPPER_BYTESWAP_EXISTS = prove
 (`!q4 q5 q6 q7 (initial_tag:int128).
    ?ct0 ct1 ct2 ct3.
      word_xor (aes_gcm_rev64_int128 q4) (byteswap128 initial_tag) =
              byteswap128 (word_xor initial_tag ct0) /\
      aes_gcm_rev64_int128 q5 = byteswap128 ct1 /\
      aes_gcm_rev64_int128 q6 = byteswap128 ct2 /\
      aes_gcm_rev64_int128 q7 = byteswap128 ct3`,
  REPEAT GEN_TAC THEN
  EXISTS_TAC `word_xor (initial_tag:int128) (byteswap128
                (word_xor (aes_gcm_rev64_int128 q4) (byteswap128 initial_tag)))` THEN
  EXISTS_TAC `byteswap128 (aes_gcm_rev64_int128 q5):int128` THEN
  EXISTS_TAC `byteswap128 (aes_gcm_rev64_int128 q6):int128` THEN
  EXISTS_TAC `byteswap128 (aes_gcm_rev64_int128 q7):int128` THEN
  REWRITE_TAC[BYTESWAP128_INVOLUTION_LOCAL] THEN
  ABBREV_TAC `Y:int128 = byteswap128 (word_xor (aes_gcm_rev64_int128 q4)
                                               (byteswap128 initial_tag))` THEN
  SUBGOAL_THEN
    `word_xor (initial_tag:int128) (word_xor initial_tag (Y:int128)) = Y`
    SUBST1_TAC THENL [CONV_TAC WORD_BLAST; ALL_TAC] THEN
  EXPAND_TAC "Y" THEN
  REWRITE_TAC[BYTESWAP128_INVOLUTION_LOCAL]);;

(* ==========================================================================
 * Phase 9b/10 (s100) — N-iteration count helpers for byte_len > 128 wrapper.
 *
 * The byte_len > 128 wrapper composition needs to compute the
 * MAIN_LOOP_WRAPPER's iteration count `N` from byte_len.  After the prelude,
 *
 *   x0_after_prelude = ptr0 + 64
 *   x5_init           = ptr0 + M    where M = (byte_len_w - 1) AND ~63.
 *
 * MAIN_LOOP_WRAPPER's antecedents include:
 *   ~(N = 0)
 *   word_add x0_init (word (64*N)) = x5_init
 *   val x0_init + 64*N < 2 EXP 63
 *
 * Substituting x0_init = ptr0+64 and x5_init = ptr0+M:
 *   ~(N = 0)
 *   word_add (word_add ptr0 (word 64)) (word (64*N)) = word_add ptr0 (word M)
 *   val (word_add ptr0 (word 64)) + 64*N < 2 EXP 63
 *
 * The natural choice is N := (M - 64) / 64 = ((byte_len_w-1) AND ~63 - 64) / 64.
 *
 * For byte_len > 128 (i.e. val byte_len_w >= 129), M >= 128 so N >= 1, hence
 * `~(N = 0)`.  Below: N nonzero helper.  The arithmetic identity
 * `word_add (word_add ptr0 (word 64)) (word (64*N)) = word_add ptr0 (word M)`
 * follows from M = 64 + 64*N (provable via DIVISION_SIMP since M is a
 * multiple of 64) plus word_add associativity.
 * ========================================================================= *)

let MAIN_LOOP_WRAPPER_N_NONZERO = prove
 (`!byte_len_w:int64.
     128 < val byte_len_w /\ val byte_len_w < 2 EXP 63
     ==> ~(((val (word_and (word_sub byte_len_w (word 1):int64)
                           (word 18446744073709551552:int64)) - 64) DIV 64) = 0)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `(word 18446744073709551552:int64) = word_not (word 63:int64)`
    SUBST1_TAC THENL [CONV_TAC WORD_BLAST; ALL_TAC] THEN
  SUBGOAL_THEN `word 63:int64 = word (2 EXP 6 - 1):int64` SUBST1_TAC THENL
   [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
  REWRITE_TAC[VAL_WORD_AND_NOT_MASK_WORD] THEN
  SUBGOAL_THEN `val (word_sub byte_len_w (word 1):int64) = val byte_len_w - 1`
    SUBST1_TAC THENL
   [REWRITE_TAC[VAL_WORD_SUB_CASES; VAL_WORD_1] THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  SUBGOAL_THEN `2 <= (val (byte_len_w:int64) - 1) DIV 64` MP_TAC THENL
   [SIMP_TAC[ARITH_RULE `2 <= n DIV 64 <=> 128 <= n`] THEN ASM_ARITH_TAC;
    ARITH_TAC]);;

(* Helper: arithmetic identity tying x0_after_prelude + word(64*N) to x5_init.
 *
 * For byte_len > 128, with M = (byte_len_w - 1) AND ~63 and N = (M-64)/64:
 *   word_add (word_add ptr0 (word 64)) (word (64 * N)) = word_add ptr0 (word M).
 *
 * Composes with [[main_loop_wrapper_n_nonzero]] to discharge the
 * MAIN_LOOP_WRAPPER PRE conjunct
 *   `word_add x0_init (word (64 * N)) = x5_init`
 * after binding x0_init := word_add ptr0 (word 64), x5_init := word_add ptr0 M.
 *)

let MAIN_LOOP_WRAPPER_X0_ADD_X5 = prove
 (`!ptr0:int64 byte_len_w:int64.
     128 < val byte_len_w /\ val byte_len_w < 2 EXP 63
     ==> word_add (word_add ptr0 (word 64))
                  (word (64 *
                         (val (word_and (word_sub byte_len_w (word 1):int64)
                                        (word 18446744073709551552:int64)) - 64)
                         DIV 64)) =
         word_add ptr0
                  (word_and (word_sub byte_len_w (word 1):int64)
                            (word 18446744073709551552:int64))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `(word 18446744073709551552:int64) = word_not (word 63:int64)`
    SUBST1_TAC THENL [CONV_TAC WORD_BLAST; ALL_TAC] THEN
  ABBREV_TAC
    `mask_w:int64 = word_and (word_sub (byte_len_w:int64) (word 1))
                             (word_not (word 63:int64))` THEN
  SUBGOAL_THEN
    `val (mask_w:int64) MOD 64 = 0 /\
     128 <= val mask_w /\
     val mask_w <= val (byte_len_w:int64) - 1`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "mask_w" THEN
    SUBGOAL_THEN `word_not (word 63:int64) = word_not (word (2 EXP 6 - 1):int64)`
      SUBST1_TAC THENL [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
    REWRITE_TAC[VAL_WORD_AND_NOT_MASK_WORD] THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    SUBGOAL_THEN `val (word_sub byte_len_w (word 1):int64) = val byte_len_w - 1`
      SUBST1_TAC THENL
     [REWRITE_TAC[VAL_WORD_SUB_CASES; VAL_WORD_1] THEN
      COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [SIMP_TAC[MOD_MULT; ARITH_EQ];
      SIMP_TAC[ARITH_RULE `128 <= 64 * n <=> 2 <= n`;
               ARITH_RULE `2 <= n DIV 64 <=> 128 <= n`] THEN ASM_ARITH_TAC;
      MESON_TAC[DIV_MUL_LE]];
    ALL_TAC] THEN
  SUBGOAL_THEN `64 * (val (mask_w:int64) - 64) DIV 64 = val mask_w - 64`
    SUBST1_TAC THENL
   [MP_TAC (CONJUNCT2 DIVISION_SIMP) THEN
    DISCH_THEN(MP_TAC o SPECL[`val (mask_w:int64)`; `64`]) THEN
    ASM_REWRITE_TAC[ADD_CLAUSES] THEN DISCH_TAC THEN
    POP_ASSUM(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[ARITH_RULE `64 * x - 64 = 64 * (x - 1)`; MOD_MULT] THEN
    SIMP_TAC[DIV_MULT; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN `word (val (mask_w:int64) - 64):int64 = word_sub mask_w (word 64)`
    SUBST1_TAC THENL
   [REWRITE_TAC[GSYM VAL_EQ; VAL_WORD] THEN
    REWRITE_TAC[VAL_WORD_SUB_CASES; VAL_WORD; DIMINDEX_64] THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    COND_CASES_TAC THENL
     [POP_ASSUM(K ALL_TAC) THEN MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      POP_ASSUM MP_TAC THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  CONV_TAC WORD_RULE);;

(* Helper: val(x0_after_prelude) + 64*N upper bound.
 *
 * For byte_len > 128 with `val ptr0 + val byte_len_w <= 2 EXP 63` (the
 * standard buffer-fits-in-int64 condition), the MAIN_LOOP_WRAPPER's
 * antecedent `val x0_init + 64 * N < 2 EXP 63` holds when binding
 * x0_init := word_add ptr0 (word 64) and N := (M-64)/64.
 *
 * Composes with [[main_loop_wrapper_n_nonzero]] and
 * [[main_loop_wrapper_x0_add_x5]].
 *)

let MAIN_LOOP_WRAPPER_X0_OVERFLOW_BOUND = prove
 (`!ptr0:int64 byte_len_w:int64.
     128 < val byte_len_w /\ val byte_len_w < 2 EXP 63 /\
     val ptr0 + val byte_len_w <= 2 EXP 63
     ==> val (word_add ptr0 (word 64):int64) +
         64 * (val (word_and (word_sub byte_len_w (word 1):int64)
                             (word 18446744073709551552:int64)) - 64) DIV 64
         < 2 EXP 63`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `(word 18446744073709551552:int64) = word_not (word 63:int64)`
    SUBST1_TAC THENL [CONV_TAC WORD_BLAST; ALL_TAC] THEN
  ABBREV_TAC
    `mask_w:int64 = word_and (word_sub (byte_len_w:int64) (word 1))
                             (word_not (word 63:int64))` THEN
  SUBGOAL_THEN `val (mask_w:int64) <= val (byte_len_w:int64) - 1` ASSUME_TAC THENL
   [EXPAND_TAC "mask_w" THEN
    SUBGOAL_THEN `word_not (word 63:int64) = word_not (word (2 EXP 6 - 1):int64)`
      SUBST1_TAC THENL [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
    REWRITE_TAC[VAL_WORD_AND_NOT_MASK_WORD] THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    SUBGOAL_THEN `val (word_sub byte_len_w (word 1):int64) = val byte_len_w - 1`
      SUBST1_TAC THENL
     [REWRITE_TAC[VAL_WORD_SUB_CASES; VAL_WORD_1] THEN
      COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    MESON_TAC[DIV_MUL_LE];
    ALL_TAC] THEN
  MP_TAC(SPECL[`val (mask_w:int64) - 64`; `64`] DIV_MUL_LE) THEN
  MP_TAC(ISPECL[`ptr0:int64`; `word 64:int64`] VAL_WORD_ADD_CASES) THEN
  REWRITE_TAC[VAL_WORD; DIMINDEX_64] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  COND_CASES_TAC THENL
   [ASM_ARITH_TAC;
    POP_ASSUM MP_TAC THEN ASM_ARITH_TAC]);;
(* MAIN_LOOP_WRAPPER_FULL_NOEXISTS_CORRECT:
 *
 * Variant of AES_GCM_MAIN_LOOP_WRAPPER_FULL_CORRECT where the existentially-
 * quantified PRE conjunct (?(q4..q7)(b0..b2)(ct0..ct3). <byteswap ids>) is
 * unfolded with outer-quantified witnesses.  Used by the byte_len > 128
 * wrapper composition (s101).
 *)

let MAIN_LOOP_WRAPPER_FULL_NOEXISTS_CORRECT = prove
 (`!pc (cptr:int64) (x0_init:int64) (x5_init:int64) (N:num)
       (h:int128) (initial_tag:int128)
       (q12:int128) (q13:int128) (q14:int128) (q15:int128)
       (q16:int128) (q17:int128)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128) (rk4:int128)
       (rk5:int128) (rk6:int128) (rk7:int128) (rk8:int128) (rk9:int128)
       (sx10:int64) (sx13:int64) (sx14:int64)
       (q4:int128) (q5:int128) (q6:int128) (q7:int128)
       (b0:int128) (b1:int128) (b2:int128)
       (ct0:int128) (ct1:int128) (ct2:int128) (ct3:int128).
   ~(N = 0) /\
   nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (cptr, 64*N) /\
   word_add x0_init (word(64*N)) = x5_init /\
   val x0_init + 64 * N < 2 EXP 63 /\
   q15 = byteswap128 (h_power (ghash_twist h) 3) /\
   q14 = byteswap128 (h_power (ghash_twist h) 2) /\
   q13 = byteswap128 (h_power (ghash_twist h) 1) /\
   q12 = byteswap128 (h_power (ghash_twist h) 0) /\
   q17 = (word_join (karatsuba_mid (h_power (ghash_twist h) 3) :64 word)
                    (karatsuba_mid (h_power (ghash_twist h) 2) :64 word)
          :int128) /\
   q16 = (word_join (karatsuba_mid (h_power (ghash_twist h) 1) :64 word)
                    (karatsuba_mid (h_power (ghash_twist h) 0) :64 word)
          :int128) /\
   word_xor (aes_gcm_rev64_int128 q4) (byteswap128 initial_tag) =
     byteswap128 (word_xor initial_tag ct0) /\
   aes_gcm_rev64_int128 q5 = byteswap128 ct1 /\
   aes_gcm_rev64_int128 q6 = byteswap128 ct2 /\
   aes_gcm_rev64_int128 q7 = byteswap128 ct3
   ==> ensures arm
        (\s. aligned_bytes_loaded s (word pc) aes_gcm_enc_kernel_mc /\
             read PC s = word (pc + 0x308) /\
             read X0 s = x0_init /\
             read X2 s = cptr /\
             read X5 s = x5_init /\
             read Q0 s = b0 /\
             read Q1 s = b1 /\
             read Q2 s = b2 /\
             read Q4 s = q4 /\
             read Q5 s = q5 /\
             read Q6 s = q6 /\
             read Q7 s = q7 /\
             read Q11 s = initial_tag /\
             read Q12 s = q12 /\
             read Q13 s = q13 /\
             read Q14 s = q14 /\
             read Q15 s = q15 /\
             read Q16 s = q16 /\
             read Q17 s = q17 /\
             read Q18 s = rk0 /\
             read Q19 s = rk1 /\
             read Q20 s = rk2 /\
             read Q21 s = rk3 /\
             read Q22 s = rk4 /\
             read Q23 s = rk5 /\
             read Q24 s = rk6 /\
             read Q25 s = rk7 /\
             read Q26 s = rk8 /\
             read Q31 s = rk9 /\
             read X10 s = sx10 /\
             read X13 s = sx13 /\
             read X14 s = sx14)
        (\s. read PC s = word (pc + 0x5c8) /\
             read X0 s = x5_init /\
             read X2 s = word_add cptr (word(64*N)) /\
             read X5 s = x5_init /\
             read Q12 s = q12 /\
             read Q13 s = q13 /\
             read Q14 s = q14 /\
             read Q15 s = q15 /\
             read Q16 s = q16 /\
             read Q17 s = q17 /\
             read Q18 s = rk0 /\
             read Q19 s = rk1 /\
             read Q20 s = rk2 /\
             read Q21 s = rk3 /\
             read Q22 s = rk4 /\
             read Q23 s = rk5 /\
             read Q24 s = rk6 /\
             read Q25 s = rk7 /\
             read Q26 s = rk8 /\
             read Q31 s = rk9 /\
             read X10 s = sx10 /\
             read X13 s = sx13 /\
             read X14 s = sx14 /\
             (?cts. LENGTH cts = 4 * N /\
                    read Q11 s = nist_ghash h initial_tag cts))
        (MAYCHANGE [PC] ,,
         MAYCHANGE [Q0; Q1; Q2; Q3; Q4; Q5; Q6; Q7; Q8; Q9; Q10; Q11] ,,
         MAYCHANGE [X0; X2; X6; X7; X9; X12; X19; X20; X21; X22; X23; X24] ,,
         MAYCHANGE SOME_FLAGS ,,
         MAYCHANGE [memory :> bytes(cptr, 64*N)] ,,
         MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL
    [`pc:num`; `cptr:int64`; `x0_init:int64`; `x5_init:int64`; `N:num`;
     `h:int128`; `initial_tag:int128`;
     `q12:int128`; `q13:int128`; `q14:int128`; `q15:int128`;
     `q16:int128`; `q17:int128`;
     `rk0:int128`; `rk1:int128`; `rk2:int128`; `rk3:int128`; `rk4:int128`;
     `rk5:int128`; `rk6:int128`; `rk7:int128`; `rk8:int128`; `rk9:int128`;
     `sx10:int64`; `sx13:int64`; `sx14:int64`]
    AES_GCM_MAIN_LOOP_WRAPPER_FULL_CORRECT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC (REWRITE_RULE[IMP_CONJ] ENSURES_PRECONDITION_THM) THEN
  GEN_TAC THEN STRIP_TAC THEN
  POP_ASSUM(STRIP_ASSUME_TAC o BETA_RULE) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY EXISTS_TAC
    [`q4:int128`; `q5:int128`; `q6:int128`; `q7:int128`;
     `b0:int128`; `b1:int128`; `b2:int128`;
     `ct0:int128`; `ct1:int128`; `ct2:int128`; `ct3:int128`] THEN
  ASM_REWRITE_TAC[]);;


(* ------------------------------------------------------------------------- *)
(* Phase 11b G1 (s199, GT_128 ciphertext threading) — foundational leaf.     *)
(*                                                                           *)
(* The GT_128 (byte_len > 128) path threads the 4 firstblocks ciphertext     *)
(* cells (written at the original cptr, offsets 0/16/32/48) THROUGH the      *)
(* multi-iteration main loop.  The main loop runs with X2 = cptr+64 (after   *)
(* firstblocks advanced it), so the loop's write region [cptr+64, +64*N) is  *)
(* DISJOINT from the firstblocks cells [cptr, +64).  This is the loop-level  *)
(* analogue of the s195 `_CPTR` tail (distinct-pointer cell passthrough), but *)
(* the (64,128] band had no main loop so this capability is new for GT_128.  *)
(*                                                                           *)
(* Two lemmas:                                                               *)
(*   WRAPPER_FRAME_PRESERVES_DISTINCT_CELLS — the NOEXISTS loop frame         *)
(*     (which writes memory:>bytes(cptr,n)) preserves bytes128(prev_cptr+16j) *)
(*     for j<4, given nonoverlapping (prev_cptr,64) (cptr,n).  Closes via     *)
(*     the MAYCHANGE→ASSIGNS→READ_OVER_WRITE_ORTHOGONAL chain (SOME_FLAGS     *)
(*     unfolded so the seq reduces to a bare write-chain, per s195).          *)
(*   AES_GCM_MAIN_LOOP_WRAPPER_FULL_NOEXISTS_PREVCELLS_CORRECT — strengthens   *)
(*     MAIN_LOOP_WRAPPER_FULL_NOEXISTS_CORRECT with the 4 generic-valued cells *)
(*     g 0..g 3 carried in both PRE and POST, via ENSURES_THREAD_PRIOR_CELLS  *)
(*     (the s159 B1 loop-threading helper) discharging the frame premise with *)
(*     the lemma above (n := 64*N).  The cell values g j stay generic here;   *)
(*     a later compose step pins them to the firstblocks AES-spec ciphertext. *)
(* ------------------------------------------------------------------------- *)

let WRAPPER_FRAME_PRESERVES_DISTINCT_CELLS = prove
 (`!(prev_cptr:int64) (cptr:int64) (n:num).
      nonoverlapping (prev_cptr,64) (cptr,n)
      ==> (!s s2.
            (MAYCHANGE [PC] ,,
             MAYCHANGE [Q0; Q1; Q2; Q3; Q4; Q5; Q6; Q7; Q8; Q9; Q10; Q11] ,,
             MAYCHANGE [X0; X2; X6; X7; X9; X12; X19; X20; X21; X22; X23; X24] ,,
             MAYCHANGE SOME_FLAGS ,,
             MAYCHANGE [memory :> bytes(cptr:int64, n)] ,,
             MAYCHANGE [events]) s s2
            ==> (!j. j < 4
                     ==> read (memory :> bytes128 (word_add prev_cptr (word(16*j)))) s2 =
                         read (memory :> bytes128 (word_add prev_cptr (word(16*j)))) s))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  REPEAT GEN_TAC THEN
  REWRITE_TAC[MAYCHANGE; SEQ_ID; GSYM SEQ_ASSOC] THEN
  PURE_REWRITE_TAC[ASSIGNS_SEQ] THEN
