    ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC MAIN_LOOP_WRAPPER_N_NONZERO THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN
