let SLICE_FULL_X0_LIFT_STRONG = prove
 (`!pc (ptr0:int64) (bit_len:int64) (cptr:int64) (tag_ptr:int64)
       (ivec_ptr:int64) (key_ptr:int64) (htable_ptr:int64)
