    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_main_loop_prelude_slice_mc /\
              read PC s = word pc /\
              read SP s = stackpointer /\
              read X0 s = ptr0 /\
              read X1 s = bit_len /\
              read X2 s = cptr /\
              read X3 s = tag_ptr /\
              read X4 s = ivec_ptr /\
              read X5 s = key_ptr /\
