    ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* Phase 11b Stage 3 / C1 (s171) — GT_128 LE FUNCTIONAL REPLAY.              *)
(*                                                                           *)
(* Functional (NIST-GHASH) siblings of the four X12-only body wrappers       *)
(* AES_GCM_ENC_KERNEL_BYTE_LEN_GT_128_LE_{16,32,48,64}_BODY_CORRECT above.   *)
(* Each swaps Stage 1 from the Q11-silent                                    *)
(* ..._PREPRETAIL_STRONG_X12_BODY_CORRECT to the s170                        *)
(* ..._PREPRETAIL_STRONG_X12_NIST_BODY_CORRECT (whose POST threads the       *)
(* running GHASH tag ?initial_tag cts. read Q11 s = nist_ghash h initial_tag *)
(* cts), and Stage 2 from AES_GCM_LENC_TAIL_N{k}_FULL_KERNEL_CORRECT to      *)
(* ..._FUNCTIONAL_CORRECT (whose POST exposes the byte-memory GHASH tag at   *)
(* xiptr).  The composed POST therefore exposes the genuine running tag      *)
(*                                                                           *)
(*   ?initial_tag cts q0_post .. q{N-1}_post.                                *)
(*     LENGTH cts = 4*K + 4 /\                                               *)
(*     read (memory :> bytes128 xiptr) s =                                   *)
(*       word_bytereverse(nist_ghash h (nist_ghash h initial_tag cts)        *)
(*         [word_bytereverse ct0; ..; word_bytereverse ct{N-1}])             *)
(*                                                                           *)
(* where K = (mask_w - 64) DIV 64 main-loop iterations (so cts holds the     *)
(* 4*(K+1) main-loop+prelude blocks) and ct0..ct{N-1} are the N trailing     *)
(* tail blocks.  The nested nist_ghash is what consumes STRONG_X12_NIST's    *)
(* Q11 = running tag — an opaque ?prev_tag POST would be derivable from the  *)
(* X12-silent base too, defeating C1's purpose.                             *)
(*                                                                           *)
(* Proof shape (per N): Stage-1 NIST body BIGSTEP to s_mid; ABBREV           *)
(* q11_mid/q0_mid/../q{N-1}_mid (+ q3_mid/q10_mid for N=4) BEFORE Stage 2,   *)
(* per [[abbrev_state_read_before_bigstep]] (q11_mid folds to nist_ghash h   *)
(* initial_tag cts); MP the N{k} FUNCTIONAL tail with q11_in := q11_mid;     *)
(* discharge the H-power subword ANTS via REWRITE[h_power] + REPEAT CONJ_TAC *)
(* + TRY NONOVERLAPPING_TAC + SIMP[..JOIN_LOWER;JOIN_UPPER..] +              *)
(* REWRITE[GSYM DIMINDEX_64; WORD_SUBWORD_N_EQUAL] (order-independent, per   *)
(* [[c2_le_body_functional_replay]]); BIGSTEP to s_end with X12 self-ref via *)
(* FIRST_ASSUM ACCEPT_TAC (NOT bare ASM_REWRITE — [[asm_rewrite_x12_selfref_close]]) *)
(* + IVAL_EQ_VAL byte_len bridge; close the eventually existential by        *)
(* SUBST1(SYM) of the q11_mid = nist_ghash abbreviation so the goal's        *)
(* running-tag form rewrites back to q11_mid, then MATCH_ACCEPT the tail     *)
(* POST hyp.                                                                 *)
(* ========================================================================= *)

let AES_GCM_ENC_KERNEL_BYTE_LEN_GT_128_LE_16_BODY_FUNCTIONAL_CORRECT = prove
 (`!pc (ptr0:int64) (bit_len:int64) (cptr:int64) (xiptr:int64)
       (ivec_ptr:int64) (key_ptr:int64) (htable_ptr:int64)
       (stackpointer:int64)
       (lk_lo:int64) (lk_hi:int64) (rk9:int128)
       (ctr_lo:int64) (ctr_hi:int64) (ctr0:int128)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128)
       (rk5:int128) (rk6:int128) (rk7:int128)
       (h:int128) (q6_pre:int128) (q7_pre:int128)
       (b0_lo:int64) (b0_hi:int64) (b1_lo:int64) (b1_hi:int64)
       (b2_lo:int64) (b2_hi:int64) (b3_lo:int64) (b3_hi:int64)
       (bt_lo:int64) (bt_hi:int64)
       (byte_len_w:int64) (cptr_tail:int64) (ptr0_tail:int64).
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (htable_ptr, 96) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (cptr, 64) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc)
                   (word_add cptr (word 64),
                    val (word_and (word_sub byte_len_w (word 1):int64)
                                  (word 18446744073709551552:int64)) - 64) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (cptr_tail, 16) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (ptr0_tail, 16) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (xiptr, 16) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc)
                   (word_add ivec_ptr (word 12), 4) /\
    nonoverlapping (cptr_tail, 16) (xiptr, 16) /\
    nonoverlapping (cptr_tail, 16) (word_add ivec_ptr (word 12), 4) /\
    nonoverlapping (xiptr, 16) (word_add ivec_ptr (word 12), 4) /\
    nonoverlapping (ptr0_tail, 16) (cptr_tail, 16) /\
    nonoverlapping (ptr0_tail, 16) (xiptr, 16) /\
    nonoverlapping (ptr0_tail, 16) (word_add ivec_ptr (word 12), 4) /\
    nonoverlapping (ptr0_tail, 16) (cptr, 64) /\
    nonoverlapping (ptr0_tail, 16) (word_add cptr (word 64),
                                    val (word_and (word_sub byte_len_w (word 1):int64)
                                                  (word 18446744073709551552:int64)) - 64) /\
    word_ushr bit_len 3 = byte_len_w /\
    cptr_tail = word_add cptr
                  (word (val (word_and (word_sub byte_len_w (word 1):int64)
                                       (word 18446744073709551552:int64)))) /\
    ptr0_tail = word_add ptr0
                  (word_and (word_sub byte_len_w (word 1):int64)
                            (word 18446744073709551552:int64)) /\
    128 < val byte_len_w /\
    val byte_len_w < 2 EXP 63 /\
    val ptr0 + val byte_len_w <= 2 EXP 63 /\
    val (word_sub byte_len_w
          (word_and (word_sub byte_len_w (word 1):int64)
                    (word 18446744073709551552:int64))) <= 16
    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_enc_kernel_mc /\
              read PC s = word (pc + 0x2c) /\
              read SP s = word_sub stackpointer (word 128) /\
              read X0 s = ptr0 /\
              read X1 s = bit_len /\
              read X2 s = cptr /\
              read X3 s = xiptr /\
              read X4 s = ivec_ptr /\
              read X5 s = key_ptr /\
              read X6 s = htable_ptr /\
              read X16 s = ivec_ptr /\
              read X8 s = key_ptr /\
              read Q6 s = q6_pre /\
              read Q7 s = q7_pre /\
              read (memory :> bytes32 (word_add key_ptr (word 240))) s = (word 10:32 word) /\
              read (memory :> bytes64 (word_add key_ptr (word 160))) s = lk_lo /\
              read (memory :> bytes64 (word_add key_ptr (word 168))) s = lk_hi /\
              read (memory :> bytes128 (word_add key_ptr (word 144))) s = rk9 /\
              read (memory :> bytes64 ivec_ptr) s = ctr_lo /\
              read (memory :> bytes64 (word_add ivec_ptr (word 8))) s = ctr_hi /\
              read (memory :> bytes128 ivec_ptr) s = ctr0 /\
              read (memory :> bytes128 key_ptr) s = rk0 /\
              read (memory :> bytes128 (word_add key_ptr (word 16))) s = rk1 /\
