  ABBREV_TAC `q11_mid:int128 = read Q11 s_mid` THEN
  ABBREV_TAC `q0_mid:int128 = read Q0 s_mid` THEN
  ABBREV_TAC `q1_mid:int128 = read Q1 s_mid` THEN
  ABBREV_TAC `q2_mid:int128 = read Q2 s_mid` THEN
