(* ========================================================================= *)
(* Phase 11b G1 (s197) — 4-way (64,128] band AES body combinator.            *)
(*                                                                           *)
(* Combines the s196/s197 per-N (64,128] AES body wrappers (LE_16/32/48/64)  *)
(* into a single body theorem.  POST: 4 UNGUARDED cptr-blocks-0..3 spec      *)
(* conjuncts (firstblocks ciphertext, identical across all N) PLUS the 4     *)
(* band-guarded GHASH-tail existentials (one per N, copied from the s176     *)
(* CLOSED 4-way combinator).  Clone of the s176 CLOSED combinator's          *)
(* ASM_CASES dispatch nest, with each per-N MP swapped to the _AES variant   *)
(* (adding rk4/rk8 + key reads + the 3 caller-obligation nonoverlapping      *)
(* (key_ptr,256) / (cptr,64) vs xiptr / vs ivec+12).  THREAD_BRIDGE_TAC      *)
(* close per [[c3_c4_functional_combinator_recipe]].                         *)
(* ========================================================================= *)

let AES_GCM_ENC_KERNEL_BYTE_LEN_64_TO_128_BODY_FUNCTIONAL_CLOSED_AES_CORRECT = prove
 (`!pc (ptr0:int64) (bit_len:int64) (cptr:int64) (xiptr:int64)
       (ivec_ptr:int64) (key_ptr:int64) (htable_ptr:int64)
       (stackpointer:int64)
       (lk_lo:int64) (lk_hi:int64) (rk9:int128)
       (ctr_lo:int64) (ctr_hi:int64) (ctr0:int128)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128) (rk4:int128)
       (rk5:int128) (rk6:int128) (rk7:int128) (rk8:int128)
       (h:int128) (q6_pre:int128) (q7_pre:int128) (initial_tag:int128)
