let AES_GCM_ENC_KERNEL_BYTE_LEN_GT_128_LE_16_BODY_FUNCTIONAL_CLOSED_AES_CORRECT = prove
 (`!pc (ptr0:int64) (bit_len:int64) (cptr:int64) (xiptr:int64)
