   not(sub_in "MAYCHANGE" s) && not(sub_in "byte_list" s) in
 (fun (asl,w) -> (MAP_EVERY (fun (_,th)->MP_TAC th) (filter small asl) THEN ARITH_TAC) (asl,w))))]);;


(* ========================================================================= *)
(* Phase 11b (s210) — CORE PUBLIC byte_list_at presentation theorem, LE_16.   *)
(* Wraps AES_GCM_ENC_KERNEL_BYTE_LEN_LE_16_BODY_FUNCTIONAL_CLOSED_AES_CORRECT *)
(* (@43141) with a byte_list_at-form ciphertext POST (mirrors AES256_XTS).    *)
(* ========================================================================= *)

(* byte_list_at lives in aes_xts_common.ml, outside this file's needs-chain;
   define locally (identical definition). *)
let byte_list_at = define
  `byte_list_at (m : byte list) (m_p : int64) (len: int64) s =
    ! i. i < val len ==> read (memory :> bytes8(word_add m_p (word i))) s = EL i m`;;

(* Thread a byte_list_at window through an ensures POST given frame
   preservation + PRE pinning.  bytes8/byte_list_at analogue of
   ENSURES_ADD_QUANT_MEM_TO_POST. *)
let ENSURES_ADD_BYTE_LIST_AT_TO_POST = prove
 (`!(m:byte list) (m_p:int64) (len:int64) step (P:armstate->bool) Q R.
    (!s s2. R s s2
            ==> (!i. i < val len
                     ==> read (memory :> bytes8 (word_add m_p (word i))) s2 =
                         read (memory :> bytes8 (word_add m_p (word i))) s)) /\
    (!s. P s ==> byte_list_at m m_p len s) /\
    ensures step P Q R
    ==> ensures step P (\s. byte_list_at m m_p len s /\ Q s) R`,
  REPEAT GEN_TAC THEN REWRITE_TAC[byte_list_at; ensures] THEN STRIP_TAC THEN
  GEN_TAC THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `s:armstate`) THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(REWRITE_RULE[RIGHT_IMP_FORALL_THM] EVENTUALLY_MONO) THEN
  ASM_MESON_TAC[]);;

(* contained reflexivity for 64-bit address regions. *)
let CONTAINED_REFL_64 = prove
 (`!(x:int64) n. contained (x,n) (x,n)`,
  REPEAT GEN_TAC THEN
  ONCE_REWRITE_TAC[WORD_RULE `(x:int64) = word_add x (iword(&0))`] THEN
  MATCH_MP_TAC CONTAINED_SIMPLE_64 THEN INT_ARITH_TAC);;

(* A single byte at base+i (i < n) is contained in the n-byte region at base. *)
let CONTAINED_BYTE_IN_REGION = prove
 (`!(base:int64) (i:num) (n:num).
     i < n ==> contained (word_add base (word i), 1) (base, n)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `contained (word_add base (iword(&i)):int64, 1) (word_add base (iword(&0)), n)`
    MP_TAC THENL
   [MATCH_MP_TAC CONTAINED_SIMPLE_64 THEN ASM_ARITH_TAC;
    REWRITE_TAC[WORD_RULE `word_add base (iword(&0)):int64 = base`;
                WORD_RULE `word_add base (iword(&i)):int64 = word_add base (word i)`]]);;

(* Lift a single preserved bytes64 cell into the POST front. *)
let LIFT_BYTES64_TAC =
  MATCH_MP_TAC ENSURES_ADD_FACT_TO_POST THEN
  CONJ_TAC THENL
   [REWRITE_TAC[SOME_FLAGS; MAYCHANGE; SEQ_ID] THEN
    REWRITE_TAC[GSYM SEQ_ASSOC] THEN PURE_REWRITE_TAC[ASSIGNS_SEQ] THEN
    CONV_TAC (TOP_DEPTH_CONV BETA_CONV) THEN REWRITE_TAC[ASSIGNS_THM] THEN
    REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN REPEAT GEN_TAC THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES]) THEN
    READ_OVER_WRITE_ORTHOGONAL_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [SIMP_TAC[]; ALL_TAC];;

let AES_GCM_ENC_KERNEL_BYTE_LEN_LE_16_PRESENT_CORRECT = prove
 (`!pc (ptr0:int64) (bit_len:int64) (cptr:int64) (xiptr:int64)
       (ivec_ptr:int64) (key_ptr:int64) (htable_ptr:int64)
       (stackpointer:int64)
       (lk_lo:int64) (lk_hi:int64) (rk9:int128)
       (ctr_lo:int64) (ctr_hi:int64) (ctr0:int128)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128) (rk4:int128)
       (rk5:int128) (rk6:int128) (rk7:int128) (rk8:int128)
       (h:int128) (q6_pre:int128) (q7_pre:int128) (initial_tag:int128)
       (pt_in:byte list)
       (b0_lo:int64) (b0_hi:int64) (b1_lo:int64) (b1_hi:int64)
       (b2_lo:int64) (b2_hi:int64) (b3_lo:int64) (b3_hi:int64).
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (htable_ptr, 96) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (ptr0, 64) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (cptr, 16) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (xiptr, 16) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (key_ptr, 256) /\
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc)
                   (word_add ivec_ptr (word 12), 4) /\
    nonoverlapping (cptr, 16) (xiptr, 16) /\
    nonoverlapping (cptr, 16) (word_add ivec_ptr (word 12), 4) /\
    nonoverlapping (xiptr, 16) (word_add ivec_ptr (word 12), 4) /\
    nonoverlapping (ptr0, 64) (cptr, 16) /\
    nonoverlapping (ptr0, 64) (xiptr, 16) /\
    nonoverlapping (ptr0, 64) (word_add ivec_ptr (word 12), 4) /\
    LENGTH pt_in = 16 /\
    1 <= val (word_ushr bit_len 3) /\ val (word_ushr bit_len 3) <= 16
    ==> ensures arm
         (\s. aligned_bytes_loaded s (word pc) aes_gcm_enc_kernel_mc /\
              read PC s = word (pc + 0x2c) /\
              read SP s = word_sub stackpointer (word 128) /\
              read X0 s = ptr0 /\
              read X1 s = bit_len /\
              read X2 s = cptr /\
              read X3 s = xiptr /\
              read X4 s = ivec_ptr /\
              read X5 s = key_ptr /\
              read X6 s = htable_ptr /\
              read X16 s = ivec_ptr /\
              read X8 s = key_ptr /\
              read Q6 s = q6_pre /\
              read Q7 s = q7_pre /\
              read (memory :> bytes32 (word_add key_ptr (word 240))) s = (word 10:32 word) /\
              read (memory :> bytes64 (word_add key_ptr (word 160))) s = lk_lo /\
              read (memory :> bytes64 (word_add key_ptr (word 168))) s = lk_hi /\
              read (memory :> bytes128 (word_add key_ptr (word 144))) s = rk9 /\
              read (memory :> bytes64 ivec_ptr) s = ctr_lo /\
              read (memory :> bytes64 (word_add ivec_ptr (word 8))) s = ctr_hi /\
              read (memory :> bytes128 ivec_ptr) s = ctr0 /\
              read (memory :> bytes128 key_ptr) s = rk0 /\
              read (memory :> bytes128 (word_add key_ptr (word 16))) s = rk1 /\
              read (memory :> bytes128 (word_add key_ptr (word 32))) s = rk2 /\
              read (memory :> bytes128 (word_add key_ptr (word 48))) s = rk3 /\
              read (memory :> bytes128 (word_add key_ptr (word 64))) s = rk4 /\
              read (memory :> bytes128 (word_add key_ptr (word 80))) s = rk5 /\
              read (memory :> bytes128 (word_add key_ptr (word 96))) s = rk6 /\
              read (memory :> bytes128 (word_add key_ptr (word 112))) s = rk7 /\
              read (memory :> bytes128 (word_add key_ptr (word 128))) s = rk8 /\
              read (memory :> bytes128 xiptr) s = initial_tag /\
              read (memory :> bytes128 htable_ptr) s =
                byteswap128 (h_power (ghash_twist h) 0) /\
              read (memory :> bytes128 (word_add htable_ptr (word 32))) s =
                byteswap128 (h_power (ghash_twist h) 1) /\
              read (memory :> bytes128 (word_add htable_ptr (word 48))) s =
                byteswap128 (h_power (ghash_twist h) 2) /\
              read (memory :> bytes128 (word_add htable_ptr (word 80))) s =
                byteswap128 (h_power (ghash_twist h) 3) /\
              read (memory :> bytes64 ptr0) s = b0_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 8))) s = b0_hi /\
              read (memory :> bytes64 (word_add ptr0 (word 16))) s = b1_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 24))) s = b1_hi /\
              read (memory :> bytes64 (word_add ptr0 (word 32))) s = b2_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 40))) s = b2_hi /\
              read (memory :> bytes64 (word_add ptr0 (word 48))) s = b3_lo /\
              read (memory :> bytes64 (word_add ptr0 (word 56))) s = b3_hi /\
              byte_list_at pt_in ptr0 (word 16) s)
         (\s. read PC s = word (pc + 0x970) /\
              byte_list_at
                (int128_to_nist_bytes
                  (aes_gcm_ct_block_at pt_in (word_bytereverse ctr0)
                    (MAP word_bytereverse
                       [rk0;rk1;rk2;rk3;rk4;rk5;rk6;rk7;rk8;rk9;
                        word_join lk_hi lk_lo]) 0))
                cptr (word 16) s /\
              read (memory :> bytes128 xiptr) s =
                word_bytereverse
                  (nist_ghash h (word_bytereverse initial_tag)
                     [word_bytereverse
                       (word_xor (word_insert (word_zx (b0_lo:int64) :int128) (64,64) b0_hi)
                                 (word_bytereverse
                                    (aes128_cipher (aes_gcm_ctr_at (word_bytereverse ctr0) 0)
                                       (MAP word_bytereverse
                                          [rk0;rk1;rk2;rk3;rk4;rk5;rk6;rk7;rk8;rk9;
                                           word_join lk_hi lk_lo]))))]) /\
              (?cf:int32.
                read (memory :> bytes32 (word_add ivec_ptr (word 12))) s =
                  word_subword
                    (word_zx (word_bytereverse (cf:int32)):int64)
                    (0,32):int32))
         (MAYCHANGE [PC; X0; X4; X5; X6; X7; X9; X10; X11; X12; X13;
                     X14; X15; X17; X19] ,,
          MAYCHANGE [Q0; Q1; Q2; Q3; Q4; Q5; Q7; Q8; Q9; Q10; Q11;
                     Q12; Q13; Q14; Q15; Q16; Q17;
                     Q18; Q19; Q20; Q21; Q22; Q23; Q24; Q25;
                     Q26; Q27; Q28; Q29; Q30; Q31] ,,
          MAYCHANGE SOME_FLAGS ,,
          MAYCHANGE [memory :> bytes128 cptr;
                     memory :> bytes128 xiptr] ,,
          MAYCHANGE [memory :> bytes32 (word_add ivec_ptr (word 12))] ,,
          MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* Bring the LE_16 AES wrapper into context. *)
  MP_TAC(SPECL [
      `pc:num`; `ptr0:int64`; `bit_len:int64`; `cptr:int64`; `xiptr:int64`;
      `ivec_ptr:int64`; `key_ptr:int64`; `htable_ptr:int64`;
      `stackpointer:int64`;
      `lk_lo:int64`; `lk_hi:int64`; `rk9:int128`;
      `ctr_lo:int64`; `ctr_hi:int64`; `ctr0:int128`;
      `rk0:int128`; `rk1:int128`; `rk2:int128`; `rk3:int128`; `rk4:int128`;
      `rk5:int128`; `rk6:int128`; `rk7:int128`; `rk8:int128`;
      `h:int128`; `q6_pre:int128`; `q7_pre:int128`; `initial_tag:int128`;
      `b0_lo:int64`; `b0_hi:int64`; `b1_lo:int64`; `b1_hi:int64`;
      `b2_lo:int64`; `b2_hi:int64`; `b3_lo:int64`; `b3_hi:int64`
    ] AES_GCM_ENC_KERNEL_BYTE_LEN_LE_16_BODY_FUNCTIONAL_CLOSED_AES_CORRECT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN
    (FIRST_ASSUM ACCEPT_TAC ORELSE NONOVERLAPPING_TAC ORELSE
     ASM_ARITH_TAC ORELSE ASM_REWRITE_TAC[]);
    ALL_TAC] THEN
  DISCH_TAC THEN
  (* Apply ENSURES_PREPOSTCONDITION_THM with intermediate PRE = blat /\ P_w,
     POST = b0lo_rd /\ b0hi_rd /\ blat /\ POST_w.  Read the wrapper ensures
     from the assumptions at apply-time to build the intermediate predicates. *)
  (fun (asl,w) ->
    let wth = snd(find (fun (_,th) ->
        try fst(dest_const(fst(strip_comb(concl th)))) = "ensures"
        with _ -> false) asl) in
    let args = snd(strip_comb(concl wth)) in
    let pw = el 1 args and postw = el 2 args in
    let sv = `s:armstate` in
    let blat = `byte_list_at pt_in ptr0 (word 16) s` in
    let b0lo = `read (memory :> bytes64 ptr0) s = b0_lo` in
    let b0hi = `read (memory :> bytes64 (word_add ptr0 (word 8))) s = b0_hi` in
    let pinter = mk_abs(sv, mk_conj(blat, mk_comb(pw,sv))) in
    let postinter =
      mk_abs(sv, mk_conj(b0lo, mk_conj(b0hi, mk_conj(blat, mk_comb(postw,sv))))) in
    (MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
     EXISTS_TAC pinter THEN EXISTS_TAC postinter) (asl,w)) THEN
  CONJ_TAC THENL
   [(* PRE-imp: our PRE ==> blat /\ P_w *)
    GEN_TAC THEN BETA_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [(* POST-imp: b0lo /\ b0hi /\ blat /\ POST_w ==> POST_t *)
    GEN_TAC THEN REWRITE_TAC[] THEN BETA_TAC THEN STRIP_TAC THEN
    REPEAT CONJ_TAC THENL
     [(* PC *) FIRST_ASSUM ACCEPT_TAC;
      (* byte_list_at-ct conversion *)
      REWRITE_TAC[byte_list_at] THEN
      SUBGOAL_THEN `val(word 16:int64) = 16` SUBST1_TAC THENL
       [CONV_TAC WORD_REDUCE_CONV; ALL_TAC] THEN
      MP_TAC(ISPECL [
          `cptr:int64`; `b0_lo:int64`; `b0_hi:int64`;
          `word_bytereverse ctr0 :int128`;
          `MAP word_bytereverse
             [rk0;rk1;rk2;rk3;rk4;rk5;rk6;rk7;rk8;rk9;
              (word_join (lk_hi:int64) (lk_lo:int64) :int128)] :int128 list`;
          `pt_in:byte list`; `0`; `x:armstate`]
        READ_BYTES128_EMIT_AS_CT_BLOCK_NIST_BYTES) THEN
      ANTS_TAC THENL
       [CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          MP_TAC(ISPECL [`ptr0:int64`; `b0_lo:int64`; `b0_hi:int64`;
                         `pt_in:byte list`; `0`; `16`; `x:armstate`]
                  PT_BLOCK_AT_FROM_BYTES64_PAIR) THEN
          ANTS_TAC THENL
           [ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
            REWRITE_TAC[WORD_ADD_0] THEN ASM_REWRITE_TAC[] THEN
            UNDISCH_TAC `byte_list_at pt_in ptr0 (word 16) x` THEN
            REWRITE_TAC[byte_list_at] THEN
            CONV_TAC(ONCE_DEPTH_CONV WORD_REDUCE_CONV) THEN
            DISCH_THEN ACCEPT_TAC;
            DISCH_THEN ACCEPT_TAC]];
        DISCH_THEN(fun th -> ASM_REWRITE_TAC[th])];
      (* GHASH *) FIRST_ASSUM ACCEPT_TAC;
      (* ?cf *) ASM_MESON_TAC[]];
    ALL_TAC] THEN
  (* 3rd obligation: ensures (blat /\ P_w) POST_inter MC.  Lift the 3 facts. *)
  LIFT_BYTES64_TAC THEN
  LIFT_BYTES64_TAC THEN
  MATCH_MP_TAC ENSURES_ADD_BYTE_LIST_AT_TO_POST THEN
  CONJ_TAC THENL
   [(* byte window preserved by the frame *)
    REWRITE_TAC[SOME_FLAGS] THEN
    REPEAT GEN_TAC THEN
    REWRITE_TAC[MAYCHANGE; SEQ_ID; GSYM SEQ_ASSOC] THEN
    PURE_REWRITE_TAC[ASSIGNS_SEQ] THEN
    CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
    REWRITE_TAC[ASSIGNS_THM] THEN
    REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
    REPEAT GEN_TAC THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    SUBGOAL_THEN
      `nonoverlapping (word_add ptr0 (word i):int64, 1) (cptr:int64, 16) /\
       nonoverlapping (word_add ptr0 (word i):int64, 1) (xiptr:int64, 16) /\
       nonoverlapping (word_add ptr0 (word i):int64, 1)
                      (word_add ivec_ptr (word 12):int64, 4)`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC NONOVERLAPPING_SUBREGIONS THEN
        MAP_EVERY EXISTS_TAC [`ptr0:int64`; `64`; `cptr:int64`; `16`] THEN
        REPEAT CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          MATCH_MP_TAC CONTAINED_BYTE_IN_REGION THEN
          UNDISCH_TAC `i < val(word 16:int64)` THEN
          CONV_TAC(ONCE_DEPTH_CONV WORD_REDUCE_CONV) THEN ARITH_TAC;
          MATCH_ACCEPT_TAC CONTAINED_REFL_64];
        MATCH_MP_TAC NONOVERLAPPING_SUBREGIONS THEN
        MAP_EVERY EXISTS_TAC [`ptr0:int64`; `64`; `xiptr:int64`; `16`] THEN
        REPEAT CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          MATCH_MP_TAC CONTAINED_BYTE_IN_REGION THEN
          UNDISCH_TAC `i < val(word 16:int64)` THEN
          CONV_TAC(ONCE_DEPTH_CONV WORD_REDUCE_CONV) THEN ARITH_TAC;
          MATCH_ACCEPT_TAC CONTAINED_REFL_64];
        MATCH_MP_TAC NONOVERLAPPING_SUBREGIONS THEN
        MAP_EVERY EXISTS_TAC
          [`ptr0:int64`; `64`; `word_add ivec_ptr (word 12):int64`; `4`] THEN
        REPEAT CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          MATCH_MP_TAC CONTAINED_BYTE_IN_REGION THEN
          UNDISCH_TAC `i < val(word 16:int64)` THEN
          CONV_TAC(ONCE_DEPTH_CONV WORD_REDUCE_CONV) THEN ARITH_TAC;
          MATCH_ACCEPT_TAC CONTAINED_REFL_64]];
      ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[NONOVERLAPPING_CLAUSES]) THEN
    READ_OVER_WRITE_ORTHOGONAL_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [(* PRE ==> byte_list_at *)
    GEN_TAC THEN BETA_TAC THEN SIMP_TAC[];
    ALL_TAC] THEN
  (* finally: ensures (blat /\ P_w) POST_w MC, from the wrapper W by weakening
     PRE to drop blat. *)
  (fun (asl,w) ->
    let wth = snd(find (fun (_,th) ->
        try fst(dest_const(fst(strip_comb(concl th)))) = "ensures"
        with _ -> false) asl) in
    (MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
     EXISTS_TAC (el 1 (snd(strip_comb(concl wth)))) THEN
     CONJ_TAC THENL
      [GEN_TAC THEN SIMP_TAC[];
       MATCH_ACCEPT_TAC wth ORELSE
       (CONV_TAC(ONCE_DEPTH_CONV ETA_CONV) THEN ACCEPT_TAC wth) ORELSE
       ACCEPT_TAC wth]) (asl,w)) );;

(* ========================================================================= *)
(* Phase 11b G3/debt-3 (s243) — int128-level ciphertext-EMIT -> spec block.   *)
(* The GHASH-list elements in the per-band PRESENT POST are in raw EMIT form  *)
(*   word_bytereverse(word_xor (word_insert (word_zx b_lo)(64,64) b_hi)       *)
(*                             (word_bytereverse(aes128_cipher(ctr_at i) ks)))*)
(* This lemma rewrites a single such element to the spec ciphertext block     *)
(* `aes_gcm_ct_block_at pt_in ctr0 ks i`, given the kernel's two 64-bit       *)
(* plaintext half-reads at ptr0+16i / ptr0+16i+8 and the input byte_list_at   *)
(* window (the SAME antecedents PRESENT_CT_BLOCK_AT consumes at the byte      *)
(* layer).  It is the int128-value analogue of                               *)
(* READ_BYTES128_EMIT_AS_CT_BLOCK_NIST_BYTES, used to pin the `cts` argument  *)
(* of nist_ghash to the spec ciphertext blocks (C6b debt 3).                  *)
(* Proof: WORD_BYTEREVERSE_XOR_INSERT_BYTEREVERSE distributes the byte-       *)
(* reverse; aes_gcm_ct_block_at/aes_gcm_ks_block_at unfold; the residual      *)
(* plaintext-block half is exactly PT_BLOCK_AT_FROM_BYTES64_PAIR.             *)
(* ========================================================================= *)

let EMIT_GHASH_ELT_AS_CT_BLOCK_AT = prove
 (`!(ptr0:int64) (b_lo:int64) (b_hi:int64) (ctr0:int128) (ks:int128 list)
     (pt_in:byte list) (i:num) (n:num) (s:armstate).
     read (memory :> bytes64 (word_add ptr0 (word (16*i)))) s = b_lo /\
     read (memory :> bytes64 (word_add ptr0 (word (16*i+8)))) s = b_hi /\
     16 * i + 16 <= LENGTH pt_in /\
     16 * i + 16 <= n /\
     (!k. k < n
          ==> read (memory :> bytes8 (word_add ptr0 (word k))) s = EL k pt_in)
     ==> word_bytereverse
           (word_xor (word_insert (word_zx b_lo :int128) (64,64) b_hi)
                     (word_bytereverse
                        (aes128_cipher (aes_gcm_ctr_at ctr0 i) ks)))
         = aes_gcm_ct_block_at pt_in ctr0 ks i`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[WORD_BYTEREVERSE_XOR_INSERT_BYTEREVERSE;
              aes_gcm_ct_block_at; aes_gcm_ks_block_at] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN
  MATCH_MP_TAC PT_BLOCK_AT_FROM_BYTES64_PAIR THEN
  MAP_EVERY EXISTS_TAC [`ptr0:int64`; `n:num`; `s:armstate`] THEN
  ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* Phase 11b (s211) — per-block ciphertext-EMIT -> byte_list_at conversion.   *)
(* Repackages the s208/s209 bridge hooks                                      *)
(* (READ_BYTES128_EMIT_AS_CT_BLOCK_NIST_BYTES + PT_BLOCK_AT_FROM_BYTES64_PAIR) *)
(* into a single byte_list_at-shaped fact per block, parameterised over the   *)
(* block index k (the s210 LE_16 conversion was hardwired to k=0).            *)
(* ========================================================================= *)

let PRESENT_CT_BLOCK_AT = prove
 (`!(cptr:int64) (ptr0:int64) (b_lo:int64) (b_hi:int64)
     (ctr0:int128) (ks:int128 list) (pt_in:byte list)
     (k:num) (len:int64) (s:armstate).
     read (memory :> bytes128 (word_add cptr (word (16*k)))) s =
       word_xor (word_insert (word_zx b_lo :int128) (64,64) b_hi)
                (word_bytereverse (aes128_cipher (aes_gcm_ctr_at ctr0 k) ks)) /\
     read (memory :> bytes64 (word_add ptr0 (word (16*k)))) s = b_lo /\
     read (memory :> bytes64 (word_add ptr0 (word (16*k+8)))) s = b_hi /\
     16 * k + 16 <= LENGTH pt_in /\
     16 * k + 16 <= val len /\
     byte_list_at pt_in ptr0 len s
     ==> byte_list_at
