  MP_TAC(ISPECL [
      `word_add cptr (word (16*k)):int64`; `b_lo:int64`; `b_hi:int64`;
      `ctr0:int128`; `ks:int128 list`; `pt_in:byte list`; `k:num`; `s:armstate`]
