(* ========================================================================= *)
(* Phase 11b (s211) — CORE PUBLIC byte_list_at presentation theorem, LE_64.   *)
(* Wraps AES_GCM_ENC_KERNEL_BYTE_LEN_LE_64_BODY_FUNCTIONAL_CLOSED_AES_CORRECT  *)
(* (@71876) with byte_list_at-form per-block ciphertext POST conjuncts.       *)
(* Keeps the wrapper's 4 guarded sub-bands (N=1..4); each band's per-block    *)
(* EMIT ciphertext read at cptr+16k is converted to the spec byte form via    *)
(* PRESENT_CT_BLOCK_AT at block index k.  GHASH tag + G3 ?cf carried verbatim.*)
(* ========================================================================= *)

let AES_GCM_ENC_KERNEL_BYTE_LEN_LE_64_PRESENT_CORRECT = prove
 (`!pc (ptr0:int64) (bit_len:int64) (cptr:int64) (xiptr:int64)
       (ivec_ptr:int64) (key_ptr:int64) (htable_ptr:int64)
       (stackpointer:int64)
       (lk_lo:int64) (lk_hi:int64) (rk9:int128)
       (ctr_lo:int64) (ctr_hi:int64) (ctr0:int128)
       (rk0:int128) (rk1:int128) (rk2:int128) (rk3:int128) (rk4:int128)
       (rk5:int128) (rk6:int128) (rk7:int128) (rk8:int128)
       (h:int128) (q6_pre:int128) (q7_pre:int128) (initial_tag:int128)
       (pt_in:byte list)
       (b0_lo:int64) (b0_hi:int64) (b1_lo:int64) (b1_hi:int64)
       (b2_lo:int64) (b2_hi:int64) (b3_lo:int64) (b3_hi:int64).
    nonoverlapping (word pc, LENGTH aes_gcm_enc_kernel_mc) (htable_ptr, 96) /\
