    let postbody = itlist (fun t acc -> mk_conj(t,acc))
                     breads (mk_conj(blat, mk_comb(postw,sv))) in
    let postinter = mk_abs(sv, postbody) in
    (MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
