       REWRITE_TAC[WORD_ADD_0] THEN
       DISCH_THEN MATCH_MP_TAC THEN
       ASM_REWRITE_TAC[] THEN
       CONV_TAC(ONCE_DEPTH_CONV WORD_REDUCE_CONV) THEN ASM_REWRITE_TAC[] THEN
