                                    (word 18446744073709551552:int64))) <= 16
               ==> read (memory :> bytes32 (word_add ivec_ptr (word 12))) s =
                     word_subword
                       (word_zx (word_bytereverse
                          (word_subword
                             (aes_gcm_ctr_at (word_bytereverse ctr0)
