    ARM_STEPS_TAC AES_GCM_ENC_KERNEL_EXEC (13--21) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL [
      REWRITE_TAC[byte_list_at] THEN
      CONV_TAC(ONCE_DEPTH_CONV WORD_REDUCE_CONV) THEN
      CONV_TAC EXPAND_CASES_CONV THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      ASM_REWRITE_TAC[];
      REPEAT CONJ_TAC THEN
      TRY(EXISTS_TAC `cf:int32` THEN REFL_TAC) THEN
      TRY(CONV_TAC WORD_RULE) THEN
      TRY(CONV_TAC WORD_BLAST)]]);;

(* ============================================================================
 * Session 216 — Phase 11b: FUNCTIONAL SUBROUTINE wrapper, byte_len<=64 band.
 *
 * Replays the s215 LE_16 SUBROUTINE pilot to the LE_64 PRESENT core, whose POST
 * carries 4 BAND-GUARDED byte_list_at groups (v<=16 | 16<v<=32 | 32<v<=48 | 48<v,
 * where v = val(word_ushr bit_len 3)), each `guard ==> blats /\ ghash`.  Even the
 * GHASH conjunct sits under each guard; only PC and the ?cf (G3, ivec+12) are
 * unconditional.
 *
 * The LE_16 pilot threaded UNCONDITIONAL facts by unfolding byte_list_at -> 16
 * concrete bytes8 reads BEFORE the epilogue ARM_STEPS (so the simulator forwards
 * them s12 -> s21).  Guarded facts cannot be unfolded unconditionally, so subgoal
 * B here CASE-SPLITS on the band BEFORE stepping the epilogue: in each band the
 * active guarded blats become unconditional (guard discharged by ARITH from the
 * case assumptions), are unfolded to concrete s12 reads, threaded through the
 * epilogue, and reconstructed at s21; inactive bands are vacuous (guard refuted).
 *
 * CRUX GOTCHA: the band guards in the POST are NOT alpha-equivalent to a freshly
 * typed ASM_CASES_TAC term (they print identically but aconv=false — the
 * `val(word_ushr bit_len 3)` subterm differs structurally).  So each cut term is
 * EXTRACTED from the band hypothesis itself (band1: imp w/ non-conj <=16 ante;
 * band2/3: right conjunct of the range ante).
 * ============================================================================ *)
let AES_GCM_ENC_KERNEL_BYTE_LEN_LE_64_SUBROUTINE_CORRECT = prove
 (`!pc (ptr0:int64) (bit_len:int64) (cptr:int64) (xiptr:int64)
       (ivec_ptr:int64) (key_ptr:int64) (htable_ptr:int64)
