    (* Subgoal B: epilogue with band-guarded ct facts. *)
    ALL_TAC] THEN
  (* ---- Subgoal B: thread the 4 band-guarded ct/ghash facts through the epilogue.
     Band-case-split BEFORE stepping. Cut terms EXTRACTED from band hyps so they are
     alpha-identical to the POST guards. ---- *)
  let band_find_nonconj_le16 =
    fun asl -> find (fun (_,th) -> is_imp(concl th) &&
                 (let a=fst(dest_imp(concl th)) in
                  not(is_conj a) && is_binop `(<=):num->num->bool` a &&
                  rand a = `16`)) asl in
  (* Close a single POST conjunct: EXISTS cf for G3; an active guarded band gets its
     guard DISCHed then its (block-blats + ghash) closed via EXPAND_CASES/ASM_REWRITE;
     an inactive guarded band is vacuous via ARITH; a bare forall-block via EXPAND. *)
  let POST_CONJ_TAC : tactic =
    FIRST [
      (EXISTS_TAC `cf:int32` THEN REFL_TAC);
      (CONV_TAC EXPAND_CASES_CONV THEN
       CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN ASM_REWRITE_TAC[] THEN
       NO_TAC);
      (DISCH_TAC THEN ASM_ARITH_TAC);
      (DISCH_TAC THEN REPEAT CONJ_TAC THEN
       TRY(CONV_TAC EXPAND_CASES_CONV THEN
           CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN ASM_REWRITE_TAC[]) THEN
       TRY(ASM_REWRITE_TAC[]) THEN
       TRY(CONV_TAC WORD_RULE) THEN TRY(CONV_TAC WORD_BLAST) THEN NO_TAC);
      (ASM_REWRITE_TAC[] THEN NO_TAC);
      (CONV_TAC WORD_RULE);
      (CONV_TAC WORD_BLAST)] in
  let CLOSE_BAND : tactic =
    (fun (asl,w) ->
       let bands = filter (fun (_,th) ->
          is_imp(concl th) &&
          contains_substring "byte_list_at" (string_of_term(concl th)) &&
          contains_substring "s12" (string_of_term(concl th)) &&
          contains_substring "val (word_ushr bit_len 3)"
             (string_of_term(fst(dest_imp(concl th))))) asl in
       FIRST (map (fun (_,bth) ->
          let g = fst(dest_imp(concl bth)) in
          SUBGOAL_THEN g (fun gth -> STRIP_ASSUME_TAC(MATCH_MP bth gth)) THENL
           [ASM_ARITH_TAC; ALL_TAC]) bands) (asl,w)) THEN
    REPEAT(FIRST_X_ASSUM(MP_TAC o check (fun th ->
        let s = string_of_term (concl th) in
        not(is_imp(concl th)) &&
        contains_substring "byte_list_at" s && contains_substring "cptr" s &&
        contains_substring "s12" s)) THEN
      REWRITE_TAC[byte_list_at] THEN
      CONV_TAC(ONCE_DEPTH_CONV WORD_REDUCE_CONV) THEN
      CONV_TAC(LAND_CONV EXPAND_CASES_CONV) THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      STRIP_TAC) THEN
    RULE_ASSUM_TAC(REWRITE_RULE[fst AES_GCM_ENC_KERNEL_EXEC]) THEN
    ARM_STEPS_TAC AES_GCM_ENC_KERNEL_EXEC (13--21) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THEN POST_CONJ_TAC THEN
    TRY(CONV_TAC WORD_RULE) THEN TRY(CONV_TAC WORD_BLAST) in
  (fun (asl,w) ->
     let (_,b1) = band_find_nonconj_le16 asl in
     ASM_CASES_TAC (fst(dest_imp(concl b1))) (asl,w)) THENL
   [CLOSE_BAND;
    (fun (asl,w) ->
       let (_,b2) = find (fun (_,th) -> is_imp(concl th) &&
                     (let a=fst(dest_imp(concl th)) in is_conj a &&
                      is_binop `(<=):num->num->bool` (rand a) &&
                      rand(rand a) = `32`)) asl in
       ASM_CASES_TAC (rand(fst(dest_imp(concl b2)))) (asl,w)) THENL
    [CLOSE_BAND;
     (fun (asl,w) ->
        let (_,b3) = find (fun (_,th) -> is_imp(concl th) &&
                      (let a=fst(dest_imp(concl th)) in is_conj a &&
                       is_binop `(<=):num->num->bool` (rand a) &&
                       rand(rand a) = `48`)) asl in
        ASM_CASES_TAC (rand(fst(dest_imp(concl b3)))) (asl,w)) THENL
     [CLOSE_BAND; CLOSE_BAND]]]
);;

(* ============================================================================
 * Session 216 — Phase 11b: FUNCTIONAL SUBROUTINE wrapper, (64, 128] band.
 *
 * Wraps AES_GCM_ENC_KERNEL_BYTE_LEN_64_TO_128_PRESENT_CORRECT.  Its POST carries
 * 4 UNCONDITIONAL firstblock byte_list_at groups (blocks 0..3) + ?cf + 4 GHASH-
 * GUARDED bands (each `guard ==> ?cts q*_post. LENGTH cts=4 /\ read xiptr = F`,
 * guard on val(word_sub byte_len_w (word 64))).
